Object.assign(window.TEM8_DICTIONARY, {"experiment":{"media":{"uk":"media/uk/experiment__gb_1.mp3","us":"media/us/experiment__us_1.mp3"},"oxford":{"phon":"ɪkˈsperɪmənt","pos":"noun","senses":[{"en":"a scientific test that is done in order to study what happens and to gain new knowledge","cn":"实验；试验","ex":{"en":"to do/perform/conduct an experiment","cn":"做实验"}},{"en":"a new activity, idea or method that you try out to see what happens or what effect it has","cn":"尝试；试做","ex":{"en":"I've never cooked this before so it's an experiment.","cn":"我以前从未做过这种菜，所以这是一个尝试。"}},{"en":"to do a scientific experiment or experiments","cn":"做试验；进行实验","g":"[intransitive]","ex":{"en":"After experimenting at Columbia University, he realized that fission was the key to releasing nuclear energy.","cn":"在哥伦比亚大学进行实验后，他意识到裂变是释放核能的关键。"},"pos":"verb"},{"en":"to try or test new ideas, methods, etc. to find out what effect they have","cn":"尝试；试用","g":"[intransitive]","ex":{"en":"I experimented until I got the recipe just right.","cn":"我不断地尝试，直至找到正合适的烹饪法为止。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"实验","en":"An experiment is a scientific test which is done in order to discover what happens to something in particular conditions.","ex":{"en":"The astronauts are conducting a series of experiments to learn more about how the body adapts to weightlessness","cn":"那些宇航员正在进行一系列实验，以更多地了解身体如何适应失重状态。"}},{"pos":"VERB 动词","cn":"（用…）做实验","en":"If you experiment with something or experiment on it, you do a scientific test on it in order to discover what happens to it in particular conditions.","ex":{"en":"In 1857 Mendel started experimenting with peas in his monastery garden","cn":"1857年，孟德尔开始在修道院的菜园里用豌豆做实验。"}},{"pos":"N-VAR 可变名词","cn":"试验;试用","en":"An experiment is the trying out of a new idea or method in order to see what it is like and what effects it has.","ex":{"en":"As an experiment, we bought Ted a watch.","cn":"我们试着给特德买了一块手表。"}},{"pos":"VERB 动词","cn":"进行试验;试用","en":"To experiment means to try out a new idea or method to see what it is like and what effects it has.","ex":{"en":"...if you like cooking and have the time to experiment","cn":"如果你喜欢烹饪而且有时间尝试的话"}}]},"examples":[{"en":"He wanted to experiment more with different textures in his paintings.","cn":"他想在自己的绘画中更多地尝试不同的纹理结构。"},{"en":"I experimented until I got the recipe just right.","cn":"我不断地尝试，直至找到正合适的烹饪法为止。"}]},"excellent":{"media":{"uk":"media/uk/excellent__gb_1.mp3","us":"media/us/excellent__us_1.mp3"},"oxford":{"phon":"ˈeksələnt","pos":"adjective","senses":[{"en":"extremely good","cn":"优秀的；杰出的；极好的","lab":"informal","ex":{"en":"an excellent book/article","cn":"优秀的书；出色的文章"}},{"en":"used to show that you are very pleased about something or that you approve of something","cn":"（用以表示愉快或赞同）好极了，妙极了","ex":{"en":"You can all come? Excellent!","cn":"你们都能来？太好了！"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极好的;优秀的;卓越的;杰出的","en":"Something that is excellent is very good indeed.","ex":{"en":"The recording quality is excellent","cn":"录音质量非常好。"}},{"pos":"EXCLAM 感叹语","cn":"（表示赞同）好极了，太好了","en":"Some people say 'Excellent!' to show that they approve of something."}]},"examples":[{"en":"At $300 the bike is excellent value.","cn":"这辆自行车 300 块钱太合算了。"},{"en":"The rooms are excellent value at $20 a night.","cn":"这些房间一晚 20 元太合算了。"}]},"extroverted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"外向的；活泼友好的","en":"Someone who is extroverted is very active, lively, and friendly.","ex":{"en":"Some young people who were easy-going and extroverted as children become self-conscious in early adolescence.","cn":"一些年轻人孩童时脾气随和、性格活泼，刚进入青春期却变得害羞起来。"}}]},"media":{"uk":"media/uk/extroverted__gb_1.mp3","us":"media/us/extroverted__us_1.mp3"},"oxford":{"phon":"ˈekstrəvɜːtɪd","pos":"adjective","senses":[{"en":"lively and confident, and enjoying being with other people","cn":"性格外向者；活泼自信的人","ex":{"en":"He is bold and extroverted.","cn":"他性格大胆、外向。"}}]}},"expense":{"media":{"uk":"media/uk/expense__gb_1.mp3","us":"media/us/expense__us_1.mp3"},"oxford":{"phon":"ɪkˈspens","pos":"noun","senses":[{"en":"the money that you spend on something","cn":"费用；价钱","g":"[uncountable]","ex":{"en":"The garden was transformed at great expense.","cn":"花园改建花了一大笔费用。"}},{"en":"something that makes you spend money","cn":"花钱的东西；开销","g":"[countable, usually singular]","ex":{"en":"Running a car is a big expense.","cn":"养一辆车开销很大。"}},{"en":"money spent in doing a particular job, or for a particular purpose","cn":"开支；花费；费用","g":"[plural]","ex":{"en":"living/medical/travel expenses","cn":"生活费；医疗费；差旅费"}},{"en":"money that you spend while you are working and that your employer will pay back to you later","cn":"（向雇主报销的）费用，开支，花销，业务费用","g":"[plural]","lab":"British English","ex":{"en":"You can claim back your travelling/travel expenses.","cn":"你可以报销差旅费。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"花费;费用;开支","en":"Expense is the money that something costs you or that you need to spend in order to do something.","ex":{"en":"He's bought a specially big TV at vast expense so that everyone can see properly","cn":"他花大价钱买了一台特别大的电视机，这样每个人都能看清楚。"}},{"pos":"N-PLURAL 复数名词","cn":"（由雇主报销的）开支，费用，业务费用","en":"Expenses are amounts of money that you spend while doing something in the course of your work, which will be paid back to you afterwards.","ex":{"en":"As a member of the International Olympic Committee her fares and hotel expenses were paid by the IOC","cn":"作为国际奥林匹克委员会的成员，她的交通费用和酒店住宿费用都由国际奥委会支付。"}},{"pos":"PHRASE 短语","cn":"由…付费","en":"If you do something at someone's expense, they provide the money for it.","ex":{"en":"Should architects continue to be trained for five years at public expense?","cn":"建筑师是否应该继续接受5年的公费培训呢？"}},{"pos":"PHRASE 短语","cn":"拿…开玩笑;以…为嘲弄的对象","en":"If someone laughs or makes a joke at your expense, they do it to make you seem foolish.","ex":{"en":"I think he's having fun at our expense.","cn":"我想他在拿我们寻开心。"}},{"pos":"PHRASE 短语","cn":"以牺牲…的利益为代价","en":"If you achieve something at the expense of someone, you do it in a way which might cause them some harm or disadvantage.","ex":{"en":"But skeptics worry that costs may be trimmed at the expense of the patient","cn":"但是持怀疑态度的人担心费用的削减会以牺牲病人的利益为代价。"}},{"pos":"PHRASE 短语","cn":"以…为代价","en":"If you say that someone does something at the expense of another thing, you are expressing concern at the fact that they are not doing the second thing, because the first thing uses all their resources.","ex":{"en":"They are worth having but not at the expense of better services","cn":"它们值得拥有，但是不能因此放弃更好的服务。"}},{"pos":"PHRASE 短语","cn":"花（大笔）钱做","en":"If you go to the expense of doing something, you do something which costs a lot of money. If you go to great expense to do something, you spend a lot of money in order to achieve it.","ex":{"en":"Why go to the expense of buying an electric saw when you can hire one?","cn":"既然可以租电锯，为什么要花大价钱买一个呢？"}},{"pos":"","cn":"","en":"to spare no expense→see: ;"}]},"examples":[{"en":"They went to all the expense of redecorating the house and then they moved.","cn":"他们不惜一切代价重新装饰这房子，可后来又搬走了。"},{"en":"He built up the business at the expense of his health.","cn":"他以自己的健康为代价逐步建立起这个企业。"}]},"exactly":{"media":{"uk":"media/uk/exactly__gb_1.mp3","us":"media/us/exactly__us_1.mp3"},"oxford":{"phon":"ɪɡˈzæktli","pos":"adverb","senses":[{"en":"used to emphasize that something is correct in every way or in every detail","cn":"精确地；准确地；确切地","ex":{"en":"It's exactly nine o'clock.","cn":"现在是九点整。"}},{"en":"used to ask for more information about something","cn":"（要求得到更多信息）究竟，到底","lab":"informal","ex":{"en":"Where exactly did you stay in France?","cn":"你究竟待在法国什么地方？"}},{"en":"used as a reply, agreeing with what somebody has just said, or emphasizing that it is correct","cn":"（答语，表示赞同或强调正确）一点不错，正是如此，完全正确","ex":{"en":"‘You mean somebody in this room must be the murderer?’ ‘Exactly.’","cn":"“你的意思是这屋子里肯定有人是凶手？”“正是。”"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"精确地;确切地;正好","en":"You use exactly before an amount, number, or position to emphasize that it is no more, no less, or no different from what you are stating.","ex":{"en":"Each corner had a guard tower, each of which was exactly ten meters in height","cn":"每个角落都有一座警戒塔，每座警戒塔正好10米高。"}},{"pos":"ADV 副词","cn":"确实如此/并非如此;正是/不完全是","en":"If you say 'Exactly', you are agreeing with someone or emphasizing the truth of what they say. If you say 'Not exactly', you are telling them politely that they are wrong in part of what they are saying.","ex":{"en":"Eve nodded, almost approvingly. 'Exactly.'","cn":"伊芙几乎赞同地点了点头。“确实如此。”"}},{"pos":"ADV 副词","cn":"不完全是;不完全对","en":"You use not exactly to indicate that a meaning or situation is slightly different from what people think or expect.","ex":{"en":"He's not exactly homeless, he just hangs out in this park.","cn":"确切来说他并不算是无家可归，他只是老在这个公园里转悠。"}},{"pos":"ADV 副词","cn":"根本不；决不","en":"You can use not exactly to show that you mean the opposite of what you are saying.","ex":{"en":"This was not exactly what I wanted to hear","cn":"这根本不是我想听到的。"}},{"pos":"ADV 副词","cn":"（用于问句中，表示不赞成）到底，具体","en":"You use exactly with a question to show that you disapprove of what the person you are talking to is doing or saying.","ex":{"en":"What exactly do you mean?","cn":"你到底什么意思?"}}]},"examples":[{"en":"‘So he told you you'd got the job?’ ‘Not exactly, but he said they were impressed with me.’ “","cn":"如此看来，他对你说你得到这份工作了？” “不完全是这样，不过他说我给他们留下了深刻的印象。”"},{"en":"‘You mean somebody in this room must be the murderer?’ ‘Exactly.’ “","cn":"你的意思是这屋子里肯定有人是凶手？” “正是。”"}]},"explain":{"media":{"uk":"media/uk/explain__gb_1.mp3","us":"media/us/explain__us_1.mp3"},"oxford":{"phon":"ɪkˈspleɪn","pos":"verb","senses":[{"en":"to tell somebody about something in a way that makes it easy to understand","cn":"解释；说明；阐明","g":"[transitive, intransitive]","ex":{"en":"He was trying to explain the difference between hip hop and rap.","cn":"他正在试图解释嘻哈和说唱的区别。"}},{"en":"to give a reason, or be a reason, for something","cn":"说明（…的）原因；解释（…的）理由","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"She tried to explain but he wouldn't listen.","cn":"她试图说明一下原因，可他根本不听。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"解释;说明","en":"If you explain something, you give details about it or describe it so that it can be understood.","ex":{"en":"Not every judge, however, has the ability to explain the law in simple terms","cn":"然而，不是每个法官都能用简单的语言来解释法律。"}},{"pos":"VERB 动词","cn":"解释;辩解;说明…的理由","en":"If you explain something that has happened, you give people reasons for it, especially in an attempt to justify it.","ex":{"en":"'Let me explain, sir.' — 'Don't tell me about it. I don't want to know.'","cn":"“您听我解释，先生。”——“别跟我说，我不想知道。”"}},{"pos":"","cn":"","en":"相关词组：explain away"}]},"examples":[{"en":"I really don't see why I should have to explain myself to you.","cn":"我真不明白我为什么非要向你解释我的行为不可。"},{"en":"Could you explain yourself a little more — I didn't understand.","cn":"请把你的意思说得更清楚一点，我还是不明白。"}]},"exclusion":{"oxford":{"phon":"ɪkˈskluːʒn","pos":"noun","senses":[{"en":"the act of preventing somebody/something from entering a place or taking part in something","cn":"排斥；排除在外","g":"[uncountable]","ex":{"en":"He was disappointed with his exclusion from the England squad.","cn":"他对自己没有入选英格兰队感到失望。"}},{"en":"a person or thing that is not included in something","cn":"不包括在内的人（或事物）；被排除在外的人（或事物）","g":"[countable]","ex":{"en":"Check the list of exclusions in the insurance policy.","cn":"检查一下保险单上的除外责任清单。"}},{"en":"the act of deciding that something is not possible","cn":"排除；认为不可能","g":"[uncountable]","ex":{"en":"the exclusion of robbery as a motive","cn":"排除抢劫动机"}},{"en":"a situation in which a child is banned from attending school because of bad behaviour","cn":"开除学籍","g":"[uncountable, countable]","lab":"British English","ex":{"en":"the exclusion of disruptive students from school","cn":"把捣蛋的学生开除出学校"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"排除;不予考虑","en":"The exclusion of something is the act of deliberately not using, allowing, or considering it.","ex":{"en":"It calls for the exclusion of all commercial lending institutions from the college loan program","cn":"它提倡将所有商贷机构排除在高校贷款计划之外。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"排斥;拒绝","en":"Exclusion is the act of preventing someone from entering a place or taking part in an activity.","ex":{"en":"...women's exclusion from political power","cn":"在政治权力上对女性的排斥"}},{"pos":"PHRASE 短语","cn":"把…排除在外；排除…","en":"If you do one thing to the exclusion of something else, you only do the first thing and do not do the second thing at all.","ex":{"en":"Diane had dedicated her life to caring for him to the exclusion of all else.","cn":"黛安娜一生都在照顾他，对其他一切都无暇顾及。"}}]},"media":{"uk":"media/uk/exclusion__gb_1.mp3","us":"media/us/exclusion__us_1.mp3"},"examples":[{"en":"Two exclusions from one school in the same week is unusual.","cn":"一所学校在一周内就有两起开除学生的事是少有的。"},{"en":"Memories of the past filled her mind to the exclusion of all else.","cn":"她满脑子全是对过去的回忆，其他事情都不想了。"}]},"examination":{"media":{"uk":"media/uk/examination__gb_1.mp3","us":"media/us/examination__us_1.mp3"},"oxford":{"phon":"ɪɡˌzæmɪˈneɪʃn","pos":"noun","senses":[{"en":"a formal written, spoken or practical test, especially at school or college, to see how much you know about a subject, or what you can do","cn":"（笔头、口头或操作）考试","g":"[countable]","lab":"formal","ex":{"en":"successful candidates in GCSE examinations","cn":"通过普通中等教育证书考试的考生"}},{"en":"the act of looking at or considering something very carefully","cn":"审查；调查；考查；考察","g":"[uncountable, countable]","ex":{"en":"Careful examination of the ruins revealed an even earlier temple.","cn":"仔细考察这片废墟后发现了一座更为古老的庙宇。"}},{"en":"a close look at something/somebody, especially to see if there is anything wrong or to find the cause of a problem","cn":"（仔细的）检查，检验","g":"[countable, uncountable]","ex":{"en":"a medical/physical examination","cn":"健康检查"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"考试","en":"An examination is a formal test that you take to show your knowledge or ability in a particular subject, or to obtain a qualification."},{"pos":"N-COUNT 可数名词","cn":"体检；医学检查","en":"If you have a medical examination, a doctor looks at your body, feels it, or does simple tests in order to check how healthy you are."}]},"examples":[{"en":"Careful examination of the ruins revealed an even earlier temple.","cn":"仔细考察这片废墟后发现了一座更为古老的庙宇。"},{"en":"The chapter concludes with a brief examination of some of the factors causing family break-up.","cn":"本章结束时简要考查了引起家庭破裂的某些因素。"}]},"exerted":{"lemma":"exert"},"exceptional":{"media":{"uk":"media/uk/exceptional__gb_1.mp3","us":"media/us/exceptional__us_1.mp3"},"oxford":{"phon":"ɪkˈsepʃənl","pos":"adjective","senses":[{"en":"unusually good","cn":"杰出的；优秀的；卓越的","ex":{"en":"At the age of five he showed exceptional talent as a musician.","cn":"他五岁时就表现出非凡的音乐才能。"}},{"en":"very unusual","cn":"异常的；特别的；罕见的","ex":{"en":"This deadline will be extended only in exceptional circumstances.","cn":"只有在特殊情况下才会延长最后期限。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优异的;非凡的","en":"You use exceptional to describe someone or something that has a particular quality, usually a good quality, to an unusually high degree.","ex":{"en":"...children with exceptional ability","cn":"具有非凡才能的孩子们"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"例外的;特殊的","en":"Exceptional situations and incidents are unusual and only likely to happen very infrequently.","ex":{"en":"...if the courts hold that this case is exceptional","cn":"如果法庭认为这是个特殊案例"}}]},"examples":[{"en":"This deadline will be extended only in exceptional circumstances.","cn":"只有在特殊情况下才会延长最后期限。"},{"en":"At the age of five he showed exceptional talent as a musician.","cn":"他五岁时就表现出非凡的音乐才能。"}]},"extras":{"lemma":"extra","media":{"uk":"media/uk/extra__gb_1.mp3","us":"media/us/extra__us_1.mp3"}},"exploit":{"media":{"uk":"media/uk/exploit__gb_1.mp3","us":"media/us/exploit__us_1.mp3"},"oxford":{"phon":"ɪkˈsplɔɪt","pos":"verb","senses":[{"en":"to treat a person or situation as an opportunity to gain an advantage for yourself","cn":"利用（…为自己谋利）","lab":"disapproving","ex":{"en":"He exploited his father's name to get himself a job.","cn":"他利用他父亲的名声为自己找到一份工作。"}},{"en":"to treat somebody unfairly by making them work and not giving them much in return","cn":"剥削；压榨","lab":"disapproving","ex":{"en":"What is being done to stop employers from exploiting young people?","cn":"目前有什么措施制止雇主剥削年轻人呢？"}},{"en":"to use something well in order to gain as much from it as possible","cn":"运用；利用；发挥","ex":{"en":"She fully exploits the humour of her role in the play.","cn":"她在剧中把她那个角色的幽默发挥得淋漓尽致。"}},{"en":"to develop or use something for business or industry","cn":"开发；开采；开拓","ex":{"en":"No minerals have yet been exploited in Antarctica.","cn":"南极洲的矿藏还未开采。"}},{"en":"a brave, exciting or interesting act","cn":"英勇（或激动人心、引人注目）的行为","ex":{"en":"the daring exploits of Roman heroes","cn":"古罗马英雄的英勇壮举"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"压榨;剥削;占…的便宜","en":"If you say that someone is exploiting you, you think that they are treating you unfairly by using your work or ideas and giving you very little in return.","ex":{"en":"Critics claim he exploited black musicians for personal gain.","cn":"批评家声称他压榨黑人音乐家谋求私利。"}},{"pos":"VERB 动词","cn":"利用；乘（机）","en":"If you say that someone is exploiting a situation, you disapprove of them because they are using it to gain an advantage for themselves, rather than trying to help other people or do what is right.","ex":{"en":"The government and its opponents compete to exploit the troubles to their advantage.","cn":"政府及其反对派竞相利用这些问题为自己谋利。"}},{"pos":"VERB 动词","cn":"充分运用；发挥","en":"If you exploit something, you use it well, and achieve something or gain an advantage from it.","ex":{"en":"You'll need a good aerial to exploit the radio's performance","cn":"你需要弄个好天线来发挥广播的性能。"}},{"pos":"VERB 动词","cn":"开采;开发;利用","en":"To exploit resources or raw materials means to develop them and use them for industry or commercial activities.","ex":{"en":"I think we're being very short sighted in not exploiting our own coal.","cn":"我认为不开采我们自己的煤是非常短视的做法。"}},{"pos":"N-COUNT 可数名词","cn":"英勇行为;功绩;有趣的行为","en":"If you refer to someone's exploits, you mean the brave, interesting, or amusing things that they have done.","ex":{"en":"His wartime exploits were later made into a film.","cn":"他在战争中的英勇行为后来被改编成一部电影。"}}]},"examples":[{"en":"She fully exploits the humour of her role in the play.","cn":"她在剧中把她那个角色的幽默发挥得淋漓尽致。"},{"en":"She realized that her youth and inexperience were being exploited.","cn":"她意识到自己的年轻和缺乏经验正受人利用。"}]},"exhausting":{"media":{"uk":"media/uk/exhausting__gb_1.mp3","us":"media/us/exhausting__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɔːstɪŋ","pos":"adjective","senses":[{"en":"making you feel very tired","cn":"使人疲惫不堪的；令人筋疲力尽的","ex":{"en":"an exhausting day at work","cn":"工作得筋疲力尽的一天"}}]},"examples":[{"en":"I find her exhausting — she never stops talking.","cn":"我发现她真让人疲累 — 她总是不停地说话。"},{"en":"an exhausting day at work","cn":"工作得筋疲力尽的一天"}],"base":"exhaust"},"excel":{"media":{"uk":"media/uk/excel__gb_1.mp3","us":"media/us/excel__us_1.mp3"},"oxford":{"phon":"ɪkˈsel","pos":"verb","senses":[{"en":"to be very good at doing something","cn":"擅长；善于；突出","g":"[intransitive]","ex":{"en":"She has always excelled in foreign languages.","cn":"她的外语从来都是出类拔萃。"}},{"en":"to do extremely well and even better than you usually do","cn":"胜过平时","g":"[transitive]","lab":"British English","ex":{"en":"Rick's cooking was always good, but this time he really excelled himself.","cn":"里克的烹饪技术一直不错，但这次简直是好上加好。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"突出;擅长;胜过（他人）","en":"If someone excels in something or excels at it, they are very good at doing it.","ex":{"en":"Caine has always been an actor who excels in irony","cn":"凯恩向来是个擅长讽刺的演员。"}}]},"examples":[{"en":"Rick's cooking was always good but this time he really excelled himself.","cn":"里克的烹饪技术一直不错，但这次简直是好上加好。"},{"en":"She has always excelled in foreign languages.","cn":"她的外语从来都是出类拔萃。"}]},"exotic":{"media":{"uk":"media/uk/exotic__gb_1.mp3","us":"media/us/exotic__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɒtɪk","pos":"adjective","senses":[{"en":"from or in another country, especially a tropical one; seeming exciting and unusual because it seems to be connected with foreign countries","cn":"来自异国（尤指热带国家）的；奇异的；（貌似有）异国情调的，异国风味的","ex":{"en":"brightly-coloured exotic flowers/plants/birds","cn":"色彩鲜艳的异国花卉／植物／鸟儿"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"具有异国情调的;外来的;奇异的","en":"Something that is exotic is unusual and interesting, usually because it comes from or is related to a distant country.","ex":{"en":"...brilliantly coloured, exotic flowers","cn":"色彩斑斓的奇异花卉"}}]},"examples":[{"en":"She travels to all kinds of exotic locations all over the world.","cn":"她走遍了全世界所有具有奇异风情的地方。"},{"en":"brightly-coloured exotic flowers/plants/birds","cn":"色彩鲜艳的异国花卉/植物/鸟儿"}]},"exclamations":{"lemma":"exclamation"},"experienced":{"media":{"uk":"media/uk/experienced__gb_1.mp3","us":"media/us/experienced__us_1.mp3"},"oxford":{"phon":"ɪkˈspɪəriənst","pos":"adjective","senses":[{"en":"having knowledge or skill in a particular job or activity","cn":"有经验的；熟练的","ex":{"en":"an experienced player/teacher","cn":"经验丰富的选手／教师"}},{"en":"having knowledge as a result of doing something for a long time, or having had a lot of different experiences","cn":"有阅历的；有见识的；老练的","ex":{"en":"She's very young and not very experienced.","cn":"她很年轻，还不太老练。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有经验的;老练的","en":"If you describe someone as experienced, you mean that they have been doing a particular job or activity for a long time, and therefore know a lot about it or are very skilful at it.","ex":{"en":"...lawyers who are experienced in these matters","cn":"在这些问题上颇有经验的律师们"}}]},"examples":[{"en":"She's very young and not very experienced.","cn":"她很年轻，还不太老练。"},{"en":"He's very experienced in looking after animals.","cn":"他养动物很有经验。"}],"base":"experience"},"expert":{"media":{"uk":"media/uk/expert__gb_1.mp3","us":"media/us/expert__us_1.mp3"},"oxford":{"phon":"ˈekspɜːt","pos":"noun","senses":[{"en":"a person with special knowledge, skill or training in something","cn":"专家；行家；能手","ex":{"en":"a legal/security/medical/computer expert","cn":"法律／安全／医疗／计算机专家"}},{"en":"done with, having or involving great knowledge or skill","cn":"熟练的；内行的；专家的；经验（或知识）丰富的","ex":{"en":"to seek expert advice","cn":"征求专家意见"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"行家;专家","en":"An expert is a person who is very skilled at doing something or who knows a lot about a particular subject.","ex":{"en":"Our team of experts will be on hand to offer help and advice between 12 noon and 7pm daily.","cn":"每天中午12点到下午7点，我们的专家小组将随时提供帮助和建议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"技术娴熟的;熟练的;在行的","en":"Someone who is expert at doing something is very skilled at it.","ex":{"en":"The Japanese are expert at lowering manufacturing costs","cn":"日本人在降低制造成本方面很在行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"行家的;内行的","en":"If you say that someone has expert hands or an expert eye, you mean that they are very skilful or experienced in using their hands or eyes for a particular purpose.","ex":{"en":"When the horse suffered a back injury Harvey cured it with his own expert hands","cn":"那匹马背部受伤后，哈维用他内行的双手把它治好了。"}},{"pos":"ADJ 形容词","cn":"专业的;专家的","en":"Expert advice or help is given by someone who has studied a subject thoroughly or who is very skilled at a particular job.","ex":{"en":"You'll also get expert advice on keeping your hair in good condition","cn":"你还会获得有关如何保持良好发质的专家建议。"}}]},"examples":[{"en":"The roads were icy but she stopped the car expertly.","cn":"道路结了冰，可她却非常熟练地把车停了下来。"},{"en":"He's an expert at getting his own way.","cn":"他在如何达到自己的目的方面很在行。"}]},"exchange":{"oxford":{"phon":"ɪksˈtʃeɪndʒ","pos":"noun","senses":[{"en":"an act of giving something to somebody or doing something for somebody and receiving something in return","cn":"交换；互换；交流；掉换","g":"[countable, uncountable]","sc":"giving and receiving","ex":{"en":"The exchange of prisoners took place this morning.","cn":"今天早上交换了俘虏。"}},{"en":"the process of changing an amount of one currency for an equal value of another","cn":"兑换；汇兑","g":"[uncountable]","sc":"of money","ex":{"en":"currency exchange facilities","cn":"货币兑换服务"}},{"en":"an arrangement when two people or groups from different countries visit each other’s homes or do each other’s jobs for a short time","cn":"（不同国家人或团体之间的）交流，互访","g":"[countable]","sc":"between two countries","ex":{"en":"Our school does an exchange with a school in France.","cn":"我们学校与法国的一所学校进行交流。"}},{"en":"a conversation or an argument","cn":"交谈；对话；争论","g":"[countable]","sc":"conversation/argument","ex":{"en":"There was only time for a brief exchange.","cn":"只有简短的交谈时间。"}},{"en":"a building where business people met in the past to buy and sell a particular type of goods","cn":"交易所","g":"[countable]","sc":"building","ex":{"en":"the old Corn Exchange","cn":"古老的谷物交易所"}},{"en":"a place where phone calls are connected so that people can speak to each other","cn":"电话交换台；总机；电话局","g":"[countable]","sc":"telephone"},{"en":"to give something to somebody and at the same time receive the same type of thing from them","cn":"交换；交流；掉换","g":"[transitive]","sc":"give and receive","ex":{"en":"to exchange news/information","cn":"交换新闻/信息"},"pos":"verb"},{"en":"to change an amount of one currency for an equal value of another","cn":"兑换；汇兑","g":"[transitive]","sc":"money","ex":{"en":"Where can I exchange my money?","cn":"我在哪里可以兑换货币？"},"pos":"verb"},{"en":"to give or return something that you have and get something different or better instead","cn":"兑换；交易；更换","g":"[transitive]","sc":"goods","ex":{"en":"If it doesn't fit, take it back and the store will exchange it.","cn":"如果不合适就把它拿回来，商店将给你更换。"},"pos":"verb"},{"en":"when a buyer and seller exchange contracts, especially on the sale of a house or land, they each sign a copy of the contract and give it to the other person","cn":"（尤指买卖房屋或土地时）订立契约","g":"[transitive, intransitive]","lab":"especially British English","sc":"contracts","ex":{"en":"The firm has just exchanged contracts on a nine-acre site.","cn":"该公司刚刚就一块九英亩的土地交换了合同。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"交换;互换","en":"If two or more people exchange things of a particular kind, they give them to each other at the same time.","ex":{"en":"We exchanged addresses and Christmas cards","cn":"我们交换了地址和圣诞贺卡。"}},{"pos":"VERB 动词","cn":"调换，交换，更换（尤指更好或更令人满意的东西）","en":"If you exchange something, you replace it with a different thing, especially something that is better or more satisfactory.","ex":{"en":"...the chance to sell back or exchange goods","cn":"回销或调换商品的机会"}},{"pos":"N-COUNT 可数名词","cn":"短暂的交谈;（常指）口角，争吵","en":"An exchange is a brief conversation, usually an angry one.","ex":{"en":"There've been some bitter exchanges between the two groups.","cn":"两组之间发生过一些激烈的争吵。"}},{"pos":"N-COUNT 可数名词","cn":"交战;交火","en":"An exchange of fire, for example, is an incident in which people use guns or missiles against each other.","ex":{"en":"There was an exchange of fire during which the gunman was wounded","cn":"有过交火，其间那名持枪歹徒受伤了。"}},{"pos":"N-COUNT 可数名词","cn":"（不同国家人们之间的）交流，互访","en":"An exchange is an arrangement in which people from two different countries visit each other's country, to strengthen links between them.","ex":{"en":"...a series of sporting and cultural exchanges with Seoul","cn":"和首尔之间的一系列体育和文化交流"}},{"pos":"N-IN-NAMES 名称名词","cn":"交易大厅;交易所","en":"Exchange is used in the names of some places where people used to trade and do business with each other.","ex":{"en":"...the Royal Exchange.","cn":"皇家交易所"}},{"pos":"N-COUNT 可数名词","cn":"同telephone exchange","en":"The exchange is the same as the telephone exchange ."},{"pos":"PHRASE 短语","cn":"作为交换","en":"If you do or give something in exchange for something else, you do it or give it in order to get that thing.","ex":{"en":"It is illegal for public officials to solicit gifts or money in exchange for favors","cn":"公务员通过索要礼物或钱财作为为他人提供便利的交换是违法的。"}}]},"media":{"uk":"media/uk/exchange__gb_1.mp3","us":"media/us/exchange__us_1.mp3"},"examples":[{"en":"I'll type your report if you'll babysit in exchange.","cn":"如果你愿意代我照看孩子，我就把这个报告给你打出来。"},{"en":"I buy you lunch and you fix my computer. Is that a fair exchange?","cn":"我请你吃午饭，你给我修计算机，这算是公平交易吧？"}]},"executive":{"media":{"uk":"media/uk/executive__gb_1.mp3","us":"media/us/executive__us_1.mp3"},"oxford":{"phon":"ɪɡˈzekjətɪv","pos":"noun","senses":[{"en":"a person who has an important job as a manager of a company or an organization","cn":"（公司或机构的）经理，主管领导，管理人员","g":"[countable]","ex":{"en":"company/corporate/business/industry executives","cn":"公司／企业高管；业务主管；行业高管"}},{"en":"a group of people who run a company or an organization","cn":"（统称公司或机构的）行政领导，领导层","g":"[countable + singular or plural verb]","ex":{"en":"The union’s executive has/have yet to reach a decision.","cn":"工会领导层尚未作出决策。"}},{"en":"the part of a government responsible for putting laws into effect","cn":"（政府的）行政部门","g":"[singular + singular or plural verb]","ex":{"en":"Conservatives are by tradition believers in a strong executive.","cn":"依照传统，保守派相信需要一个强大的行政机构。"}},{"en":"connected with managing a business or an organization, and with making plans and decisions","cn":"经营管理的；经理的；决策的","ex":{"en":"She has an executive position in a finance company.","cn":"她在一家金融公司担任主管。"},"pos":"adjective"},{"en":"having or using the power to put important laws and decisions into effect","cn":"有执行权的；实施的；行政的","ex":{"en":"an executive vice-president/chairman/officer","cn":"执行副总裁／董事长／主管"},"pos":"adjective"},{"en":"expensive; for the use of somebody who is considered important","cn":"高级的；供重要人物使用的","ex":{"en":"an executive car/home","cn":"高级汽车／住宅"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"主管;管理者;经理","en":"An executive is someone who is employed by a business at a senior level. Executives decide what the business should do, and ensure that it is done.","ex":{"en":"...an advertising executive.","cn":"广告主管"}},{"pos":"ADJ 形容词","cn":"管理的;执行的","en":"The executive sections and tasks of an organization are concerned with the making of decisions and with ensuring that decisions are carried out.","ex":{"en":"A successful job search needs to be as well organised as any other executive task","cn":"成功的求职与执行其他任何任务一样，都需要良好的条理性。"}},{"pos":"ADJ 形容词","cn":"高级的;精美时髦的;供主管人员使用的","en":"Executive goods are expensive goods designed or intended for executives and other people at a similar social or economic level.","ex":{"en":"...an executive briefcase.","cn":"高级公文包"}},{"pos":"N-SING 单数名词","cn":"执行委员会；行政委员会","en":"The executive committee or board of an organization is a committee within that organization which has the authority to make decisions and ensures that these decisions are carried out.","ex":{"en":"He sits on the executive committee that manages Lloyds","cn":"他是管理劳埃德保险公司的执行委员会成员。"}},{"pos":"N-SING 单数名词","cn":"（政府的）行政部门","en":"The executive is the part of the government of a country that is concerned with carrying out decisions or orders, as opposed to the part that makes laws or the part that deals with criminals.","ex":{"en":"The government, the executive and the judiciary are supposed to be separate","cn":"政府、行政部门和司法部门应该彼此分离。"}}]},"examples":[{"en":"a chief/senior/top executive in a computer firm","cn":"一家计算机公司的总裁/资深主管/高层主管"},{"en":"The union's executive has/have yet to reach a decision.","cn":"工会领导层还有待作出决策。"}]},"exuberance":{"media":{"uk":"media/uk/exuberance__gb_1.mp3","us":"media/us/exuberance__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"热情洋溢；兴高采烈;喜气洋洋","en":"Exuberance is behaviour which is energetic, excited, and cheerful.","ex":{"en":"Her burst of exuberance and her brightness overwhelmed me.","cn":"她勃发的热情和阳光的性格征服了我。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勃勃生机","en":"If you talk about the exuberance of something, you like it because it is lively, exciting, and full of energy and life.","ex":{"en":"The sheer exuberance of the sculpture was exhilarating.","cn":"那尊雕塑表现出的勃勃生机让人振奋。"}}]},"examples":[{"en":"We can excuse his behaviour as youthful exuberance.","cn":"年轻人精力旺盛，所以他的行为我们可以原谅。"}],"oxford":{"phon":"ɪɡˈzjuːbərəns","pos":"noun","senses":[{"en":"the quality of being full of energy, excitement and happiness","cn":"精力充沛的；热情洋溢的；兴高采烈的","ex":{"en":"We can excuse his behaviour as youthful exuberance.","cn":"我们可以原谅他的行为，只当是年轻人精力旺盛。"}}]}},"expression":{"media":{"uk":"media/uk/expression__gb_1.mp3","us":"media/us/expression__us_1.mp3"},"oxford":{"phon":"ɪkˈspreʃn","pos":"noun","senses":[{"en":"a word or phrase","cn":"词语；措辞；表达方式","g":"[countable]","lab":"informal","sc":"words","ex":{"en":"What's the meaning of the expression ‘on cloud nine’?","cn":"on cloud nine 这个表达是什么意思？"}},{"en":"things that people say, write or do in order to show their feelings, opinions and ideas","cn":"表示；表达；表露","g":"[uncountable, countable]","lab":"formal","sc":"showing feelings/ideas","ex":{"en":"Freedom of expression (= freedom to say what you think) is a basic human right.","cn":"言论自由是基本的人权。"}},{"en":"a look on a person’s face that shows their thoughts or feelings","cn":"表情；神色","g":"[countable]","sc":"on face","ex":{"en":"The actors' gestures and facial expressions are perfect.","cn":"演员的动作和面部表情都很完美。"}},{"en":"a strong show of feeling when you are playing music, speaking, acting, etc.","cn":"（演奏乐曲、说话、表演等时流露的）感情，表情","g":"[uncountable]","sc":"in music/acting","ex":{"en":"Try to put a little more expression into it!","cn":"尽量注入更多的感情！"}},{"en":"a group of signs that represent an idea or a quantity","cn":"式；表达式","g":"[countable]","sc":"mathematics"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"表达;表述","en":"The expression of ideas or feelings is the showing of them through words, actions, or artistic activities.","ex":{"en":"Laughter is one of the most infectious expressions of emotion","cn":"笑是最具感染力的情感表达方式之一。"}},{"pos":"N-VAR 可变名词","cn":"表情;神情","en":"Your expression is the way that your face looks at a particular moment. It shows what you are thinking or feeling.","ex":{"en":"The civil servant's expression, however, did not change, not so much as by a flicker","cn":"然而，那位公务员的表情还是那样，丝毫没变。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（表演、歌唱或演奏时的）情感表现","en":"Expression is the showing of feeling when you are acting, singing, or playing a musical instrument.","ex":{"en":"I don't sing perfectly in tune, but I think I put more expression into my lyrics than a lot of other singers do.","cn":"我唱歌不是特别合拍，但我认为我唱得比其他很多歌手都更富感情。"}},{"pos":"N-COUNT 可数名词","cn":"措词;说法","en":"An expression is a word or phrase.","ex":{"en":"She spoke in a quiet voice but used remarkably coarse expressions.","cn":"她说话声音很小，但是用了些特别粗俗的字眼儿。"}},{"pos":"N-COUNT 可数名词","cn":"（数学中的）表达式","en":"In mathematics, an expression is a symbol or equation which represents a quantity or problem.","ex":{"en":"This forms the basis for our mathematical expression for the electric field.","cn":"这是电场数学表达式的基础。"}}]},"examples":[{"en":"( informal ) He's a pain in the butt, if you'll pardon the expression.","cn":"请原谅我这么说，他是一个讨厌透顶的家伙。"},{"en":"( formal ) The poet's anger finds expression in (= is shown in) the last verse of the poem.","cn":"诗人的愤怒在诗的最后一节表达出来。"}]},"exposure":{"media":{"uk":"media/uk/exposure__gb_1.mp3","us":"media/us/exposure__us_1.mp3"},"oxford":{"phon":"ɪkˈspəʊʒə(r)","pos":"noun","senses":[{"en":"the state of being in a place or situation where there is no protection from something harmful or unpleasant","cn":"面临，遭受（危险或不快）","g":"[uncountable, countable]","lab":"finance","sc":"to something harmful","ex":{"en":"prolonged exposure to harmful radiation","cn":"长时间接触有害辐射"}},{"en":"the fact of having the true facts about somebody/something told after they have been hidden because they are bad, dishonest or illegal","cn":"揭露；曝光","g":"[uncountable, countable]","sc":"showing truth","ex":{"en":"his exposure as a liar and a fraud","cn":"他说谎和欺骗的行径被揭露"}},{"en":"the fact of being discussed or mentioned on television, in newspapers, etc.","cn":"（在电视、报纸等上的）亮相，被报道","g":"[uncountable]","sc":"on TV/in newspapers, etc.","ex":{"en":"Her new movie has had a lot of exposure in the media.","cn":"她的新电影媒体有很多报道。"}},{"en":"the fact of experiencing something new or different","cn":"接触；体验","g":"[uncountable]","sc":"to something new","ex":{"en":"We try to give our children exposure to other cultures.","cn":"我们努力让孩子体验其他文化。"}},{"en":"a medical condition caused by being out in very cold weather for too long without protection","cn":"挨冻；受寒","g":"[uncountable]","sc":"medical condition","ex":{"en":"Two climbers were brought in suffering from exposure.","cn":"两名登山者因冻僵被带了进来。"}},{"en":"the length of time for which light is allowed into the camera when taking a photograph","cn":"曝光时间","g":"[countable]","sc":"photographs","ex":{"en":"I used a long exposure for this one.","cn":"我这张照片用了长曝光。"}},{"en":"a length of film in a camera that is used to take a photograph","cn":"（照一张照片的）软片，底片，胶片","g":"[countable]","sc":"photographs","ex":{"en":"There were three exposures left on the roll of film.","cn":"这卷胶卷还有三张没拍。"}},{"en":"the act of showing something that is usually hidden","cn":"暴露；显露","g":"[uncountable]","sc":"showing something hidden"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"暴露;接触","en":"Exposure to something dangerous means being in a situation where it might affect you.","ex":{"en":"Exposure to lead is known to damage the brains of young children.","cn":"众所周知，接触铅对幼儿的大脑有害。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（身体）受冻","en":"Exposure is the harmful effect on your body caused by very cold weather.","ex":{"en":"He was suffering from exposure and shock but his condition was said to be stable","cn":"他被冻伤了，而且出现了休克，但是据说情况稳定。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"曝光;揭发;揭露","en":"The exposure of a well-known person is the revealing of the fact that they are bad or immoral in some way.","ex":{"en":"...the exposure of Anthony Blunt as a former Soviet spy","cn":"安东尼·布伦特前苏联间谍身份的曝光"}},{"pos":"N-UNCOUNT 不可数名词","cn":"报道；宣传","en":"Exposure is publicity that a person, company, or product receives.","ex":{"en":"All the candidates have been getting an enormous amount of exposure on television and in the press.","cn":"所有候选人都在电视和报刊上频频亮相。"}},{"pos":"N-COUNT 可数名词","cn":"单张胶片","en":"In photography, an exposure is a single photograph.","ex":{"en":"Larger drawings tend to require two or three exposures to cover them.","cn":"较大的图画往往需要两三张胶片才能拍下来。"}},{"pos":"N-VAR 可变名词","cn":"曝光量","en":"In photography, the exposure is the amount of light that is allowed to enter a camera when taking a photograph.","ex":{"en":"A tripod also lets you shoot long exposures at night.","cn":"三脚架也可以让你在晚上长时间曝光。"}}]},"examples":[{"en":"I used a long exposure for this one.","cn":"我这张照片用了长一点的曝光时间。"},{"en":"Two climbers were brought in suffering from exposure.","cn":"两名登山者因冻僵被带了进来。"}]},"exams":{"lemma":"exam"},"exercise":{"media":{"img":["media/pic/keepingfit_comp.jpg","media/thumb/treadmill.jpg"],"uk":"media/uk/exercise__gb_1.mp3","us":"media/us/exercise__us_1.mp3"},"oxford":{"phon":"ˈeksəsaɪz","pos":"noun","senses":[{"en":"physical or mental activity that you do to stay healthy or become stronger","cn":"（身体或脑力的）活动，锻炼，运动","g":"[uncountable]","lab":"British English","sc":"activity/movements","ex":{"en":"Swimming is good exercise.","cn":"游泳是有益的运动。"}},{"en":"a set of movements or activities that you do to stay healthy or develop a skill","cn":"（保持健康或培养技能的）一套动作，训练活动，练习","g":"[countable]","sc":"activity/movements","ex":{"en":"relaxation/stretching exercises","cn":"放松/伸展运动"}},{"en":"a set of questions in a book that tests your knowledge or practises a skill","cn":"习题；练习","g":"[countable]","sc":"questions","ex":{"en":"grammar exercises","cn":"语法练习"}},{"en":"the use of power, a skill, a quality or a right to make something happen","cn":"行使；运用；使用","g":"[uncountable]","sc":"use of power/right/quality","ex":{"en":"the exercise of power by the government","cn":"政府权力的行使"}},{"en":"an activity that is designed to achieve a particular result","cn":"（为达到特定结果的）活动","g":"[countable]","sc":"for particular result","ex":{"en":"a public consultation exercise","cn":"公众咨询活动"}},{"en":"a set of activities for training soldiers","cn":"（士兵的）操练，演习，演练","g":"[countable, usually plural]","sc":"for soldiers","ex":{"en":"military exercises","cn":"军事演习"}},{"en":"ceremonies","cn":"仪式","g":"[plural]","lab":"North American English","sc":"ceremonies","ex":{"en":"college graduation exercises","cn":"大学毕业典礼"}},{"en":"to do sports or other physical activities in order to stay healthy or become stronger; to make an animal do this","cn":"锻炼；训练；操练","g":"[intransitive, transitive]","sc":"do physical activity","ex":{"en":"an hour’s class of exercising to music","cn":"音乐伴奏下的一小时健身操课"},"pos":"verb"},{"en":"to give a part of the body the movement and activity it needs to keep strong and healthy","cn":"锻炼（身体某部位）","g":"[transitive]","sc":"do physical activity","ex":{"en":"These movements will exercise your arms and shoulders.","cn":"这些动作将锻炼你的手臂和肩膀。"},"pos":"verb"},{"en":"to use your power, rights or personal qualities in order to achieve something","cn":"行使；使用；运用","g":"[transitive]","lab":"formal","sc":"use power/right/quality","ex":{"en":"to exercise power/authority/control","cn":"行使权力／权威／控制"},"pos":"verb"},{"en":"if somebody is exercised about something, they are very anxious about it","cn":"焦虑；不安；烦恼","g":"[usually passive]","lab":"formal","sc":"be anxious","ex":{"en":"The public are less exercised about this matter than the media.","cn":"与媒体相比，公众对此事的关注较少。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"运用;行使","en":"If you exercise something such as your authority, your rights, or a good quality, you use it or put it into effect.","ex":{"en":"They are merely exercising their right to free speech","cn":"他们只是在行使他们的言论自由权。"}},{"pos":"VERB 动词","cn":"活动;运动;锻炼","en":"When you exercise, you move your body energetically in order to get fit and to remain healthy.","ex":{"en":"She exercises two or three times a week","cn":"她每周锻炼两三次。"}},{"pos":"VERB 动词","cn":"锻炼（身体部位）","en":"If a movement or activity exercises a part of your body, it keeps it strong, healthy, or in good condition.","ex":{"en":"They call rowing the perfect sport. It exercises every major muscle group.","cn":"他们称划船是最佳运动，它可以锻炼每一处主要肌肉群。"}},{"pos":"N-COUNT 可数名词","cn":"锻炼;练习","en":"Exercises are a series of movements or actions which you do in order to get fit, remain healthy, or practise for a particular physical activity.","ex":{"en":"These stomach exercises will tighten abdominal muscles","cn":"这些腹部练习会增强腹肌。"}},{"pos":"N-COUNT 可数名词","cn":"演习;操练","en":"Exercises are military activities and operations which are not part of a real war, but which allow the armed forces to practise for a real war.","ex":{"en":"General Powell predicted that in the future it might even be possible to stage joint military exercises","cn":"鲍威尔将军预测将来甚至可能举行联合军事演习。"}},{"pos":"N-COUNT 可数名词","cn":"练习;习题","en":"An exercise is a short activity or piece of work that you do, for example in school, which is designed to help you learn a particular skill.","ex":{"en":"Try working through the opening exercises in this chapter","cn":"做一做本章节的开篇习题。"}},{"pos":"N-PLURAL 复数名词","cn":"仪式；典礼","en":"Exercises is an official ceremony, in which people make speeches and present awards.","ex":{"en":"Vicky and Gary attended the graduation exercises at Columbia.","cn":"维基和加里参加了哥伦比亚大学的毕业典礼。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指非预期的）活动，情况","en":"If you describe an activity as an exercise in a particular quality or result, you mean that it has that quality or result, especially when it was not intended to have it.","ex":{"en":"Her morning was an exercise in indecision. She tried on everything in her closet but couldn't remember what he'd liked","cn":"她整个早晨都犹豫不决。她试穿了衣橱中的所有衣服，却不记得他喜欢哪一件。"}},{"pos":"VERB 动词","cn":"使担忧;使不安","en":"If something exercises you or your mind, you think or talk about it a great deal, especially because you are worried or concerned about it.","ex":{"en":"This has been a major problem exercising the minds of scientists around the world","cn":"这一直是困扰全世界科学家的一个重要问题。"}}]},"examples":[{"en":"When she appeared in court she exercised her right to remain silent.","cn":"她出庭时行使了自己保持沉默的权利。"},{"en":"In the end it proved a pointless exercise.","cn":"这最终证明是一项毫无意义的活动。"}]},"exploding":{"lemma":"explode"},"except":{"media":{"uk":"media/uk/except__gb_1.mp3","us":"media/us/except__us_1.mp3"},"oxford":{"phon":"ɪkˈsept","pos":"preposition","senses":[{"en":"used before you mention the only thing or person about which a statement is not true","cn":"（用于所言不包括的人或事物前）除…之外","ex":{"en":"We work every day except Sunday.","cn":"我们除星期天外每天都工作。"}},{"en":"used before you mention something that makes a statement not completely true","cn":"除了；只是","ex":{"en":"I didn't tell him anything except that I needed the money.","cn":"我什么都没告诉他，只是说我需要钱。"},"pos":"conjunction"},{"en":"to not include somebody/something","cn":"不包括；不计；把…除外","ex":{"en":"Children under five are excepted from the survey.","cn":"五岁以下的儿童不在调查之列。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"除了…之外","en":"You use except to introduce the only thing or person that a statement does not apply to, or a fact that prevents a statement from being completely true.","ex":{"en":"I wouldn't have accepted anything except a job in Europe","cn":"除了到欧洲工作外，我本来什么都不会接受。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除了;除…之外;唯有","en":"You use except for to introduce the only thing or person that prevents a statement from being completely true.","ex":{"en":"He hadn't eaten a thing except for one forkful of salad","cn":"除了一餐叉色拉，他什么都没吃。"}}]},"examples":[{"en":"The sanctions ban the sale of any products excepting medical supplies and food.","cn":"国际制裁禁止销售医药用品和食物以外的任何产品。"},{"en":"Our dresses were the same except mine was red.","cn":"我们的连衣裙是一样的，只是我的那件是红色。"}]},"excellence":{"media":{"uk":"media/uk/excellence__gb_1.mp3","us":"media/us/excellence__us_1.mp3"},"oxford":{"phon":"ˈeksələns","pos":"noun","senses":[{"en":"the quality of being extremely good","cn":"优秀；杰出；卓越","ex":{"en":"a reputation for academic excellence","cn":"因学术上的杰出成就而获得的声誉"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"优秀;卓越;杰出","en":"If someone or something has the quality of excellence, they are extremely good in some way.","ex":{"en":"...the top US award for excellence in journalism and the arts.","cn":"美国新闻和艺术的最高杰出成就奖"}}]},"examples":[{"en":"The hospital is recognized as a centre of excellence in research and teaching.","cn":"这所医院已被确认为成就卓著的教学和研究中心。"},{"en":"a reputation for academic excellence","cn":"因学术上的杰出成就而获得的声誉"}]},"exaggeration":{"media":{"uk":"media/uk/exaggeration__gb_1.mp3","us":"media/us/exaggeration__us_1.mp3"},"oxford":{"phon":"ɪɡˌzædʒəˈreɪʃn","pos":"noun","senses":[{"en":"a statement or description that makes something seem larger, better, worse or more important than it really is; the act of making a statement like this","cn":"夸张；夸大；言过其实","ex":{"en":"a slight/gross/wild exaggeration","cn":"有点／明显的／过于夸张"}}]},"examples":[{"en":"It's no exaggeration to say that most students have never read a complete Shakespeare play.","cn":"说大多数同学从未读过一部完整的莎士比亚戏剧一点也不夸张。"},{"en":"It would be an exaggeration to say I knew her well — I only met her twice.","cn":"说我非常了解她不免言过其实，我只见过她两次。"}]},"excuse":{"media":{"uk":"media/uk/excuse__gb_1.mp3","us":"media/us/excuse__us_1.mp3"},"oxford":{"phon":"ɪkˈskjuːs","pos":"noun","senses":[{"en":"a reason, either true or invented, that you give to explain or defend your behaviour","cn":"借口；理由；辩解","ex":{"en":"Late again! What's your excuse this time?","cn":"又迟到了！你这次有什么借口？"}},{"en":"a good reason that you give for doing something that you want to do for other reasons","cn":"（正当的）理由，借口","ex":{"en":"Eating ice cream for a sore throat isn't really a cure, but I like it, so any excuse!","cn":"吃冰淇淋治疗喉咙痛并不能真正治愈，但我喜欢它，所以有任何借口！"}},{"en":"a very bad example of something","cn":"拙劣样品；蹩脚货","ex":{"en":"Why get involved with that pathetic excuse for a human being?","cn":"为什么要与那个讨厌的家伙混在一起？"}},{"en":"a note written by a parent or doctor to explain why a student cannot go to school or somebody cannot go to work","cn":"假条（家长或医生写明请假原因）","lab":"North American English"},{"en":"to forgive somebody for something that they have done, for example not being polite or making a small mistake","cn":"原谅；宽恕","lab":"British English","ex":{"en":"Please excuse the mess.","cn":"这里凌乱不堪，请见谅。"},"pos":"verb"},{"en":"to make your or somebody else’s behaviour seem less offensive by finding reasons for it","cn":"为…辩解（或找理由）","ex":{"en":"Nothing can excuse such rudeness.","cn":"如此粗鲁无礼不能原谅。"},"pos":"verb"},{"en":"to allow somebody to leave; to say in a polite way that you are leaving","cn":"准许…离开；请求准予离开；（离开前）请求原谅","ex":{"en":"Now if you'll excuse me, I'm a very busy man.","cn":"如果可以，我先行一步了。我很忙。"},"pos":"verb"},{"en":"to allow somebody to not do something that they should normally do","cn":"同意免除；同意免做","g":"[usually passive]","ex":{"en":"She was excused from giving evidence because of her age.","cn":"她因年龄关系获准免于作证。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"借口;理由;辩解","en":"An excuse is a reason which you give in order to explain why something has been done or has not been done, or in order to avoid doing something.","ex":{"en":"It is easy to find excuses for his indecisiveness","cn":"为他的犹豫不决寻找借口是很容易的。"}},{"pos":"VERB 动词","cn":"（尤指别人不赞同时）为…辩解，为…寻找理由","en":"To excuse someone or excuse their behaviour means to provide reasons for their actions, especially when other people disapprove of these actions.","ex":{"en":"He excused himself by saying he was 'forced to rob to maintain my wife and cat'","cn":"他辩解说自己是“为了供养妻子和猫儿被迫去抢劫的”。"}},{"pos":"VERB 动词","cn":"原谅;宽恕","en":"If you excuse someone for something wrong that they have done, you forgive them for it.","ex":{"en":"Many people might have excused them for shirking some of their responsibilities.","cn":"很多人可能已经原谅了他们逃避责任的行为。"}},{"pos":"VERB 动词","cn":"使免除（责任、义务等）","en":"If someone is excused from a duty or responsibility, they are told that they do not have to carry it out.","ex":{"en":"She is usually excused from her duties during the school holidays","cn":"在学校放假期间，她通常不必担负职责。"}},{"pos":"VERB 动词","cn":"准许…离开;让…离开","en":"If you excuse yourself, you use a phrase such as 'Excuse me' as a polite way of saying that you are about to leave.","ex":{"en":"He excused himself and went up to his room.","cn":"他告辞后回到他楼上的房间。"}},{"pos":"CONVENTION 惯用语","cn":"对不起，劳驾，打扰一下（用于礼貌地引起注意，尤其是要提问时）","en":"You say 'Excuse me' when you want to politely get someone's attention, especially when you are about to ask them a question.","ex":{"en":"Excuse me, but are you Mr Honig?","cn":"请问，您是霍尼格先生吗？"}},{"pos":"CONVENTION 惯用语","cn":"对不起，抱歉（用于因打扰或打断对方而道歉）","en":"You use excuse me to apologize to someone when you have disturbed or interrupted them.","ex":{"en":"Excuse me interrupting, but there's a thing I feel I've got to say.","cn":"抱歉打断一下，我觉得有件事我得说。"}},{"pos":"CONVENTION 惯用语","cn":"对不起，抱歉（用于礼貌地表示要离开或者停止和对方交谈）","en":"You use excuse me or a phrase such as if you'll excuse me as a polite way of indicating that you are about to leave or that you are about to stop talking to someone.","ex":{"en":"'Excuse me,' she said to Jarvis, and left the room","cn":"“抱歉出去一下，”她对贾维斯说，然后离开了房间。"}},{"pos":"CONVENTION 惯用语","cn":"对不起，抱歉（用于表示反对）","en":"You use excuse me, but to indicate that you are about to disagree with someone.","ex":{"en":"Excuse me, but I want to know what all this has to do with us.","cn":"抱歉，我想知道所有这些和我们有什么关系。"}},{"pos":"CONVENTION 惯用语","cn":"对不起，抱歉，借过（用于因为撞到某人或者在人群中挤过时表示道歉）","en":"You say excuse me to apologize when you have bumped into someone, or when you need to move past someone in a crowd.","ex":{"en":"Saying excuse me, pardon me, Seaton pushed his way into the crowded living room.","cn":"西顿一边说对不起、借过，一边挤过人群进入拥挤的客厅。"}},{"pos":"CONVENTION 惯用语","cn":"抱歉，对不起（用于为打嗝、打喷嚏等失礼行为道歉）","en":"You say excuse me to apologize when you have done something slightly embarrassing or impolite, such as burping, hiccupping, or sneezing."},{"pos":"CONVENTION 惯用语","cn":"对不起，请再说一遍","en":"You say 'Excuse me?' to show that you want someone to repeat what they have just said."}]},"examples":[{"en":"You must excuse my father — he's not always that rude.","cn":"你一定要原谅我父亲，他并不总是那样粗暴无礼。"},{"en":"‘Excuse me for a moment,’ she said and left the room.","cn":"她说了声“很抱歉，失陪一会儿”就离开了房间。"}]},"excessively":{"oxford":{"phon":"ɪkˈsesɪvli","pos":"adverb","senses":[{"en":"to a much greater level or degree than seems reasonable or appropriate","cn":"过分的；过度的","ex":{"en":"excessively high prices","cn":"过高的价格"}}]},"media":{"uk":"media/uk/excessively__gb_1.mp3","us":"media/us/excessively__us_1.mp3"},"examples":[{"en":"excessively high prices","cn":"过高的价格"},{"en":"$15 for two beers seems a little excessive.","cn":""}]},"expectancy":{"media":{"uk":"media/uk/expectancy__gb_1.mp3","us":"media/us/expectancy__us_1.mp3"},"oxford":{"phon":"ɪkˈspektənsi","pos":"noun","senses":[{"en":"the state of expecting or hoping that something, especially something good or exciting, will happen","cn":"预料；预期；期待；盼望","ex":{"en":"There was an air of expectancy among the waiting crowd.","cn":"等待的人群心怀期盼。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"期待;期望","en":"Expectancy is the feeling or hope that something exciting, interesting, or good is about to happen.","ex":{"en":"The supporters had a tremendous air of expectancy.","cn":"支持者们充满了期待。"}}]},"examples":[{"en":"There was an air of expectancy among the waiting crowd.","cn":"等待的人群有一种期盼的心情。"},{"en":"I saw the look of expectancy in the children’s eyes.","cn":"我从孩子们的眼神中看到了期盼。"}]},"explosion":{"media":{"uk":"media/uk/explosion__gb_1.mp3","us":"media/us/explosion__us_1.mp3"},"oxford":{"phon":"ɪkˈspləʊʒn","pos":"noun","senses":[{"en":"the sudden violent bursting and loud noise of something such as a bomb exploding; the act of deliberately causing something to explode","cn":"爆炸，爆破，爆裂（声）","g":"[countable, uncountable]","ex":{"en":"a bomb/nuclear/gas explosion","cn":"炸弹／核／气体爆炸"}},{"en":"a large, sudden or rapid increase in the amount or number of something","cn":"突增；猛增；激增","g":"[countable]","ex":{"en":"a population explosion","cn":"人口激增"}},{"en":"a sudden, violent expression of emotion, especially anger","cn":"（感情，尤指愤怒的）突然爆发，迸发","g":"[countable]","lab":"formal","ex":{"en":"Do you know what brought on that explosion?","cn":"你知道爆炸发生的原因是什么吗？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"爆炸","en":"An explosion is a sudden, violent burst of energy, for example one caused by a bomb.","ex":{"en":"After the second explosion, all of London's main train and subway stations were shut down","cn":"第二次爆炸后，伦敦所有的主要火车站和地铁站都关闭了。"}},{"pos":"N-VAR 可变名词","cn":"爆破;引爆","en":"Explosion is the act of deliberately causing a bomb or similar device to explode.","ex":{"en":"Bomb disposal experts blew up the bag in a controlled explosion","cn":"拆弹专家对那个袋子进行了控制爆破。"}},{"pos":"N-COUNT 可数名词","cn":"激增;骤增","en":"An explosion is a large rapid increase in the number or amount of something.","ex":{"en":"The study also forecast an explosion in the diet soft-drink market","cn":"该研究还预测低糖软饮料市场将迅猛增长。"}},{"pos":"N-COUNT 可数名词","cn":"（感情的）迸发，突然发作;（尤指）勃然大怒","en":"An explosion is a sudden violent expression of someone's feelings, especially anger.","ex":{"en":"Every time they met, Myra anticipated an explosion","cn":"他们每次见面，迈拉都预料到会发火。"}},{"pos":"N-COUNT 可数名词","cn":"（抗议、暴力等的）爆发","en":"An explosion is a sudden and serious political protest or violence.","ex":{"en":"They warned him that a referendum might cause an explosion in the country.","cn":"他们警告他说全民公决可能会引发国内暴乱。"}},{"pos":"N-COUNT 可数名词","cn":"爆炸声;轰然巨响","en":"An explosion is a sudden very loud noise.","ex":{"en":"There was an explosion of music.","cn":"突然爆发出一阵震耳欲聋的音乐声。"}}]},"examples":[{"en":"Bomb Squad officers carried out a controlled explosion of the device.","cn":"炸弹处理小组人员在受控条件下引爆了这一装置。"},{"en":"There were two loud explosions and then the building burst into flames.","cn":"两声巨响之后建筑物便燃烧起来。"}]},"explorer":{"media":{"uk":"media/uk/explorer__gb_1.mp3","us":"media/us/explorer__us_1.mp3"},"oxford":{"phon":"ɪkˈsplɔːrə(r)","pos":"noun","senses":[{"en":"a person who travels to places where few people have been before or places that are unknown to them, in order to find out more about them","cn":"探险者；勘探者；考察者","ex":{"en":"Early explorers traded directly with Indigenous people.","cn":"早期的探险家直接与原住民进行贸易。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"探险家;探险者","en":"An explorer is someone who travels to places about which very little is known, in order to discover what is there."}]}},"excerpt":{"media":{"uk":"media/uk/excerpt__gb_1.mp3","us":"media/us/excerpt__us_1.mp3"},"oxford":{"phon":"ekˈsɜːpt","pos":"verb","senses":[{"en":"to take a short piece of writing, music, film, etc. from a longer whole","cn":"摘录；节选；（音乐、电影的）片段","ex":{"en":"The document was excerpted from an unidentified FBI file.","cn":"文件摘自来源不明的联邦调查局档案。"}},{"en":"a short piece of writing, music, film, etc. taken from a longer whole","cn":"摘录；节选；（音乐、电影的）片段","ex":{"en":"Read the following excerpt from one of Milton’s poems.","cn":"阅读以下弥尔顿一首诗的摘录。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摘录;节选;选段","en":"An excerpt is a short piece of writing or music which is taken from a larger piece.","ex":{"en":"...an excerpt from Tchaikovsky's Nutcracker.","cn":"柴可夫斯基的《胡桃夹子》选段"}},{"pos":"V-PASSIVE 被动动词","cn":"摘录;节选","en":"If a long piece of writing or music is excerpted, short pieces from it are printed or played on their own.","ex":{"en":"The readings you heard earlier were excerpted from a new oral history of Pearl Harbor.","cn":"你之前听到的朗读片段节选自一部新的珍珠港口述史。"}}]},"examples":[{"en":"The document was excerpted from an unidentified FBI file.","cn":"此文件摘自来源不明的联邦调查局档案。"},{"en":"An excerpt of the speech appeared in the Sunday paper.","cn":"演讲的节录刊登在周日报纸上了。"}]},"extra-curricular":{"oxford":{"phon":"","pos":"adj.","senses":[{"en":"not part of the usual course of work or studies at a school or college","cn":"课外的；课程以外的"}]},"media":{"uk":"media/uk/extra_curricular_1_gb_1.mp3","us":"media/us/extra_curricular_1_us_1.mp3"},"examples":[{"en":"She's involved in many extra-curricular activities.","cn":"她参加了许多课外活动。"}]},"extended":{"media":{"uk":"media/uk/extended__gb_1.mp3","us":"media/us/extended__us_1.mp3"},"oxford":{"phon":"ɪkˈstendɪd","pos":"adjective","senses":[{"en":"long or longer than usual or expected","cn":"延长了的；扩展了的","ex":{"en":"an extended lunch hour","cn":"延长了的午餐时间"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（时间）长的，延长的","en":"If something happens for an extended period of time, it happens for a long period of time.","ex":{"en":"Obviously, any child who receives dedicated teaching over an extended period is likely to improve.","cn":"很明显，任何长期接受用心教育的孩子都有可能取得进步。"}}]},"examples":[{"en":"an extended lunch hour","cn":"延长了的午餐时间"},{"en":"The computer uses extended memory.","cn":"计算机使用扩展内存。"}],"base":"extend"},"exaggerating":{"lemma":"exaggerate"},"extra":{"media":{"uk":"media/uk/extra__gb_1.mp3","us":"media/us/extra__us_1.mp3"},"oxford":{"phon":"ˈekstrə","pos":"adjective","senses":[{"en":"more than is usual, expected, or than exists already","cn":"额外的；分外的；外加的；附加的","ex":{"en":"extra money/cash/funding","cn":"额外的钱／现金／资金"}},{"en":"behaving in a way that is too dramatic or shows too much effort","cn":"行为方式过于戏剧化或表现出过多的努力","lab":"slang","ex":{"en":"Calm down—you're being so extra right now.","cn":"冷静点——你现在太多余了。"}},{"en":"a thing that is added to something that is not usual, standard or necessary and that costs more","cn":"额外的事物；另外收费的事物","lab":"British English","ex":{"en":"The monthly fee is fixed and there are no hidden extras (= unexpected costs).","cn":"月费是固定的，没有未言明的额外开支。"},"pos":"noun"},{"en":"a person who is employed to play a very small part in a film, usually as a member of a crowd","cn":"（电影里的）临时演员，群众演员","ex":{"en":"We need hundreds of extras for the battle scenes.","cn":"我们拍战斗场面需要上百的临时演员。"},"pos":"noun"},{"en":"in addition; more than is usual, expected or exists already","cn":"额外；另外；外加","ex":{"en":"to pay/cost extra","cn":"另付费；额外花费"},"pos":"adverb"},{"en":"more than usually","cn":"特别；格外；分外","ex":{"en":"You need to be extra careful not to make any mistakes.","cn":"你要格外小心，别犯错误。"},"pos":"adverb"},{"en":"outside; beyond","cn":"在…之外；超出；越出","ex":{"en":"extramarital sex","cn":"婚外性行为"},"pos":"prefix"},{"en":"very; more than usual","cn":"非常；格外；十分","lab":"informal","ex":{"en":"extra-thin","cn":"特别瘦"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"额外的;外加的","en":"You use extra to describe an amount, person, or thing that is added to others of the same kind, or that can be added to others of the same kind.","ex":{"en":"Police warned motorists to allow extra time to get to work","cn":"警方告诫驾车者出门上班要留出富余时间。"}},{"pos":"ADJ 形容词","cn":"费用另计的；额外收费的","en":"If something is extra, you have to pay more money for it in addition to what you are already paying for something.","ex":{"en":"For foreign orders postage is extra","cn":"国外订单邮费另计。"}},{"pos":"N-COUNT 可数名词","cn":"额外费用","en":"Extras are additional amounts of money that are added to the price that you have to pay for something.","ex":{"en":"She is disgusted by big hotels adding so many extras to the bill that it nearly doubles","cn":"她非常厌恶大酒店额外收取这么多费用，账单金额都快翻倍了。"}},{"pos":"N-COUNT 可数名词","cn":"额外之物;附加物","en":"Extras are things which are not necessary in a situation, activity, or object, but which make it more comfortable, useful, or enjoyable.","ex":{"en":"Optional extras include cooking tuition at a top restaurant","cn":"可选的额外项目包括在顶级餐厅学习厨艺。"}},{"pos":"N-COUNT 可数名词","cn":"（电影中的）临时演员，群众演员","en":"The extras in a film are the people who play unimportant parts, for example as members of a crowd."},{"pos":"ADV 副词","cn":"格外;特别","en":"You can use extra in front of adjectives and adverbs to emphasize the quality that they are describing.","ex":{"en":"I'd have to be extra careful","cn":"我不得不格外小心。"}},{"pos":"","cn":"","en":"to go the extra mile→see: ;"}]},"examples":[{"en":"The government has promised an extra £1 billion for health care.","cn":"政府承诺为医疗保健再拨款 10 亿英镑。"},{"en":"The rate for a room is £30, but breakfast is extra.","cn":"一个房间收费 30 英镑，但早餐另付。"}]},"explode":{"oxford":{"phon":"ɪkˈspləʊd","pos":"verb","senses":[{"en":"to burst (= break apart) or make something burst loudly and violently, causing damage","cn":"爆炸；爆破；爆裂","g":"[intransitive, transitive]","sc":"break apart violently","ex":{"en":"A second bomb exploded in a crowded market.","cn":"又有一颗炸弹在人员密集的市场里爆炸了。"}},{"en":"to suddenly become very angry or dangerous","cn":"勃然（大怒）；大发（雷霆）；突然发生（危险）","g":"[intransitive, transitive]","sc":"get angry/dangerous","ex":{"en":"Tension between the two sides could explode at any time.","cn":"双方之间的紧张关系随时可能爆发。"}},{"en":"to suddenly express an emotion","cn":"突然爆发，迸发（感情）","g":"[intransitive]","sc":"express emotion","ex":{"en":"We all exploded into wild laughter.","cn":"我们都一下子大笑起来。"}},{"en":"to suddenly and quickly do something; to move suddenly with a lot of force","cn":"突然做起…来；突然活跃起来","g":"[intransitive]","sc":"move suddenly","ex":{"en":"After ten minutes the game exploded into life.","cn":"比赛在十分钟后突然激烈起来。"}},{"en":"to make a sudden very loud noise","cn":"突然发出巨响","g":"[intransitive]","sc":"make loud noise","ex":{"en":"Thunder exploded overhead.","cn":"雷声在头顶上炸开。"}},{"en":"to increase suddenly and very quickly in number","cn":"突增；激增","g":"[intransitive]","sc":"increase quickly","ex":{"en":"the exploding world population","cn":"迅猛增长的世界人口"}},{"en":"to show that something is not true, especially something that people believe","cn":"推翻；驳倒；破除","g":"[transitive]","sc":"show something is not true","ex":{"en":"At last, a women's magazine to explode the myth that thin equals beautiful.","cn":"终于有一家女性杂志起来推翻瘦就是美的迷思。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）爆炸；引爆","en":"If an object such as a bomb explodes or if someone or something explodes it, it bursts loudly and with great force, often causing damage or injury.","ex":{"en":"They were clearing up when the second bomb exploded","cn":"他们正在清理时，第二颗炸弹爆炸了。"}},{"pos":"VERB 动词","cn":"（感情）爆发；迸发","en":"If someone explodes, they express strong feelings suddenly and violently.","ex":{"en":"Do you fear that you'll burst into tears or explode with anger in front of her?","cn":"你担心会在她面前放声大哭或是勃然大怒吗？"}},{"pos":"VERB 动词","cn":"激增;骤增","en":"If something explodes, it increases suddenly and rapidly in number or intensity.","ex":{"en":"The population explodes to 40,000 during the tourist season","cn":"旅游季节，人口激增至4万。"}},{"pos":"VERB 动词","cn":"推翻（理论);破除（神话）","en":"If someone explodes a theory or myth, they prove that it is wrong or impossible.","ex":{"en":"Electricity privatisation has exploded the myth of cheap nuclear power","cn":"电力私有化打破了关于廉价核能的神话。"}},{"pos":"VERB 动词","cn":"突发巨响;响声大作","en":"If something explodes, it makes a sudden very loud noise.","ex":{"en":"She heard laughter explode, then die.","cn":"她听到有人爆笑了一阵，后来就没声音了。"}}]},"media":{"uk":"media/uk/explode__gb_1.mp3","us":"media/us/explode__us_1.mp3"},"examples":[{"en":"There was a huge bang as if someone had exploded a rocket outside.","cn":"突然一声巨响，彷佛有人在外面引爆了火箭似的。"},{"en":"At last, a women's magazine to explode the myth that thin equals beautiful.","cn":"终于有一家女性杂志起来推翻瘦就是美的迷思。"}]},"exploitation":{"media":{"uk":"media/uk/exploitation__gb_1.mp3","us":"media/us/exploitation__us_1.mp3"},"oxford":{"phon":"ˌeksplɔɪˈteɪʃn","pos":"noun","senses":[{"en":"a situation in which somebody treats somebody else in an unfair way, especially in order to make money from their work","cn":"剥削；榨取","lab":"disapproving","ex":{"en":"the exploitation of children","cn":"对儿童的剥削"}},{"en":"the use of land, oil, minerals, etc.","cn":"利用；开发；开采","ex":{"en":"commercial exploitation of the mineral resources in Antarctica","cn":"南极洲矿物资源的商业开采"}},{"en":"the fact of using a situation in order to get an advantage for yourself","cn":"（出于私利的）利用","lab":"disapproving","ex":{"en":"exploitation of the situation for his own purposes","cn":"利用这种局势达到他自己的目的"}}]},"examples":[{"en":"exploitation of the situation for his own purposes","cn":"利用这种局势达到他自己的目的"},{"en":"commercial exploitation of the mineral resources in Antarctica","cn":"南极洲矿物资源的商业开采"}]},"exhaustion":{"media":{"uk":"media/uk/exhaustion__gb_1.mp3","us":"media/us/exhaustion__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɔːstʃən","pos":"noun","senses":[{"en":"the state of being very tired","cn":"筋疲力尽；疲惫不堪","ex":{"en":"suffering from physical/mental/nervous exhaustion","cn":"身体／精神／神经衰弱"}},{"en":"the act of using something until it is completely finished","cn":"耗尽；用尽；枯竭","lab":"formal","ex":{"en":"the exhaustion of natural resources","cn":"自然资源的枯竭"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精疲力竭；疲惫不堪","en":"Exhaustion is the state of being so tired that you have no energy left.","ex":{"en":"Staff say he is suffering from exhaustion.","cn":"员工说他极度疲劳。"}}]},"examples":[{"en":"Her face was grey with exhaustion.","cn":"她疲惫得脸色发白。"},{"en":"suffering from physical/mental/nervous exhaustion","cn":"身体/精神/神经衰弱"}]},"expansion":{"media":{"uk":"media/uk/expansion__gb_1.mp3","us":"media/us/expansion__us_1.mp3"},"oxford":{"phon":"ɪkˈspænʃn","pos":"noun","senses":[{"en":"an act of increasing or making something increase in size, amount or importance","cn":"扩张；扩展；扩大；膨胀","ex":{"en":"a period of rapid economic expansion","cn":"经济迅猛发展期"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"扩张;扩充;扩大;发展","en":"Expansion is the process of becoming greater in size, number, or amount.","ex":{"en":"...the rapid expansion of private health insurance.","cn":"个人健康保险的迅速发展"}}]},"examples":[{"en":"Despite the recession the company is confident of further expansion.","cn":"尽管经济衰退，公司对进一步扩展仍充满信心。"},{"en":"The book is an expansion of a series of lectures given last year.","cn":"本书是去年举行的系列讲座的扩充。"}]},"external":{"media":{"uk":"media/uk/external__gb_1.mp3","us":"media/us/external__us_1.mp3"},"oxford":{"phon":"ɪkˈstɜːnl","pos":"adjective","senses":[{"en":"connected with or located on the outside of something/somebody","cn":"外部的；外面的","ex":{"en":"the external walls of the building","cn":"建筑物的外墙"}},{"en":"happening or coming from outside a place, an organization, your particular situation, etc.","cn":"外界的；外来的；在外的","ex":{"en":"A combination of internal and external factors caused the company to close down.","cn":"内外因结合导致了公司的倒闭。"}},{"en":"coming from or arranged by somebody from outside a school, a university or an organization","cn":"来自（学校或机构）以外的；外来的","lab":"British English","ex":{"en":"external examiners/assessors","cn":"校外主考人／评定人"}},{"en":"connected with foreign countries","cn":"与外国有关的；对外的","ex":{"en":"The government is committed to reducing the country's external debt.","cn":"政府决心减少国家的外债。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"外部的;外面的;外来的","en":"External is used to indicate that something is on the outside of a surface or body, or that it exists, happens, or comes from outside.","ex":{"en":"...a much reduced heat loss through external walls.","cn":"大幅降低的外墙热损失"}},{"pos":"ADJ 形容词","cn":"对外的;与外国有关的","en":"External means involving or intended for foreign countries.","ex":{"en":"...the commissioner for external affairs.","cn":"对外事务专员"}},{"pos":"ADJ 形容词","cn":"外界的;外部的","en":"External means happening or existing in the world in general and affecting you in some way.","ex":{"en":"...a reaction to external events","cn":"对外界事件的反应"}},{"pos":"ADJ 形容词","cn":"（专家等）外来的，外聘的","en":"External experts, for example external examiners, come into an organization from outside in order to do a particular job fairly and impartially, or to check that a particular job was done properly."},{"pos":"PHRASE 短语","cn":"（药物）外用的","en":"If medicine is for external use, it is intended to be used only on the outside of your body, and not to be eaten or drunk."}]},"examples":[{"en":"The university has many externally funded research projects.","cn":"这所大学有许多外界资助的研究项目。"},{"en":"Many external influences can affect your state of mind.","cn":"许多外在因素都可能影响人的心情。"}]},"exist":{"media":{"uk":"media/uk/exist__gb_1.mp3","us":"media/us/exist__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɪst","pos":"verb","senses":[{"en":"to be real; to be present in a place or situation","cn":"存在；实际上有","g":"[intransitive]","ex":{"en":"Does life exist on other planets?","cn":"其他行星上有生命吗？"}},{"en":"to live, especially in a difficult situation or with very little money","cn":"（尤指在困境或贫困中）生活，生存","g":"[intransitive]","ex":{"en":"We existed on a diet of rice.","cn":"我们靠吃大米过活。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"存在;实际上有","en":"If something exists, it is present in the world as a real thing.","ex":{"en":"He thought that if he couldn't see something, it didn't exist","cn":"他认为自己看不见的东西就不存在。"}},{"pos":"VERB 动词","cn":"（尤指在逆境中）生存，生活","en":"To exist means to live, especially under difficult conditions or with very little food or money.","ex":{"en":"I exist from one visit to the next","cn":"我的生活就是一个接一个的访问。"}}]},"examples":[{"en":"The charity exists to support victims of crime.","cn":"设立这个慈善机构是为了援助罪案受害者。"},{"en":"They can't exist on the money he's earning.","cn":"他们靠他挣的那点钱无法维持生活。"}]},"extract":{"media":{"uk":"media/uk/extract__gb_1.mp3","us":"media/us/extract__us_1.mp3"},"oxford":{"phon":"ˈekstrækt","pos":"noun","senses":[{"en":"a short passage from a book, piece of music, etc. that gives you an idea of what the whole thing is like","cn":"摘录；选录；选曲；节录","g":"[countable]","ex":{"en":"The following extract is taken from her new novel.","cn":"下面一段摘自她的新小说。"}},{"en":"a substance that has been obtained from something else using a particular process","cn":"提取物；浓缩物；精；汁","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"yeast extract","cn":"酵母萃"}},{"en":"to remove or obtain a substance from something, for example by using an industrial or a chemical process","cn":"提取；提炼","ex":{"en":"a machine that extracts excess moisture from the air","cn":"抽湿机"},"pos":"verb"},{"en":"to obtain information, money, etc., often by taking it from somebody who is unwilling to give it","cn":"索取，设法得到（对方不愿提供的信息、钱财等）","ex":{"en":"Journalists managed to extract all kinds of information about her private life.","cn":"记者们终于得到了有关她私生活的各种信息。"},"pos":"verb"},{"en":"to choose information, etc. from a book, a computer, etc. to be used for a particular purpose","cn":"选取；摘录；选录","ex":{"en":"This article is extracted from his new book.","cn":"本文选自他的新书。"},"pos":"verb"},{"en":"to take or pull something out, especially when this needs force or effort","cn":"（用力）取出，拔出","lab":"formal or specialist","ex":{"en":"The dentist may decide that the wisdom teeth need to be extracted.","cn":"牙医可能会认为智齿需要拔掉。"},"pos":"verb"},{"en":"to get a particular feeling or quality from a situation","cn":"获得，得到（某种感觉或品质）","lab":"formal","ex":{"en":"They are unlikely to extract much benefit from the trip.","cn":"他们不大可能从这次旅行中获得多大益处。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提取;提炼;挖掘","en":"To extract a substance means to obtain it from something else, for example by using industrial or chemical processes.","ex":{"en":"...the traditional method of pick and shovel to extract coal","cn":"用镐和铲挖煤的传统方法"}},{"pos":"VERB 动词","cn":"取出;抽出","en":"If you extract something from a place, you take it out or pull it out.","ex":{"en":"He extracted a small notebook from his hip pocket","cn":"他从屁股兜里摸出一个小笔记本。"}},{"pos":"VERB 动词","cn":"拔（牙）","en":"When a dentist extracts a tooth, they remove it from the patient's mouth.","ex":{"en":"A dentist may decide to extract the tooth to prevent recurrent trouble","cn":"牙医可能会决定拔掉那颗牙，以免反复发作。"}},{"pos":"VERB 动词","cn":"攫取;榨取","en":"If you say that someone extracts something, you disapprove of them because they take it for themselves to gain an advantage.","ex":{"en":"...the capitalist system, which extracts huge profits from arms production at the tax-payers' expense","cn":"牺牲纳税人利益、从武器生产中攫取巨额利润的资本主义制度"}},{"pos":"VERB 动词","cn":"设法得到;探出","en":"If you extract information or a response from someone, you get it from them with difficulty, because they are unwilling to say or do what you want.","ex":{"en":"He made the mistake of trying to extract further information from our director","cn":"他犯了个错误，不该试图从我们的主管那里打探更多的信息。"}},{"pos":"VERB 动词","cn":"摘录;提取","en":"If you extract a particular piece of information, you obtain it from a larger amount or source of information.","ex":{"en":"I've simply extracted a few figures","cn":"我只是提取了一些数据。"}},{"pos":"V-PASSIVE 被动动词","cn":"（从书中）摘录，节选","en":"If part of a book or text is extracted from a particular book, it is printed or published.","ex":{"en":"This material has been extracted from 'Collins Good Wood Handbook'.","cn":"这些材料摘自《柯林斯优秀木材手册》。"}},{"pos":"N-COUNT 可数名词","cn":"摘录;选段;引文","en":"An extract from a book or piece of writing is a small part of it that is printed or published separately.","ex":{"en":"Read this extract from an information booklet about the work of an airline cabin crew.","cn":"看看这段从有关航空公司乘务人员工作的信息手册中摘录的文字。"}},{"pos":"N-MASS 物质名词","cn":"提取物;精华;汁","en":"An extract is a substance that has been obtained from something else, for example by means of a chemical or industrial process.","ex":{"en":"Blend in the lemon extract, lemon peel and walnuts.","cn":"调入柠檬汁、柠檬皮和核桃。"}}]},"examples":[{"en":"Journalists managed to extract all kinds of information about her private life.","cn":"记者们终于得到了有关她私生活的各种情况。"},{"en":"They are unlikely to extract much benefit from the trip.","cn":"他们不大可能从这次旅行中获得很多益处。"}]},"ex":{"media":{"uk":"media/uk/ex__gb_1.mp3","us":"media/us/ex__us_1.mp3"},"oxford":{"phon":"eks","pos":"noun","senses":[{"en":"a person’s former wife, husband or partner","cn":"前妻；前夫；以前的性伴侣","ex":{"en":"The children are spending the weekend with my ex and his new wife.","cn":"孩子们与我的前夫及其新夫人在一起度周末。"}},{"en":"not including something","cn":"不包括；除…之外","ex":{"en":"The price is £1 500 ex VAT.","cn":"价格为 1 500 英镑，不含增值税。"},"pos":"preposition"},{"en":"former","cn":"原先的；从前的；一度的","ex":{"en":"ex-wife","cn":"前妻"},"pos":"prefix"},{"en":"out","cn":"出；向外","ex":{"en":"exodus","cn":"离去"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"前夫;前妻;前男友;前女友","en":"Someone's ex is the person they used to be married to or used to have a romantic or sexual relationship with.","ex":{"en":"He's different from my ex.","cn":"他和我的前夫不一样。"}}]},"examples":[{"en":"The children are spending the weekend with my ex and his new wife.","cn":"孩子们与我的前夫及其新夫人在一起度周末。"},{"en":"The price is £1 500 ex VAT.","cn":"价格为 1 500 英镑，不包括增值税。"}]},"exposed":{"media":{"uk":"media/uk/exposed__gb_1.mp3","us":"media/us/exposed__us_1.mp3"},"oxford":{"phon":"ɪkˈspəʊzd","pos":"adjective","senses":[{"en":"not protected from the weather by trees, buildings or high ground","cn":"无遮蔽的；不遮挡风雨的","ex":{"en":"The cottage is in a very exposed position on the top of a hill.","cn":"小屋位于山顶上一个非常暴露的位置。"}},{"en":"not protected from attack or criticism","cn":"易受攻击（或批评）的；无保护的","ex":{"en":"She was left feeling exposed and vulnerable.","cn":"她感到自己孤立无助，非常脆弱。"}},{"en":"likely to experience financial losses","cn":"风险高的；很可能遭受经济损失的","lab":"finance","ex":{"en":"The country became highly exposed to the vagaries of international markets.","cn":"这个国家变得极受变幻莫测的国际市场的影响。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暴露于风雨的;无遮蔽措施的","en":"If a place is exposed, it has no natural protection against bad weather or enemies, for example because it has no trees or is on very high ground.","ex":{"en":"...an exposed hillside in Connecticut","cn":"康涅狄格一处暴露于风雨中的小山坡"}}]},"examples":[{"en":"She was left feeling exposed and vulnerable.","cn":"她感到自己孤立无助，非常脆弱。"},{"en":"the side of the garden most exposed to wind","cn":"花园最向风的一边"}],"base":"expose"},"exploded":{"oxford":{"phon":"ɪkˈspləʊdɪd","pos":"adjective","senses":[{"en":"showing the parts of something separately but also showing how they are connected to each other","cn":"分解的","ex":{"en":"an exploded diagram of a plane","cn":"飞机的分解图"}}]},"media":{"uk":"media/uk/exploded__gb_1.mp3","us":"media/us/exploded__us_1.mp3"},"examples":[{"en":"an exploded diagram of an engine","cn":"发动机的分解图"}],"base":"explode"},"explanation":{"media":{"uk":"media/uk/explanation__gb_1.mp3","us":"media/us/explanation__us_1.mp3"},"oxford":{"phon":"ˌekspləˈneɪʃn","pos":"noun","senses":[{"en":"a statement, fact, or situation that tells you why something happened; a reason given for something","cn":"解释；说明；阐述；理由","g":"[countable, uncountable]","ex":{"en":"The most likely explanation is that his plane was delayed.","cn":"最可能的解释是他的飞机晚点了。"}},{"en":"a statement or piece of writing that tells you how something works or makes something easier to understand","cn":"解释性说法；说明性文字","g":"[countable]","ex":{"en":"Other parts of the book contain unnecessarily lengthy explanations.","cn":"本书的其他部分包含不必要的冗长解释。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"解释;说明","en":"If you give an explanation of something that has happened, you give people reasons for it, especially in an attempt to justify it.","ex":{"en":"She told the court she would give a full explanation of the prosecution's decision on Monday","cn":"她告诉法庭她会在星期一对原告方的决定作出全面解释。"}},{"pos":"N-COUNT 可数名词","cn":"理由；原因","en":"If you say there is an explanation for something, you mean that there is a reason for it.","ex":{"en":"The deputy airport manager said there was no apparent explanation for the crash","cn":"机场副经理说那次飞机失事没有明显的原因。"}},{"pos":"N-COUNT 可数名词","cn":"阐述;详细的说明","en":"If you give an explanation of something, you give details about it or describe it so that it can be understood.","ex":{"en":"Haig was immediately impressed by Charteris's expertise and by his lucid explanation of the work.","cn":"查特里斯的专业知识和他对作品浅显易懂的阐释立即给黑格留下了深刻印象。"}}]},"examples":[{"en":"For a full explanation of how the machine works, turn to page 5.","cn":"关于机器运作原理的详细说明，请翻阅第 5 页。"},{"en":"She didn't give an adequate explanation for being late.","cn":"她没有给出充分的理由说明迟到的原因。"}]},"extremity":{"media":{"uk":"media/uk/extremity__gb_1.mp3","us":"media/us/extremity__us_1.mp3"},"oxford":{"phon":"ɪkˈstreməti","pos":"noun","senses":[{"en":"the furthest point, end or limit of something","cn":"末端；端点；尽头","g":"[countable]","ex":{"en":"The lake is situated at the eastern extremity of the mountain range.","cn":"湖位于山脉最东端。"}},{"en":"the degree to which a situation, a feeling, an action, etc. is extreme, difficult or unusual","cn":"极端；极度；极限","g":"[countable, uncountable]","ex":{"en":"the extremities/extremity of pain","cn":"极度疼痛"}},{"en":"the parts of your body that are furthest from the centre, especially your hands and feet","cn":"（人体的）四肢，手足","g":"[plural]","lab":"formal","ex":{"en":"Cold extremities and a hot head are the first signs of the fever.","cn":"四肢冰冷和头部发热是发烧的最初症状。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"尽头;末端","en":"The extremity of something is its furthest end or edge.","ex":{"en":"...a small port on the north-western extremity of the Iberian peninsula.","cn":"伊比利亚半岛西北端的小港口"}},{"pos":"N-PLURAL 复数名词","cn":"（身体的）末端，末梢;（尤指）手脚","en":"Your extremities are the end parts of your body, especially your hands and feet.","ex":{"en":"He found that his extremities grew cold","cn":"他发现手脚变冷了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"极度;极端","en":"The extremity of a situation or of someone's behaviour is the degree to which it is severe, unusual, or unacceptable.","ex":{"en":"In spite of the extremity of her seclusion she was sane","cn":"尽管完全与世隔绝，她依然心智健全。"}}]},"examples":[{"en":"The lake is situated at the eastern extremity of the mountain range.","cn":"湖位于山脉最东端。"},{"en":"the extremities/extremity of pain","cn":"极度疼痛"}]},"excessive":{"media":{"uk":"media/uk/excessive__gb_1.mp3","us":"media/us/excessive__us_1.mp3"},"oxford":{"phon":"ɪkˈsesɪv","pos":"adjective","senses":[{"en":"greater than what seems reasonable or appropriate","cn":"过分的；过度的","ex":{"en":"They complained about the excessive noise coming from the upstairs flat.","cn":"他们抱怨楼上发出的噪音太大。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过分的;过多的","en":"If you describe the amount or level of something as excessive, you disapprove of it because it is more or higher than is necessary or reasonable.","ex":{"en":"...the alleged use of excessive force by police","cn":"警察涉嫌滥用武力"}}]},"examples":[{"en":"They complained about the excessive noise coming from the upstairs flat.","cn":"他们抱怨楼上发出的噪音太大。"},{"en":"The amounts she borrowed were not excessive.","cn":"她借的数量没有超额。"}]},"expenditures":{"lemma":"expenditure"},"extraordinarily":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"extremely","cn":"极其"},{"en":"in a way that seems strange","cn":"奇怪地"}]},"examples":[{"en":"We were extraordinarily lucky.","cn":"我们极其幸运。","src":"ld"},{"en":"Why had James behaved so extraordinarily?","cn":"为什么詹姆斯的行为那么古怪？","src":"ld"}],"media":{"uk":"media/uk/extraordinarily__gb_1.mp3","us":"media/us/extraordinarily__us_1.mp3"},"oxford":{"phon":"ɪkˈstrɔːdnrəli","pos":"adverb","senses":[{"en":"in a way that is unexpected, surprising or strange","cn":"意想不到的；令人惊奇的；奇怪的","ex":{"en":"He behaves extraordinarily for someone in his position.","cn":"以他的身份地位，做出这样的行为实在令人感到奇怪。"}},{"en":"in a way that is more, greater or better than usual","cn":"不平常的；不一般的；非凡的；卓越的","ex":{"en":"extraordinarily difficult","cn":"特别困难"}}]}},"exaggerated":{"media":{"uk":"media/uk/exaggerated__gb_1.mp3","us":"media/us/exaggerated__us_1.mp3"},"oxford":{"phon":"ɪɡˈzædʒəreɪtɪd","pos":"adjective","senses":[{"en":"made to seem larger, better, worse or more important than it really is or needs to be","cn":"夸张的；夸大的；言过其实的","ex":{"en":"to make greatly/grossly/wildly exaggerated claims","cn":"提出极为过分的索偿"}},{"en":"done in a way that makes people notice it","cn":"故作姿态的；矫揉造作的","ex":{"en":"an exaggerated laugh","cn":"矫揉造作的笑声"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"夸大的;夸张的;言过其实的","en":"Something that is exaggerated is or seems larger, better, worse, or more important than it actually needs to be.","ex":{"en":"They should be sceptical of exaggerated claims for what such courses can achieve","cn":"对于那些课程能够取得何等成果的夸大宣传，他们应该持怀疑态度。"}}]},"examples":[{"en":"He looked at me with exaggerated surprise.","cn":"他故作吃惊地看着我。"},{"en":"She has an exaggerated sense of her own importance.","cn":"她自视过高。"}],"base":"exaggerate"},"excited":{"media":{"uk":"media/uk/excited__gb_1.mp3","us":"media/us/excited__us_1.mp3"},"oxford":{"phon":"ɪkˈsaɪtɪd","pos":"adjective","senses":[{"en":"feeling or showing happiness and enthusiasm","cn":"激动的；兴奋的","ex":{"en":"Staff got excited when they heard they were getting a bonus.","cn":"员工们听说要发奖金，都非常兴奋。"}},{"en":"nervous or upset and unable to relax","cn":"受刺激的；紧张不安的","ex":{"en":"Some horses become excited when they're in traffic.","cn":"有些马在车流中会受惊。"}},{"en":"feeling sexual desire","cn":"性兴奋的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"兴奋的;激动的","en":"If you are excited, you are so happy that you cannot relax, especially because you are thinking about something pleasant that is going to happen to you.","ex":{"en":"I'm very excited about the possibility of playing for England's first team","cn":"想到可能为英格兰首屈一指的球队效力，我非常兴奋。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心烦的;忧虑的;气愤的","en":"If you are excited, you are very worried or angry about something, and so you are very alert and cannot relax.","ex":{"en":"I don't think there's any reason to get excited about inflation","cn":"我认为大可不必为通货膨胀而心烦。"}}]},"examples":[{"en":"Don't get too excited by the sight of your name in print.","cn":"不要一看到你的名字出现在出版物中就过分激动。"},{"en":"The new restaurant is nothing to get excited about (= not particularly good).","cn":"这家新餐馆没什么值得特别激动的地方。"}]},"explore":{"media":{"uk":"media/uk/explore__gb_1.mp3","us":"media/us/explore__us_1.mp3"},"oxford":{"phon":"ɪkˈsplɔː(r)","pos":"verb","senses":[{"en":"to travel to or around an area or a country in order to learn about it","cn":"勘探；勘查；探索；考察","g":"[intransitive, transitive]","ex":{"en":"As soon as we arrived on the island we were eager to explore.","cn":"我们一来到岛上就急不可耐地开始探胜。"}},{"en":"to examine a subject or a possibility completely or carefully in order to find out more about it","cn":"探究；调查研究；探索；探讨","g":"[transitive]","ex":{"en":"to explore a theme/an issue","cn":"探究主题／问题"}},{"en":"to feel something with your hands or another part of the body","cn":"（用手或其他部位）触摸，探查","g":"[transitive]","ex":{"en":"She explored the sand with her toes.","cn":"她用脚趾触探沙子。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"在…探险;探测;勘察;考察","en":"If you explore a place, you travel around it to find out what it is like.","ex":{"en":"I just wanted to explore Paris, read Sartre, listen to Sidney Bechet","cn":"我就想逛逛巴黎，读读萨特的作品，听听悉尼·贝谢的音乐。"}},{"pos":"VERB 动词","cn":"探讨，研究（观点或建议）","en":"If you explore an idea or suggestion, you think about it or comment on it in detail, in order to assess it carefully.","ex":{"en":"The secretary is expected to explore ideas for post-war reconstruction of the area","cn":"部长预计将会探讨这个地区战后重建的意见。"}},{"pos":"VERB 动词","cn":"勘探","en":"If people explore an area for a substance such as oil or minerals, they study the area and do tests on the land to see whether they can find it.","ex":{"en":"Central to the operation is a mile-deep well, dug originally to explore for oil","cn":"那次行动的重点是一口深达1英里的井，最初钻那口井是为了勘探石油。"}},{"pos":"VERB 动词","cn":"（用手等）摸索，触碰","en":"If you explore something with your hands or fingers, you touch it to find out what it feels like.","ex":{"en":"He explored the wound with his finger, trying to establish its extent.","cn":"他用手指摸了摸伤口，想要确定受伤的程度。"}}]},"examples":[{"en":"These ideas will be explored in more detail in Chapter 7.","cn":"这些想法将在第 7 章里作更详细的探讨。"},{"en":"As soon as we arrived on the island we were eager to explore.","cn":"我们一来到岛上就急不可耐地考察起来。"}]},"extravagant":{"media":{"uk":"media/uk/extravagant__gb_1.mp3","us":"media/us/extravagant__us_1.mp3"},"oxford":{"phon":"ɪkˈstrævəɡənt","pos":"adjective","senses":[{"en":"spending a lot more money or using a lot more of something than you can afford or than is necessary","cn":"奢侈的；挥霍的；铺张浪费的","ex":{"en":"I felt very extravagant spending £200 on a dress.","cn":"我觉得花 200 英镑买一条连衣裙太奢侈了。"}},{"en":"costing a lot more money than you can afford or is necessary","cn":"过于昂贵的","ex":{"en":"He bought us all these extravagant presents he couldn't really afford.","cn":"他给我们买了这些他根本无力支付的昂贵礼物。"}},{"en":"very extreme or impressive but not reasonable or practical","cn":"无节制的；过分的；放肆的；不切实际的","ex":{"en":"the extravagant claims/promises of politicians","cn":"政客的夸大其词／不切实际的承诺"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奢侈的;铺张的;浪费的","en":"Someone who is extravagant spends more money than they can afford or uses more of something than is reasonable.","ex":{"en":"We are not extravagant; restaurant meals are a luxury and designer clothes are out","cn":"我们并不铺张浪费：下馆子是一种奢侈，也不会考虑买名牌衣服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"价格过高的;昂贵的;奢侈的","en":"Something that is extravagant costs more money than you can afford or uses more of something than is reasonable.","ex":{"en":"Her Aunt Sallie gave her an uncharacteristically extravagant gift","cn":"萨莉姨妈送给她一件贵得离谱的礼物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极端的;过分的","en":"Extravagant behaviour is extreme behaviour that is often done for a particular effect.","ex":{"en":"He was extravagant in his admiration of Hellas","cn":"他极度向往希腊。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"离谱的;不切实际的","en":"Extravagant claims or ideas are unrealistic or impractical.","ex":{"en":"They have to compete by adorning their products with ever more extravagant claims","cn":"他们不得不通过更加离谱地吹捧自己的产品来进行竞争。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精美的;令人赞叹的","en":"Extravagant entertainments or designs are elaborate and impressive.","ex":{"en":"...the wildest and most extravagant London parties.","cn":"伦敦最狂野、最美妙的聚会"}}]},"examples":[{"en":"I felt very extravagant spending £100 on a dress.","cn":"我觉得花 100 英镑买一条连衣裙太奢侈了。"},{"en":"Residents were warned not to be extravagant with water, in view of the low rainfall this year.","cn":"鉴于今年降雨量少，居民被告诫不得浪费用水。"}]},"expansive":{"media":{"uk":"media/uk/expansive__gb_1.mp3","us":"media/us/expansive__us_1.mp3"},"oxford":{"phon":"ɪkˈspænsɪv","pos":"adjective","senses":[{"en":"covering a large amount of space","cn":"广阔的；辽阔的；浩瀚的","ex":{"en":"She opened her arms wide in an expansive gesture of welcome.","cn":"她展开双臂以示欢迎。"}},{"en":"covering a large subject area, rather than trying to be exact and use few words","cn":"广泛的；全面的","ex":{"en":"We need to look at a more expansive definition of the term.","cn":"我们需要考虑这个用语所包含的更广泛意义。"}},{"en":"friendly and willing to talk a lot","cn":"友善健谈的；开朗的","ex":{"en":"She was clearly relaxed and in an expansive mood.","cn":"她显然悠闲自在，心情豁朗。"}},{"en":"encouraging economic expansion","cn":"刺激经济扩张的","ex":{"en":"In the expansive 1990s bright graduates could advance rapidly.","cn":"在经济发展快速的 20 世纪 90 年代，有才华的大学毕业生可以发展很快。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"广袤的;辽阔的;全面的","en":"If something is expansive, it covers or includes a large area or many things.","ex":{"en":"...an expansive grassy play area","cn":"广阔的游乐草地"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"豪爽的;开朗的;健谈的","en":"If you are expansive, you talk a lot, or are friendly or generous, because you are feeling happy and relaxed.","ex":{"en":"He was becoming more expansive as he relaxed","cn":"他放松的时候变得更加开朗。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"扩张的;发展的","en":"If you describe something such as a period of time or an economy as expansive, you mean that it is associated with growth or expansion.","ex":{"en":"An active and expansive market economy is a necessary condition for progress.","cn":"积极扩张的市场经济是发展的必要条件。"}}]},"examples":[{"en":"In the expansive 1990s bright graduates could advance rapidly.","cn":"在经济发展快速的 20 世纪 90 年代，有才华的大学毕业生可以发展很快。"},{"en":"The piece is written in his usual expansive style.","cn":"这篇文章是以他惯常的洋洋洒洒的风格写成的。"}]},"extend":{"media":{"uk":"media/uk/extend__gb_1.mp3","us":"media/us/extend__us_1.mp3"},"oxford":{"phon":"ɪkˈstend","pos":"verb","senses":[{"en":"to make something longer or larger","cn":"使伸长；扩大；扩展","g":"[transitive]","sc":"make longer/larger/wider","ex":{"en":"to extend a fence/road/house","cn":"扩建护栏／公路／房子"}},{"en":"to make something last longer","cn":"延长；使延期","g":"[transitive]","sc":"make longer/larger/wider","ex":{"en":"to extend a deadline/visa","cn":"延长最后期限／签证"}},{"en":"to make a business, an idea, an influence, etc. cover more areas or operate in more places","cn":"扩大…的范围（或影响）","g":"[transitive]","sc":"make longer/larger/wider","ex":{"en":"The school is extending the range of subjects taught.","cn":"学校正在拓宽授课学科的范围。"}},{"en":"to relate to or include somebody/something","cn":"适用于；包括","g":"[intransitive]","sc":"include","ex":{"en":"The offer does not extend to employees' partners.","cn":"这项优惠不包括雇员的伴侣。"}},{"en":"to cover a particular area, distance or length of time","cn":"涉及（范围）；延伸（距离）；延续（时间）","g":"[intransitive]","sc":"cover area/time/distance","ex":{"en":"Our land extends as far as the river.","cn":"我们的土地一直延伸到河边。"}},{"en":"to make something reach something or stretch","cn":"使达到；使延伸","g":"[transitive]","sc":"cover area/time/distance","ex":{"en":"to extend a rope between two posts","cn":"在两根柱子间拉根绳子"}},{"en":"to stretch part of your body, especially an arm or a leg, away from yourself","cn":"伸展，舒展，展开（尤指手臂或腿）","g":"[transitive]","lab":"figurative","sc":"part of body","ex":{"en":"He extended his hand to (= offered to shake hands with) the new employee.","cn":"他伸出手来与新雇员握手。"}},{"en":"to offer or give something to somebody","cn":"提议；提供；提出","g":"[transitive]","lab":"formal","sc":"offer/give","ex":{"en":"I'm sure you will join me in extending a very warm welcome to our visitors.","cn":"我肯定你们会同我一起向来访者表示热烈的欢迎。"}},{"en":"to make somebody/something use all their effort, abilities, supplies, etc.","cn":"使竭尽全力","g":"[transitive]","sc":"use effort/ability","ex":{"en":"Jim didn't really have to extend himself in the exam.","cn":"吉姆大可不必为这次考试那么拼命。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"延伸;伸展","en":"If you say that something, usually something large, extends for a particular distance or extends from one place to another, you are indicating its size or position.","ex":{"en":"The caves extend for some 18 kilometres","cn":"那些洞穴深约18公里。"}},{"pos":"VERB 动词","cn":"伸出;凸出","en":"If an object extends from a surface or place, it sticks out from it.","ex":{"en":"A shelf of land extended from the escarpment.","cn":"悬崖上凸出一块空地。"}},{"pos":"VERB 动词","cn":"持续;延续","en":"If an event or activity extends over a period of time, it continues for that time.","ex":{"en":"...a playing career in first-class cricket that extended from 1894 to 1920","cn":"从1894年延续至1920年的板球甲级比赛职业生涯"}},{"pos":"VERB 动词","cn":"扩及;波及;包括","en":"If something extends to a group of people, things, or activities, it includes or affects them.","ex":{"en":"The service also extends to wrapping and delivering gifts","cn":"服务项目还包括包装和递送礼物。"}},{"pos":"VERB 动词","cn":"扩大;延长","en":"If you extend something, you make it longer or bigger.","ex":{"en":"This year they have introduced three new products to extend their range","cn":"今年他们发布了3种新产品，以扩大产品范围。"}},{"pos":"VERB 动词","cn":"（设备、家具等）展开，伸展","en":"If a piece of equipment or furniture extends, its length can be increased.","ex":{"en":"... a table which extends to accommodate extra guests","cn":"展开后可坐更多客人的桌子"}},{"pos":"VERB 动词","cn":"延长;使延期","en":"If you extend something, you make it last longer than before or end at a later date.","ex":{"en":"They have extended the deadline by twenty-four hours.","cn":"他们已经将最后期限延长了24小时。"}},{"pos":"VERB 动词","cn":"扩大…的影响;扩展","en":"If you extend something to other people or things, you make it include or affect more people or things.","ex":{"en":"It might be possible to extend the technique to other crop plants.","cn":"也许可以将这种技术应用于其他农作物。"}},{"pos":"VERB 动词","cn":"伸展，伸出（手臂等）","en":"If someone extends their hand, they stretch out their arm and hand to shake hands with someone.","ex":{"en":"The man extended his hand: 'I'm Chuck'.","cn":"那名男子伸出手说道：“我是查克。”"}}]},"examples":[{"en":"I'm sure you will join me in extending a very warm welcome to our visitors.","cn":"我肯定你们会同我一起向来访者表示热烈的欢迎。"},{"en":"His willingness to help did not extend beyond making a few phone calls.","cn":"他的乐意帮助只不过限于打几个电话罢了。"}]},"exploration":{"media":{"uk":"media/uk/exploration__gb_1.mp3","us":"media/us/exploration__us_1.mp3"},"oxford":{"phon":"ˌekspləˈreɪʃn","pos":"noun","senses":[{"en":"the act of travelling through a place in order to find out about it or look for something in it","cn":"勘探；勘查；探索","ex":{"en":"Budgets for space exploration have been cut back.","cn":"太空探索的预算被削减了。"}},{"en":"an examination of something in order to find out about it","cn":"探究；研究；探测","ex":{"en":"These findings merit further exploration.","cn":"这些发现值得进一步探讨。"}}]},"examples":[{"en":"the book's explorations of the human mind","cn":"本书对人类思维的研究"},{"en":"oil exploration (= searching for oil in the ground)","cn":"石油勘探"}]},"expenditure":{"oxford":{"phon":"ɪkˈspendɪtʃə(r)","pos":"noun","senses":[{"en":"the act of spending or using money; an amount of money spent","cn":"花费；消费；费用；开支","ex":{"en":"a reduction in public/government/military expenditure","cn":"公共／政府／军费开支的削减"}},{"en":"the use of energy, time, materials, etc.","cn":"（精力、时间、材料等的）耗费，消耗","ex":{"en":"the expenditure of emotion","cn":"感情的消耗"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"花费;开销;支出","en":"Expenditure is the spending of money on something, or the money that is spent on something.","ex":{"en":"Policies of tax reduction must lead to reduced public expenditure","cn":"减税政策必然导致公共支出的削减。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（时间、精力等的）消耗，花费","en":"Expenditure of something such as time or energy is the using of that thing for a particular purpose.","ex":{"en":"The financial rewards justified the expenditure of effort.","cn":"经济上的回报证明付出的努力是值得的。"}}]},"media":{"uk":"media/uk/expenditure__gb_1.mp3","us":"media/us/expenditure__us_1.mp3"},"examples":[{"en":"The budget provided for a total expenditure of £27 billion.","cn":"预算案规定支出总额为 270 亿英镑。"},{"en":"This study represents a major expenditure of time and effort.","cn":"这项研究意味着要耗费大量的时间和精力。"}]},"excavate":{"media":{"uk":"media/uk/excavate__gb_1.mp3","us":"media/us/excavate__us_1.mp3"},"oxford":{"phon":"ˈekskəveɪt","pos":"verb","senses":[{"en":"to dig in the ground to look for old buildings or objects that have been buried for a long time; to find something by digging in this way","cn":"发掘，挖出（古建筑或古物）","ex":{"en":"The site has been excavated by archaeologists.","cn":"这个遗址已被考古学家发掘出来。"}},{"en":"to make a hole, etc. in the ground by digging","cn":"挖掘，开凿，挖空（洞、隧道等）","lab":"formal","ex":{"en":"The body was discovered when builders excavated the area.","cn":"建筑工人挖地时发现了这具尸体。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发掘，挖掘（古物等）","en":"When archaeologists or other people excavate a piece of land, they remove earth carefully from it and look for things such as pots, bones, or buildings which are buried there, in order to discover information about the past.","ex":{"en":"A new Danish expedition is again excavating the site in annual summer digs.","cn":"一支新的丹麦探险队又在那个遗址上进行一年一度的夏季挖掘。"}},{"pos":"VERB 动词","cn":"挖;开凿","en":"To excavate means to dig a hole in the ground, for example in order to build there.","ex":{"en":"A contractor was hired to drain the reservoir and to excavate soil from one area for replacement with clay.","cn":"雇了一个承包商抽干水库的水，挖掉一个区域的泥土后再用黏土填上。"}}]},"examples":[{"en":"The site has been excavated by archaeologists.","cn":"这个遗址已被考古学家发掘出来。"},{"en":"The body was discovered when builders excavated the area.","cn":"建筑工人挖地时发现了这具尸体。"}]},"extremely":{"media":{"uk":"media/uk/extremely__gb_1.mp3","us":"media/us/extremely__us_1.mp3"},"oxford":{"phon":"ɪkˈstriːmli","pos":"adverb","senses":[{"en":"to a very high degree","cn":"极其；极端；非常","ex":{"en":"It is extremely important to follow the directions exactly.","cn":"严格遵循指示非常重要。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（用于形容词和副词前）非常，极其","en":"You use extremely in front of adjectives and adverbs to emphasize that the specified quality is present to a very great degree.","ex":{"en":"My mobile phone is extremely useful","cn":"我的手机非常有用。"}}]},"examples":[{"en":"She found it extremely difficult to get a job.","cn":"她发觉找工作极其困难。"},{"en":"extremely important/useful/complicated","cn":"极为重要/有用/复杂"}]},"expect":{"media":{"uk":"media/uk/expect__gb_1.mp3","us":"media/us/expect__us_1.mp3"},"oxford":{"phon":"ɪkˈspekt","pos":"verb","senses":[{"en":"to think or believe that something will happen or that somebody will do something","cn":"预料；预期；预计","g":"[transitive]","ex":{"en":"The company is expecting record sales this year.","cn":"公司预计今年的销售额将创纪录。"}},{"en":"to be waiting for somebody/something to arrive, as this has been arranged","cn":"等待；期待；盼望","g":"[transitive]","ex":{"en":"to expect a visit/call/letter from somebody","cn":"等待某人的来访／电话／来信"}},{"en":"to demand that somebody will do something because it is their duty or responsibility","cn":"要求；期望；指望","g":"[transitive]","ex":{"en":"It is reasonable to expect changes in the way we work.","cn":"我们的工作方式将发生改变，这是合理的期待。"}},{"en":"used when you think something is probably true","cn":"猜想；认为；料想","g":"[intransitive, transitive]","lab":"especially British English, informal，，","ex":{"en":"‘Will you be late?’ ‘I expect so.’","cn":"“你会迟到吗？”“我想会的。”"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"预期;预料;期待","en":"If you expect something to happen, you believe that it will happen.","ex":{"en":"...a council workman who expects to lose his job in the next few weeks","cn":"预计自己在接下来的几周里会丢掉工作的市政工人"}},{"pos":"VERB 动词","cn":"盼望;期待;等待","en":"If you are expecting something or someone, you believe that they will be delivered to you or come to you soon, often because this has been arranged earlier.","ex":{"en":"I am expecting several important letters but nothing has arrived","cn":"我正在等几封重要的信件，可是一封都没到。"}},{"pos":"VERB 动词","cn":"要求；认为应当得到;指望","en":"If you expect something, or expect a person to do something, you believe that it is your right to have that thing, or the person's duty to do it for you.","ex":{"en":"He wasn't expecting our hospitality","cn":"他没有指望我们会盛情款待。"}},{"pos":"VERB 动词","cn":"指望;期望","en":"If you tell someone not to expect something, you mean that the thing is unlikely to happen as they have planned or imagined, and they should not hope that it will.","ex":{"en":"Don't expect an instant cure","cn":"别指望立即治愈。"}},{"pos":"VERB 动词","cn":"怀孕","en":"If you say that a woman is expecting a baby, or that she is expecting, you mean that she is pregnant.","ex":{"en":"She was expecting another baby","cn":"她又怀孕了。"}},{"pos":"PHRASE 短语","cn":"我认为;我猜想","en":"You say 'I expect' to suggest that a statement is probably correct, or a natural consequence of the present situation, although you have no definite knowledge.","ex":{"en":"I expect you can guess what follows","cn":"我想你能猜出接下来发生了什么。"}},{"pos":"PHRASE 短语","cn":"你还想指望什么；那有什么大惊小怪的","en":"You can say 'What can you expect?' or 'What do you expect?' to emphasize that there is nothing surprising about a situation or a person's behaviour, especially if you find this disappointing.","ex":{"en":"It tastes artificial, but at that price what can you expect?","cn":"尝起来像是假的，但是就这个价格你还想指望什么？"}}]},"examples":[{"en":"‘Who's eaten all the cake?’ ‘Tom, I expect/I expect it was Tom.’ “","cn":"谁把蛋糕都吃光了？” “我想是汤姆吧。”"},{"en":"He's still getting over his illness, so don't expect too much from him.","cn":"他仍处于康复期，所以不要对他期望过高。"}]},"exert":{"oxford":{"phon":"ɪɡˈzɜːt","pos":"verb","senses":[{"en":"to use power or influence to affect somebody/something","cn":"运用；行使；施加","ex":{"en":"He exerted all his authority to make them accept the plan.","cn":"他利用他的所有权力让他们接受这个计划。"}},{"en":"to make a big physical or mental effort","cn":"努力；竭力","ex":{"en":"In order to be successful he would have to exert himself.","cn":"他必须努力才能成功。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"施加（影响、压力等）;行使，运用（权威等）","en":"If someone or something exerts influence, authority, or pressure, they use it in a strong or determined way, especially in order to produce a particular effect.","ex":{"en":"He exerted considerable influence on the thinking of the scientific community on these issues","cn":"他极大地影响了科学界对这些问题的看法。"}},{"pos":"VERB 动词","cn":"尽力;努力","en":"If you exert yourself, you make a great physical or mental effort, or work hard to do something.","ex":{"en":"Youngsters get so absorbed that they don't realise how much they're exerting themselves","cn":"年轻人如此地沉浸其中，他们没有意识到自己有多么努力。"}}]},"media":{"uk":"media/uk/exert__gb_1.mp3","us":"media/us/exert__us_1.mp3"},"examples":[{"en":"He exerted all his authority to make them accept the plan.","cn":"他利用他的所有权力让他们接受这个计划。"},{"en":"The moon exerts a force on the earth that causes the tides.","cn":"月球对地球的吸引力引起潮汐。"}]},"exec":{"oxford":{"phon":"ɪɡˈzek","pos":"noun","senses":[{"en":"an executive in a business","cn":"（公司的）经理，管理人员","ex":{"en":"The role of the chief exec is to empower the team.","cn":"首席执行官的作用是赋予团队权力。"}}]},"media":{"uk":"media/uk/exec__gb_1.mp3","us":"media/us/exec__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"","en":"Exec is an abbreviation for (缩略=) executive."}]}},"expressly":{"media":{"uk":"media/uk/expressly__gb_1.mp3","us":"media/us/expressly__us_1.mp3"},"oxford":{"phon":"ɪkˈspresli","pos":"adverb","senses":[{"en":"clearly; definitely","cn":"清楚地；明确地；确切地","ex":{"en":"She was expressly forbidden to touch my papers.","cn":"已经明确禁止她动我的文件。"}},{"en":"for a special and deliberate purpose","cn":"特意；专程","ex":{"en":"The rule was introduced expressly for this purpose.","cn":"这项规则是为此特意设置的。"}}]},"examples":[{"en":"She was expressly forbidden to touch my papers.","cn":"已经明确禁止她动我的文件。"},{"en":"The rule was introduced expressly for this purpose.","cn":"这项规则是为此特意提出的。"}]},"exempt":{"media":{"uk":"media/uk/exempt__gb_1.mp3","us":"media/us/exempt__us_1.mp3"},"oxford":{"phon":"ɪɡˈzempt","pos":"adjective","senses":[{"en":"if somebody/something is exempt from something, they are not affected by it, do not have to do it, pay it, etc.","cn":"免除（责任、付款等）；获豁免","ex":{"en":"The interest on the money is exempt from tax.","cn":"这笔钱的利息免税。"}},{"en":"not having to do, pay, etc. the thing mentioned","cn":"-豁免：不必做，付钱等等。","ex":{"en":"tax-exempt donations to charity","cn":"给慈善机构的免税捐款"},"pos":"combining form"},{"en":"to give somebody official permission not to do something or not to pay something they would normally have to do or pay; to cause somebody to get this official permission","cn":"免除；豁免","ex":{"en":"Charities were exempted from paying the tax.","cn":"慈善团体免付税款。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被免除的;被豁免的","en":"If someone or something is exempt from a particular rule, duty, or obligation, they do not have to follow it or do it.","ex":{"en":"Men in college were exempt from military service","cn":"大学在校男生免服兵役。"}},{"pos":"VERB 动词","cn":"免除;豁免","en":"To exempt a person or thing from a particular rule, duty, or obligation means to state officially that they are not bound or affected by it.","ex":{"en":"South Carolina claimed the power to exempt its citizens from the obligation to obey federal law","cn":"南卡罗来纳州声称有权力免除该州公民遵守联邦法规的义务。"}}]},"examples":[{"en":"Some students are exempt from certain exams.","cn":"有些学生可免除某些考试。"},{"en":"His bad eyesight exempted him from military service.","cn":"他因视力不好而免服兵役。"}]},"exclusive":{"media":{"uk":"media/uk/exclusive__gb_1.mp3","us":"media/us/exclusive__us_1.mp3"},"oxford":{"phon":"ɪkˈskluːsɪv","pos":"adjective","senses":[{"en":"only to be used by one particular person or group; only given to one particular person or group","cn":"（个人或集体）专用的，专有的，独有的，独占的","ex":{"en":"The hotel has exclusive access to the beach.","cn":"这家旅馆有通向海滩的专用通道。"}},{"en":"not very willing to allow new people to become members, especially if they are from a lower social class","cn":"排外的；不愿接收（较低社会阶层）新成员的","ex":{"en":"He belongs to an exclusive club.","cn":"他参加的是一个不轻易吸收新会员的俱乐部。"}},{"en":"of a high quality and expensive and therefore not often bought or used by most people","cn":"高档的；豪华的；高级的","ex":{"en":"an exclusive hotel","cn":"高级酒店"}},{"en":"not including anything else","cn":"不包含其他的","ex":{"en":"He had an exclusive focus on success and making money.","cn":"他一心想的是成功和赚钱。"}},{"en":"not including somebody/something","cn":"不包括；不算；除…外","ex":{"en":"The price is for accommodation only, exclusive of meals.","cn":"此价只包括住宿，饭费除外。"}},{"en":"not able to exist or be a true statement at the same time as something else","cn":"排斥的；排他的","ex":{"en":"The two options are not mutually exclusive (= you can have them both).","cn":"这两种选择并不相互排斥。"}},{"en":"an item of news or a story about famous people that is published in only one newspaper or magazine or broadcast on only one TV or radio station","cn":"独家新闻；独家专文；独家报道","ex":{"en":"We feature an exclusive on the mothers whose babies were swapped at birth.","cn":"我们独家报道了婴儿出生时被交换的母亲。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高档的;高级的;奢华的","en":"If you describe something as exclusive, you mean that it is limited to people who have a lot of money or who belong to a high social class, and is therefore not available to everyone.","ex":{"en":"He is already a member of Britain's most exclusive club","cn":"他已经是英国最高级俱乐部的成员了。"}},{"pos":"ADJ 形容词","cn":"独用的;独有的;独享的","en":"Something that is exclusive is used or owned by only one person or group, and not shared with anyone else.","ex":{"en":"Our group will have exclusive use of a 60-foot boat","cn":"我们小组将独用一条60英尺长的船。"}},{"pos":"ADJ 形容词","cn":"（新闻报道）独家的","en":"If a newspaper, magazine, or broadcasting organization describes one of its reports as exclusive, they mean that it is a special report which does not appear in any other publication or on any other channel.","ex":{"en":"He told the magazine in an exclusive interview: 'All my problems stem from drink'.","cn":"他在接受一家杂志社的独家采访时说：“我所有的问题都是饮酒造成的。”"}},{"pos":"ADJ 形容词","cn":"不包括…的；不含…的","en":"If a company states that its prices, goods, or services are exclusive of something, that thing is not included in the stated price, although it usually still has to be paid for.","ex":{"en":"All charges for service are exclusive of value added tax","cn":"所有服务费都不包括增值税。"}},{"pos":"PHRASE 短语","cn":"相互排斥的;互不相容的","en":"If two things are mutually exclusive, they are separate and very different from each other, so that it is impossible for them to exist or happen together.","ex":{"en":"They both have learnt that ambition and successful fatherhood can be mutually exclusive.","cn":"他们两个人都认识到了追求理想和做个好父亲不能两者兼顾。"}}]},"examples":[{"en":"His mother has told ‘The Times’ about his death in an exclusive interview (= not given to any other newspaper).","cn":"他的母亲在接受《泰晤士报》的独家采访时谈到他的死亡。"},{"en":"He belongs to an exclusive club.","cn":"他参加的是一个不轻易吸收新会员的俱乐部。"}]},"extraction":{"media":{"uk":"media/uk/extraction__gb_1.mp3","us":"media/us/extraction__us_1.mp3"},"oxford":{"phon":"ɪkˈstrækʃn","pos":"noun","senses":[{"en":"the act or process of removing or obtaining something from something else","cn":"提取；提炼；拔出；开采","g":"[uncountable, countable]","ex":{"en":"oil/mineral/coal, etc. extraction","cn":"石油、矿物、煤等的开采"}},{"en":"having a particular family origin","cn":"（有…）血统；族裔","g":"[uncountable]","lab":"formal","ex":{"en":"an American of Hungarian extraction","cn":"匈牙利血统的美国人"}},{"en":"the process of removing a tooth","cn":"拔牙","g":"[countable]","lab":"specialist","ex":{"en":"I didn’t like having my teeth drilled but extractions were infinitely worse.","cn":"我不喜欢钻牙，但拔牙更糟糕。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"血统;家世","en":"If you say, for example, that someone is of French extraction, you mean that they or their family originally came from France.","ex":{"en":"Her real father was of Italian extraction","cn":"她的亲生父亲是意大利裔。"}}]},"examples":[{"en":"the extraction of salt from the sea","cn":"从海水中提取盐"},{"en":"oil/mineral/coal, etc. extraction","cn":"石油、矿物、煤等的开采"}]},"examines":{"lemma":"examine","media":{"uk":"media/uk/examine__gb_1.mp3","us":"media/us/examine__us_1.mp3"}},"expand":{"media":{"uk":"media/uk/expand__gb_1.mp3","us":"media/us/expand__us_1.mp3"},"oxford":{"phon":"ɪkˈspænd","pos":"verb","senses":[{"en":"to become greater in size, number or importance; to make something greater in size, number or importance","cn":"扩大，增加，增强（尺码、数量或重要性）","g":"[intransitive, transitive]","ex":{"en":"Metals expand when they are heated.","cn":"金属受热会膨胀。"}},{"en":"if a business expands or is expanded, new branches are opened, it makes more money, etc.","cn":"扩展，发展（业务）","g":"[intransitive, transitive]","ex":{"en":"an expanding economy (= with more businesses starting and growing)","cn":"不断发展的经济"}},{"en":"to talk more; to add details to what you are saying","cn":"细谈；详述；详细阐明","g":"[intransitive]","ex":{"en":"I repeated the question and waited for her to expand.","cn":"我把问题重复了一遍，等着她详细回答。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"扩充;扩大;增加","en":"If something expands or is expanded, it becomes larger.","ex":{"en":"Engineers noticed that the pipes were not expanding as expected","cn":"工程师注意到管道并没有如预期那样膨胀。"}},{"pos":"V-ERG 及物/不及物动词","cn":"扩大；发展；扩展","en":"If something such as a business, organization, or service expands, or if you expand it, it becomes bigger and includes more people, goods, or activities.","ex":{"en":"The popular ceramics industry expanded towards the middle of the 19th century","cn":"到19世纪中期，大众制陶业得到了发展。"}},{"pos":"","cn":"","en":"相关词组：expand on"}]},"examples":[{"en":"In breathing the chest muscles expand the ribcage and allow air to be sucked into the lungs.","cn":"呼吸时胸部肌肉使胸廓扩大让空气吸入肺部。"},{"en":"I repeated the question and waited for her to expand.","cn":"我把问题重复了一遍，等着她详细回答。"}]},"exciting":{"media":{"uk":"media/uk/exciting__gb_1.mp3","us":"media/us/exciting__us_1.mp3"},"oxford":{"phon":"ɪkˈsaɪtɪŋ","pos":"adjective","senses":[{"en":"causing great interest or excitement","cn":"令人激动的；使人兴奋的","ex":{"en":"This is an exciting opportunity for me.","cn":"对我来说，这是一个激动人心的机会。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人兴奋的;令人激动的;刺激的","en":"If something is exciting, it makes you feel very happy or enthusiastic.","ex":{"en":"The race itself is very exciting","cn":"比赛本身非常刺激。"}}]},"examples":[{"en":"They watched dramatic pictures of the police raid on TV.","cn":"他们在电视上看到了警察突击搜捕的激动人心的画面。"},{"en":"They waited and waited for something exciting to happen.","cn":"他们等啊等啊，等待着激动人心的事情发生。"}]},"extent":{"media":{"uk":"media/uk/extent__gb_1.mp3","us":"media/us/extent__us_1.mp3"},"oxford":{"phon":"ɪkˈstent","pos":"noun","senses":[{"en":"how large, important, serious, etc. something is","cn":"程度；限度","ex":{"en":"It is difficult to assess the full extent of the damage.","cn":"损失情况难以全面估计。"}},{"en":"the physical size of an area","cn":"大小；面积；范围","ex":{"en":"You can't see the full extent of the beach from here.","cn":"从这儿不能看到海滩全貌。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"程度;地步","en":"If you are talking about how great, important, or serious a difficulty or situation is, you can refer to the extent of it.","ex":{"en":"The government itself has little information on the extent of industrial pollution","cn":"政府本身几乎不了解工业污染的程度。"}},{"pos":"N-SING 单数名词","cn":"范围;面积;大小","en":"The extent of something is its length, area, or size.","ex":{"en":"Their commitment was only to maintain the extent of forests, not their biodiversity.","cn":"他们仅承诺维持现有森林面积，并不保证林区生物的多样性。"}},{"pos":"PHRASE 短语","cn":"在很大程度上/ 在某种程度上/在一定程度上","en":"You use expressions such as to a large extent ,to some extent, or to a certain extent in order to indicate that something is partly true, but not entirely true.","ex":{"en":"It was and, to a large extent, still is a good show","cn":"它过去是个好节目，现在在很大程度上仍是个好节目。"}},{"pos":"PHRASE 短语","cn":"到何种程度/到那种程度/到…的程度","en":"You use expressions such as to what extent ,to that extent, or to the extent that when you are discussing how true a statement is, or in what ways it is true.","ex":{"en":"It's still not clear to what extent this criticism is originating from within the ruling party","cn":"目前仍不清楚这种批评有多少是来自执政党内部。"}},{"pos":"PHRASE 短语","cn":"（表示强调）到…的地步，到…的程度","en":"You use expressions such as to the extent of ,to the extent that, or to such an extent that in order to emphasize that a situation has reached a difficult, dangerous, or surprising stage.","ex":{"en":"He said he didn't like the president, but not to the extent of wanting to kill him","cn":"他说他不喜欢总统，但是还没有到想要刺杀他的地步。"}}]},"examples":[{"en":"The pollution of the forest has seriously affected plant life and, to a lesser extent, wildlife.","cn":"森林污染严重影响了植物的生存，其次也对野生动物造成了影响。"},{"en":"The book discusses the extent to which (= how much) family life has changed over the past 50 years.","cn":"本书论述了近 50 年来家庭生活的变化程度。"}]},"expertise":{"media":{"uk":"media/uk/expertise__gb_1.mp3","us":"media/us/expertise__us_1.mp3"},"oxford":{"phon":"ˌekspɜːˈtiːz","pos":"noun","senses":[{"en":"expert knowledge or skill in a particular subject, activity or job","cn":"专门知识；专门技能；专长","ex":{"en":"professional/scientific/technical, etc. expertise","cn":"专业、科学、技术等知识"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"专门技术;专门知识;专长","en":"Expertise is special skill or knowledge that is acquired by training, study, or practice.","ex":{"en":"The problem is that most local authorities lack the expertise to deal sensibly in this market.","cn":"问题是大多数地方政府都缺乏合理应对这个市场的专门知识。"}}]},"examples":[{"en":"We have the expertise to help you run your business.","cn":"我们有帮助你经营自己业务的专门知识。"},{"en":"They have considerable expertise in dealing with oil spills.","cn":"他们在解决溢油问题方面非常在行。"}]},"exploitative":{"media":{"uk":"media/uk/exploitative__gb_1.mp3","us":"media/us/exploitative__us_1.mp3"},"oxford":{"phon":"ɪkˈsplɔɪtətɪv","pos":"adjective","senses":[{"en":"treating somebody unfairly in order to gain an advantage or to make money","cn":"剥削的；榨取的","ex":{"en":"an exploitative economic system","cn":"剥削性的经济制度"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"剥削的;压榨的","en":"If you describe something as exploitative, you disapprove of it because it treats people unfairly by using their work or ideas for its own advantage, and giving them very little in return.","ex":{"en":"The expansion of Western capitalism incorporated the Third World into an exploitative world system.","cn":"西方资本主义的扩张将第三世界并入了剥削性的世界体系中。"}}]},"examples":[{"en":"the exploitative nature of multinational companies","cn":"跨国公司的剥削本质"}]},"excitement":{"media":{"uk":"media/uk/excitement__gb_1.mp3","us":"media/us/excitement__us_1.mp3"},"oxford":{"phon":"ɪkˈsaɪtmənt","pos":"noun","senses":[{"en":"the state of feeling or showing happiness and enthusiasm","cn":"激动；兴奋；刺激","g":"[uncountable]","ex":{"en":"The news caused great excitement among her friends.","cn":"这消息使她的朋友们兴奋不已。"}},{"en":"something that you find exciting","cn":"令人激动（或兴奋）的事","g":"[countable]","lab":"formal","ex":{"en":"The new job was not without its excitements.","cn":"这个新工作并非枯燥无味。"}},{"en":"the state of feeling sexual desire","cn":"性兴奋","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"兴奋;激动;刺激;令人兴奋的事物","en":"You use excitement to refer to the state of being excited, or to something that excites you.","ex":{"en":"Everyone is in a state of great excitement.","cn":"每个人都大为兴奋。"}}]},"examples":[{"en":"The news caused great excitement among her friends.","cn":"这消息使她的朋友们兴奋不已。"},{"en":"He was flushed with excitement at the thought.","cn":"他想到这就激动得满脸通红。"}]},"excitedly":{"oxford":{"phon":"ɪkˈsaɪtɪdli","pos":"adverb","senses":[{"en":"in a happy and enthusiastic way","cn":"兴奋地；激动地","ex":{"en":"She waved excitedly as the car approached.","cn":"汽车开近时她激动地挥手。"}}]},"media":{"uk":"media/uk/excitedly__gb_1.mp3","us":"media/us/excitedly__us_1.mp3"},"examples":[{"en":"She waved excitedly as the car approached.","cn":"汽车开近时她激动地挥着手。"},{"en":"Steve flies home tomorrow – we’re all really excited.","cn":""}]},"exhibit":{"oxford":{"phon":"ɪɡˈzɪbɪt","pos":"verb","senses":[{"en":"to show something in a public place for people to enjoy or to give them information","cn":"展览；展出","g":"[transitive, intransitive]","ex":{"en":"They will be exhibiting their new designs at the trade fairs.","cn":"他们将在商品交易会上展出他们新的设计。"}},{"en":"to show clearly that you have or feel a particular quality, ability, feeling or symptom","cn":"表现，显示，显出（品质、能力、感情或症状）","g":"[transitive]","lab":"formal","ex":{"en":"The patient exhibited signs of fatigue and memory loss.","cn":"病人表现出疲劳和记忆力丧失的迹象。"}},{"en":"an object or a collection of objects put in a public place, for example a museum, so that people can see it","cn":"（一件或一批）展览品，陈列品","ex":{"en":"The museum contains some interesting exhibits on Spanish rural life.","cn":"博物馆内有一些关于西班牙乡村生活的有趣展品。"},"pos":"noun"},{"en":"a collection of things, for example works of art, that are shown to the public","cn":"（一批）展览品","lab":"North American English","ex":{"en":"The new exhibit will tour a dozen US cities next year.","cn":"这批新展品明年将在美国十几个城市巡回展出。"},"pos":"noun"},{"en":"a thing that is used in court to prove that somebody is guilty or not guilty","cn":"（在法庭上出示的）物证，证据","ex":{"en":"The first exhibit was a knife which the prosecution claimed was the murder weapon.","cn":"当庭出示的第一件物证是原告称为杀人凶器的一把刀。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"表现;显示","en":"If someone or something shows a particular quality, feeling, or type of behaviour, you can say that they exhibit it.","ex":{"en":"He has exhibited symptoms of anxiety and overwhelming worry","cn":"他表现出焦躁不安和过度忧虑的症状。"}},{"pos":"VERB 动词","cn":"展览;展出;陈列","en":"When a painting, sculpture, or object of interest is exhibited, it is put in a public place such as a museum or art gallery so that people can come to look at it. You can also say that animals are exhibited in a zoo.","ex":{"en":"His work was exhibited in the best galleries in America, Europe and Asia.","cn":"他的作品在美洲、欧洲和亚洲最好的美术馆展出。"}},{"pos":"VERB 动词","cn":"举办展览会;展出作品","en":"When artists exhibit, they show their work in public.","ex":{"en":"By 1936 she was exhibiting at the Royal Academy.","cn":"到1936年她已在皇家艺术学院展出作品。"}},{"pos":"N-COUNT 可数名词","cn":"展品;陈列品","en":"An exhibit is a painting, sculpture, or object of interest that is displayed to the public in a museum or art gallery.","ex":{"en":"Shona showed me round the exhibits.","cn":"肖纳带我参观了展品。"}},{"pos":"N-COUNT 可数名词","cn":"展览;展出","en":"An exhibit is a public display of paintings, sculpture, or objects of interest, for example in a museum or art gallery.","ex":{"en":"...an exhibit at the Metropolitan Museum of Art.","cn":"大都会艺术博物馆的展览"}},{"pos":"N-COUNT 可数名词","cn":"（在法庭上出示的）证据，证物","en":"An exhibit is an object that a lawyer shows in court as evidence in a legal case."},{"pos":"VERB 动词","cn":"展示;炫耀;表明","en":"If you say that someone exhibits something, you mean that they are showing it openly or publicly in order to be admired, noticed, or believed.","ex":{"en":"Other women seemed content and even exhibited their bellies with pride","cn":"其他女人似乎很满足，甚至还骄傲地炫耀她们的肚腩。"}}]},"media":{"uk":"media/uk/exhibit__gb_1.mp3","us":"media/us/exhibit__us_1.mp3"},"examples":[{"en":"The first exhibit was a knife which the prosecution claimed was the murder weapon.","cn":"当庭出示的第一件物证就是原告称为杀人凶器的一把刀。"},{"en":"The new exhibit will tour a dozen US cities next year.","cn":"这批新展品明年将在美国十二个城市巡回展出。"}]},"exact":{"media":{"uk":"media/uk/exact__gb_1.mp3","us":"media/us/exact__us_1.mp3"},"oxford":{"phon":"ɪɡˈzækt","pos":"adjective","senses":[{"en":"correct in every detail","cn":"精确的；准确的","lab":"informal","ex":{"en":"The new palace is an exact replica of the original building.","cn":"新宫殿是原建筑一模一样的复制品。"}},{"en":"very accurate and careful about details","cn":"严谨的；严格的；一丝不苟的","ex":{"en":"He was very exact about everything he did.","cn":"他对自己所做的一切都非常精确。"}},{"en":"using accurate measurements and following set rules","cn":"精密的；严密的","ex":{"en":"Assessing insurance risk can never be an exact science.","cn":"估定承保的风险永远不会成为一门精确的科学。"}},{"en":"to demand and get something from somebody","cn":"要求；索取","ex":{"en":"She was determined to exact a promise from him.","cn":"她决意要他作出许诺。"},"pos":"verb"},{"en":"to make something bad happen to somebody","cn":"迫使；强迫；强求","ex":{"en":"He exacted (= took) a terrible revenge for their treatment of him.","cn":"他因受他们的虐待而痛加报复。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精确的;正确的;确切的","en":"Exact means correct in every detail. For example, an exact copy is the same in every detail as the thing it is copied from.","ex":{"en":"I don't remember the exact words","cn":"我不记得确切的话语。"}},{"pos":"ADJ 形容词","cn":"（用于名词前表强调）刚好的，确切的","en":"You use exact before a noun to emphasize that you are referring to that particular thing and no other, especially something that has a particular significance.","ex":{"en":"I hadn't really thought about it until this exact moment","cn":"直到这时我才真正开始考虑它。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一丝不苟的;严谨的","en":"If you describe someone as exact, you mean that they are very careful and detailed in their work, thinking, or methods.","ex":{"en":"Formal, exact and obstinate, he was also cold, suspicious, touchy and tactless.","cn":"严肃、严谨、倔强的他同时又冷漠、多疑、敏感、不会变通。"}},{"pos":"VERB 动词","cn":"强求;勒索;强迫","en":"When someone exacts something, they demand and obtain it from another person, especially because they are in a superior or more powerful position.","ex":{"en":"Already he has exacted a written apology from the chairman of the commission","cn":"他已经强行要求委员会主席作出书面道歉。"}},{"pos":"VERB 动词","cn":"实施，施加（报复）","en":"If someone exacts revenge on a person, they have their revenge on them.","ex":{"en":"She uses the media to help her exact a terrible revenge.","cn":"她利用媒体帮助自己进行可怕的复仇。"}},{"pos":"VERB 动词","cn":"对…有害；使…付出代价","en":"If something exacts a high price, it has a bad effect on a person or situation.","ex":{"en":"The sheer physical effort had exacted a heavy price","cn":"纯粹的体力劳动已经产生了极其不利的影响。"}},{"pos":"PHRASE 短语","cn":"确切地说;精确地说","en":"You say to be exact to indicate that you are slightly correcting or giving more detailed information about what you have been saying.","ex":{"en":"A small number — five, to be exact—have been bad","cn":"一小部分——确切地说是5个——已经坏了。"}}]},"examples":[{"en":"He started to phone me at the exact moment I started to phone him (= at the same time).","cn":"他开始给我打电话时，我也正好开始给他打电话。"},{"en":"Assessing insurance risk can never be an exact science.","cn":"估定承保的风险永远不会成为一门精确的科学。"}]},"expressive":{"oxford":{"phon":"ɪkˈspresɪv","pos":"adjective","senses":[{"en":"showing or able to show your thoughts and feelings","cn":"富于表情的；有表现力的；意味深长的","ex":{"en":"She has wonderfully expressive eyes.","cn":"她有一双会说话的眼睛。"}},{"en":"showing something; existing as an expression of something","cn":"表现；表达；表示","g":"[not before noun]","lab":"formal","ex":{"en":"Every word and gesture is expressive of the artist's sincerity.","cn":"这位艺术家的真诚从一言一行中表现出来。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富于表情的;富于表现力的","en":"If you describe a person or their behaviour as expressive, you mean that their behaviour clearly indicates their feelings or intentions.","ex":{"en":"You can train people to be more expressive.","cn":"可以训练人们使其更具表现力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"表达…的;表现…的","en":"If something is expressive of particular ideas or qualities, it has features which indicate or demonstrate them.","ex":{"en":"Perhaps all his poems were really love poems, expressive of love for someone","cn":"也许他所有的诗歌其实都是爱情诗，表现了对某个人的爱。"}}]},"media":{"uk":"media/uk/expressive__gb_1.mp3","us":"media/us/expressive__us_1.mp3"},"examples":[{"en":"Every word and gesture is expressive of the artist's sincerity.","cn":"这位艺术家的真诚从一言一行中表现出来。"},{"en":"She has wonderfully expressive eyes.","cn":"她有一双会说话的眼睛。"}]},"expecting":{"lemma":"expect","media":{"uk":"media/uk/expect__gb_1.mp3","us":"media/us/expect__us_1.mp3"}},"express":{"media":{"uk":"media/uk/express__gb_1.mp3","us":"media/us/express__us_1.mp3"},"oxford":{"phon":"ɪkˈspres","pos":"verb","senses":[{"en":"to show or make known a feeling, an opinion, etc. by words, looks or actions","cn":"表示；表达；表露","ex":{"en":"Teachers have expressed concern about the changes.","cn":"教师对这些变化表示忧虑。"}},{"en":"to speak, write or communicate in some other way what you think or feel","cn":"表达（自己的思想感情）","lab":"formal","ex":{"en":"Teenagers often have difficulty expressing themselves.","cn":"十来岁的孩子在表达思想方面常常有困难。"}},{"en":"to become obvious in a particular way","cn":"显而易见；不言自明","lab":"formal","ex":{"en":"Their pleasure expressed itself in a burst of applause.","cn":"他们的喜悦从一阵热烈的掌声中表现出来。"}},{"en":"to represent something in a particular way, for example by symbols","cn":"（用符号等）表示，代表","lab":"mathematics","ex":{"en":"The figures are expressed as percentages.","cn":"这些数字用百分数表示。"}},{"en":"to remove air or liquid from something by pressing","cn":"压榨，挤压出（空气或液体）","ex":{"en":"Coconut milk is expressed from grated coconuts.","cn":"椰子汁是从擦碎的椰肉里榨出来的。"}},{"en":"to send something by express post","cn":"快递邮寄（或发送）","lab":"North American English","ex":{"en":"As soon as I receive payment I will express the book to you.","cn":"我一收到款就把书用快递给你寄去。"}},{"en":"travelling very fast; operating very quickly","cn":"特快的；快速的；快递的","ex":{"en":"an express bus/coach/train","cn":"特快公共汽车／长途汽车／列车"},"pos":"adjective"},{"en":"sent by express service","cn":"用快递寄送的","ex":{"en":"express mail","cn":"特快邮件"},"pos":"adjective"},{"en":"providing an express service","cn":"提供快递服务的","lab":"North American English","ex":{"en":"an air express company","cn":"航空快递公司"},"pos":"adjective"},{"en":"clearly and openly stated","cn":"明确的；明白表示的","lab":"formal","ex":{"en":"It was his express wish that you should have his gold watch after he died.","cn":"他明确表示死后把金表留给你。"},"pos":"adjective"},{"en":"using a special fast service","cn":"使用快速服务","ex":{"en":"I'd like to send this express, please.","cn":"劳驾，我要寄快递。"},"pos":"adverb"},{"en":"a fast train that does not stop at many places","cn":"特快列车","g":"[countable]","ex":{"en":"the 8.27 express to Edinburgh","cn":"8:27 开往爱丁堡的特快列车"},"pos":"noun"},{"en":"a service for sending or transporting things quickly","cn":"快件服务；快递服务；快运服务","g":"[uncountable]","lab":"British English also","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"表达;表述","en":"When you express an idea or feeling, or express yourself, you show what you think or feel.","ex":{"en":"He expressed grave concern at American attitudes","cn":"他对美国的态度表示严重关切。"}},{"pos":"VERB 动词","cn":"（观点、感情等）体现，不言自明","en":"If an idea or feeling expresses itself in some way, it can be clearly seen in someone's actions or in its effects on a situation.","ex":{"en":"The anxiety of the separation often expresses itself as anger towards the child for getting lost.","cn":"离散带来的焦虑常常体现为对走失的孩子发火。"}},{"pos":"VERB 动词","cn":"（用符号等）表示，表达","en":"In mathematics, if you express a quantity or mathematical problem in a particular way, you write it using particular symbols, figures, or equations.","ex":{"en":"We can express that equation like that","cn":"我们可以这样表示那个等式。"}},{"pos":"ADJ 形容词","cn":"（命令）明白表示的，明确的","en":"An express command or order is one that is clearly and deliberately stated.","ex":{"en":"The ship was sunk on express orders from the Prime Minister.","cn":"遵照首相的明确指令，那艘船被击沉了。"}},{"pos":"ADJ 形容词","cn":"（目的或意图）明确的，特别的","en":"If you refer to an express intention or purpose, you are emphasizing that it is a deliberate and specific one that you have before you do something.","ex":{"en":"I had obtained my first camera for the express purpose of taking railway photographs.","cn":"我已经买了我的第一架照相机，专门用来拍摄铁路。"}},{"pos":"ADJ 形容词","cn":"快递的;特快的;快速的","en":"Express is used to describe special services which are provided by companies or organizations such as the Post Office, in which things are sent or done faster than usual for a higher price.","ex":{"en":"A special express service is available by fax","cn":"提供传真特快专递服务。"}},{"pos":"N-COUNT 可数名词","cn":"特快列车","en":"An express or an express train is a fast train which stops at very few stations.","ex":{"en":"Punctually at 7.45, the express to Kuala Lumpur left Singapore station","cn":"7点45分，开往吉隆坡的特快列车准时驶离新加坡火车站。"}},{"pos":"N-COUNT 可数名词","cn":"特快公共汽车（或长途汽车）;直达公共汽车（或长途汽车）","en":"An express is a fast bus or coach which goes from one place to another directly or with very few stops."}]},"examples":[{"en":"Teenagers often have difficulty expressing themselves.","cn":"十来岁的孩子在表达思想方面常常有困难。"},{"en":"She expresses herself most fully in her paintings.","cn":"她把自己的感情在画作中表现得淋漓尽致。"}]},"explanatory":{"oxford":{"phon":"ɪkˈsplænətri","pos":"adjective","senses":[{"en":"giving the reasons for something; intended to describe how something works or to make something easier to understand","cn":"解释的；说明的；阐述的","ex":{"en":"There are explanatory notes at the back of the book.","cn":"书后有注解。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"解释性的;说明性的","en":"Explanatory statements or theories are intended to make people understand something by describing it or giving the reasons for it.","ex":{"en":"These statements are accompanied by a series of explanatory notes","cn":"这些陈述后面有一系列解释性注释。"}}]},"media":{"uk":"media/uk/explanatory__gb_1.mp3","us":"media/us/explanatory__us_1.mp3"},"examples":[{"en":"There are explanatory notes at the back of the book.","cn":"书后有注解。"},{"en":"There are explanatory notes at the end of each chapter.","cn":"每一章末尾都有注释。"}]},"exhibition":{"media":{"uk":"media/uk/exhibition__gb_1.mp3","us":"media/us/exhibition__us_1.mp3"},"oxford":{"phon":"ˌeksɪˈbɪʃn","pos":"noun","senses":[{"en":"a collection of things, for example works of art, that are shown to the public","cn":"（一批）展览品","g":"[countable]","lab":"especially British English","ex":{"en":"Have you seen the Picasso exhibition?","cn":"你看过毕加索的画展吗？"}},{"en":"the act of showing something, for example works of art, to the public","cn":"展览；展出","g":"[uncountable]","ex":{"en":"She refused to allow the exhibition of her husband's work.","cn":"她拒不允许展出她丈夫的作品。"}},{"en":"the act of showing a skill, a feeling, or a kind of behaviour","cn":"（技能、感情或行为的）表现，显示，表演","g":"[singular]","lab":"formal","ex":{"en":"We were treated to an exhibition of the footballer's speed and skill.","cn":"足球运动员表现出的速度和技术，真让我们大饱眼福。"}},{"en":"an amount of money that is given as a prize to a student","cn":"奖学金","g":"[countable]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"展览会；展出","en":"An exhibition is a public event at which pictures, sculptures, or other objects of interest are displayed, for example at a museum or art gallery.","ex":{"en":"...an exhibition of expressionist art.","cn":"表现派艺术展览会"}},{"pos":"N-SING 单数名词","cn":"展示；显示","en":"An exhibition of a particular skilful activity is a display or example of it that people notice or admire.","ex":{"en":"He responded in champion's style by treating the fans to an exhibition of power and speed.","cn":"他向崇拜者展示了他的力量和速度，表现得颇有冠军风范。"}}]},"examples":[{"en":"We were treated to an exhibition of the footballer's speed and skill.","cn":"足球运动员表现出的速度和技术，真让我们大饱眼福。"},{"en":"She refused to allow the exhibition of her husband's work.","cn":"她拒不允许展出她丈夫的作品。"}]},"exacting":{"media":{"uk":"media/uk/exacting__gb_1.mp3","us":"media/us/exacting__us_1.mp3"},"oxford":{"phon":"ɪɡˈzæktɪŋ","pos":"adjective","senses":[{"en":"needing or demanding a lot of effort and care about details","cn":"严谨细致的；要求小心仔细的；要求严格的","ex":{"en":"exacting work","cn":"艰巨的工作"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费劲的;苛刻的；要求严格的","en":"You use exacting to describe something or someone that demands hard work and a great deal of care.","ex":{"en":"The Duke was not well enough to carry out such an exacting task","cn":"公爵身体不太好，无法执行那么艰巨的任务。"}}]},"examples":[{"en":"products designed to meet the exacting standards of today's marketplace","cn":"为符合当今市场严格的标准而设计的产品"},{"en":"He was an exacting man to work for.","cn":"他对手下的人要求极为严格。"}],"base":"exact"},"excerpts":{"lemma":"excerpt","media":{"uk":"media/uk/excerpt__gb_1.mp3","us":"media/us/excerpt__us_1.mp3"}},"exchanging":{"lemma":"exchange"},"exclamation":{"oxford":{"phon":"ˌekskləˈmeɪʃn","pos":"noun","senses":[{"en":"a short sound, word or phrase spoken suddenly to express an emotion. Oh!, Look out! and Ow! are exclamations.","cn":"感叹；感叹语；感叹词","ex":{"en":"He gave an exclamation of surprise.","cn":"他发出一声惊叹。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"惊叫;感叹;感叹词;感叹句","en":"An exclamation is a sound, word, or sentence that is spoken suddenly, loudly, or emphatically and that expresses excitement, admiration, shock, or anger.","ex":{"en":"Sue gave an exclamation as we got a clear sight of the house.","cn":"我们清楚看到那所房子时，休惊叹不已。"}}]},"media":{"uk":"media/uk/exclamation__gb_1.mp3","us":"media/us/exclamation__us_1.mp3"},"examples":[{"en":"He gave an exclamation of surprise.","cn":"他发出一声惊叹。"},{"en":"horrified exclamations of disgust","cn":"厌恶的惊叫"}]},"exceptionally":{"media":{"uk":"media/uk/exceptionally__gb_1.mp3","us":"media/us/exceptionally__us_1.mp3"},"oxford":{"phon":"ɪkˈsepʃənəli","pos":"adverb","senses":[{"en":"used before an adjective or adverb to emphasize how strong or unusual the quality is","cn":"（用于形容词和副词之前表示强调）罕见，特别，非常","ex":{"en":"The weather, even for January, was exceptionally cold.","cn":"这种天气即使在一月份也算得上非常寒冷。"}},{"en":"only in unusual circumstances","cn":"只有在特殊情况下；例外地","ex":{"en":"Exceptionally, students may be accepted without formal qualifications.","cn":"在特殊情况下，也可能接受无正式文凭的学生。"}}]},"examples":[{"en":"Exceptionally, students may be accepted without formal qualifications.","cn":"在特殊情况下，也可能接受无正式文凭的学生。"},{"en":"The weather, even for January, was exceptionally cold.","cn":"这种天气即使在一月份也算得上非常寒冷。"}]},"extraordinary":{"media":{"uk":"media/uk/extraordinary__gb_1.mp3","us":"media/us/extraordinary__us_1.mp3"},"oxford":{"phon":"ɪkˈstrɔːdnri","pos":"adjective","senses":[{"en":"unexpected, surprising or strange","cn":"意想不到的；令人惊奇的；奇怪的","ex":{"en":"What an extraordinary thing to say!","cn":"说这话太奇怪了！"}},{"en":"not normal or ordinary; greater or better than usual","cn":"不平常的；不一般的；非凡的；卓越的","ex":{"en":"an extraordinary achievement","cn":"卓越的成就"}},{"en":"arranged for a special purpose and happening in addition to what normally or regularly happens","cn":"特别的；临时的","g":"[only before noun]","lab":"formal","ex":{"en":"An extraordinary meeting was held to discuss the problem.","cn":"举行了特别会议讨论这个问题。"}},{"en":"employed for a special purpose in addition to the usual staff","cn":"特派的；特命的","lab":"specialist","ex":{"en":"an envoy extraordinary","cn":"特使"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非凡的;优秀的;出色的","en":"If you describe something or someone as extraordinary, you mean that they have some extremely good or special quality.","ex":{"en":"We've made extraordinary progress as a society in that regard","cn":"在那个方面，我们的社会已经取得了巨大的进步。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常奇特的;令人惊奇的","en":"If you describe something as extraordinary, you mean that it is very unusual or surprising.","ex":{"en":"What an extraordinary thing to happen!","cn":"这事儿真蹊跷！"}},{"pos":"ADJ 形容词","cn":"（会议）特别的","en":"An extraordinary meeting is arranged specially to deal with a particular situation or problem, rather than happening regularly.","ex":{"en":"...at an extraordinary meeting of the sport's ruling body","cn":"在体育运动管理机构的特别会议上"}}]},"examples":[{"en":"It's extraordinary that he managed to sleep through the party.","cn":"真想不到他竟然从聚会开始一直睡到结束。"},{"en":"He behaves extraordinarily for someone in his position.","cn":"对他那种地位的人来说，他的行为很特别。"}]},"expedition":{"media":{"uk":"media/uk/expedition__gb_1.mp3","us":"media/us/expedition__us_1.mp3"},"oxford":{"phon":"ˌekspəˈdɪʃn","pos":"noun","senses":[{"en":"an organized journey with a particular purpose, especially to find out about a place that is not well known","cn":"远征；探险；考察","ex":{"en":"to plan/lead/go on an expedition","cn":"计划／带队／去探险"}},{"en":"the people who go on an expedition","cn":"远征队；探险队；考察队","ex":{"en":"Three members of the Everest expedition were killed.","cn":"三名珠穆朗玛峰探险队员遇难。"}},{"en":"a short trip that you make when you want or need something","cn":"（短途的）旅行，出行","lab":"sometimes humorous","ex":{"en":"Win a fantastic shopping expedition to New York!","cn":"赢得远征纽约的精彩购物之旅！"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"远征;探险","en":"An expedition is an organized journey that is made for a particular purpose such as exploration.","ex":{"en":"...Byrd's 1928 expedition to Antarctica.","cn":"伯德1928年前往南极洲的探险"}},{"pos":"N-COUNT 可数名词","cn":"远征队;探险队","en":"You can refer to a group of people who are going on an expedition as an expedition .","ex":{"en":"Forty-three members of the expedition were killed.","cn":"探险队中43名成员遇难。"}},{"pos":"N-COUNT 可数名词","cn":"远足;短途旅行","en":"An expedition is a short journey or trip that you make for pleasure.","ex":{"en":"Caroline joined them on the shopping expeditions.","cn":"卡罗琳加入了他们的购物之旅。"}}]},"examples":[{"en":"Three members of the Everest expedition were killed.","cn":"三名珠穆朗玛峰探险队员遇难。"},{"en":"to plan/lead/go on an expedition to the North Pole","cn":"计划/带队/去北极探险"}]},"extension":{"oxford":{"phon":"ɪkˈstenʃn","pos":"noun","senses":[{"en":"the act of increasing the area of activity, group of people, etc. that is affected by something","cn":"扩大；延伸","g":"[uncountable, countable]","sc":"increasing influence","ex":{"en":"the extension of new technology into developing countries","cn":"新技术向发展中国家的传播"}},{"en":"a new room or rooms that are added to a house","cn":"增加的房间","g":"[countable]","lab":"North American English also","sc":"of building","ex":{"en":"They're building an extension to their house.","cn":"他们正在扩建自家的房屋。"}},{"en":"a new part that is added to a building","cn":"扩建部分；增建部分","g":"[countable]","sc":"of building","ex":{"en":"a planned two-storey extension to the hospital","cn":"计划在医院增建一栋两层的楼"}},{"en":"an extra period of time allowed for something","cn":"延期；延长期；放宽的期限","g":"[countable]","lab":"British English","sc":"extra time","ex":{"en":"He's been granted an extension of the contract for another year.","cn":"他的合同获得延期一年。"}},{"en":"an extra phone line connected to a central phone in a house or to a switchboard in a large building. In a large building, each extension usually has its own number.","cn":"电话分级线；分机号码","g":"[countable]","sc":"phone","ex":{"en":"We have an extension in the bedroom.","cn":"我们的卧室里有一个分机。"}},{"en":"the act of making something longer or larger; the thing that is made longer and larger","cn":"延长；扩大；延长（或扩大）的事物","g":"[uncountable, countable]","sc":"making something longer/larger","ex":{"en":"The extension of the subway will take several months.","cn":"扩建地铁需用几个月时间。"}},{"en":"pieces of artificial hair that are added to somebody's own hair to make it longer","cn":"（接发用的）假发","g":"[countable, usually plural]","sc":"hair","ex":{"en":"These extensions are very easy to use and won't damage your own hair.","cn":"这些接发器非常易于使用，不会损坏您自己的头发。"}},{"en":"a part of a college or university that offers courses to students who are not studying full-time; a programme of study for these students","cn":"（为非全日制学生开设的）进修部，进修课","g":"[countable]","sc":"college/university","ex":{"en":"La Salle Extension University","cn":"拉萨尔大学进修部"}},{"en":"the set of three letters that are placed after the dot (= small round mark) at the end of the name of a file and that show what type of file it is","cn":"扩展名","g":"[countable]","sc":"computing","ex":{"en":"The extension .doc indicates a word-processing file.","cn":"扩展名 .doc 表示文字处理文件。"}},{"en":"an extra length of electric wire, used when the wire on an electrical device is not long enough","cn":"接长线路，延长线（电器上的电线加长部分）","g":"[countable]","lab":"both British English","sc":"electrical"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（房屋的）扩建部分","en":"An extension is a new room or building which is added to an existing building or group of buildings."},{"pos":"N-COUNT 可数名词","cn":"（公路、铁路等的）延长线","en":"An extension is a new section of a road or rail line that is added to an existing road or line.","ex":{"en":"...the Jubilee Line extension.","cn":"银禧延长线"}},{"pos":"N-COUNT 可数名词","cn":"展期；延长期","en":"An extension is an extra period of time for which something lasts or is valid, usually as a result of official permission.","ex":{"en":"He first entered Britain on a six-month visa, and was given a further extension of six months","cn":"他最初持6个月的签证进入英国，后来又获得6个月的续签。"}},{"pos":"N-COUNT 可数名词","cn":"扩大;扩展;延伸","en":"Something that is an extension of something else is a development of it that includes or affects more people, things, or activities.","ex":{"en":"Many Filipinos see the bases as an extension of American colonial rule","cn":"很多菲律宾人视这些基地为美国殖民统治的延续。"}},{"pos":"N-COUNT 可数名词","cn":"电话分机（亦用书面缩略ext.）","en":"An extension is a telephone line that is connected to the switchboard of a company or institution, and that has its own number. The written abbreviation ext. is also used.","ex":{"en":"She can get me on extension 308","cn":"她打308分机就能联系到我。"}},{"pos":"N-COUNT 可数名词","cn":"（设备的）延伸部分","en":"An extension is a part which is connected to a piece of equipment in order to make it reach something further away.","ex":{"en":"...a 30-foot extension cord... 30","cn":"英尺的延长线"}}]},"media":{"uk":"media/uk/extension__gb_1.mp3","us":"media/us/extension__us_1.mp3"},"examples":[{"en":"( BrE ) The pub had an extension (= was allowed to stay open longer) on Christmas Eve.","cn":"这家酒吧已获准在圣诞前夕延长营业时间。"},{"en":"The blame lies with the teachers and, by extension, with the Education Service.","cn":"应受指责的是教师，再则就是教育机构。"}]},"export":{"media":{"uk":"media/uk/export__gb_1.mp3","us":"media/us/export__us_1.mp3"},"oxford":{"phon":"ˈekspɔːt","pos":"noun","senses":[{"en":"the selling and transporting of goods to another country","cn":"出口；输出","g":"[uncountable]","ex":{"en":"a ban on the export of live cattle","cn":"禁止活牛出口"}},{"en":"a product that is sold to another country","cn":"出口产品；输出品","g":"[countable, usually plural]","ex":{"en":"the country’s major exports","cn":"该国的主要出口产品"}},{"en":"to sell and send goods to another country","cn":"出口；输出","g":"[transitive, intransitive]","ex":{"en":"The islands export sugar and fruit.","cn":"这些岛出口糖和水果。"},"pos":"verb"},{"en":"to introduce an idea or activity to another country or area","cn":"传播，输出（思想或活动）","g":"[transitive]","ex":{"en":"American pop music has been exported around the world.","cn":"美国流行音乐已传播到世界各地。"},"pos":"verb"},{"en":"to send data to another program, changing its form so that the other program can read it","cn":"输出；移出；调出","g":"[transitive]","lab":"computing","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"出口；输出","en":"To export products or raw materials means to sell them to another country.","ex":{"en":"The nation also exports beef","cn":"该国也出口牛肉。"}},{"pos":"N-COUNT 可数名词","cn":"输出品;出口商品","en":"Exports are goods which are sold to another country and sent there.","ex":{"en":"He did this to promote American exports","cn":"他这么做是为了推广美国出口产品。"}},{"pos":"VERB 动词","cn":"输出;传播","en":"To export something means to introduce it into another country or make it happen there.","ex":{"en":"It has exported inflation at times.","cn":"它有时会输出通货膨胀。"}},{"pos":"VERB 动词","cn":"（在计算机中）导出，输出","en":"In computing, if you export files or information from one type of software into another type, you change their format so that they can be used in the new software.","ex":{"en":"Files can be exported in ASCII or PCX formats.","cn":"文件可以以ASCII或者PCX格式导出。"}}]},"examples":[{"en":"American pop music has been exported around the world.","cn":"美国流行音乐已传播到世界各地。"},{"en":"90% of the engines are exported to Europe. * 90%","cn":"的发动机都出口到欧洲。"}]},"exhausted":{"media":{"uk":"media/uk/exhausted__gb_1.mp3","us":"media/us/exhausted__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɔːstɪd","pos":"adjective","senses":[{"en":"very tired","cn":"筋疲力尽的；疲惫不堪的","ex":{"en":"I'm exhausted!","cn":"我累死了！"}},{"en":"completely used or finished","cn":"用完的；耗尽的；枯竭的","ex":{"en":"You cannot grow crops on exhausted land.","cn":"地力耗尽的土地上种不了庄稼。"}}]},"examples":[{"en":"The exhausted climbers were rescued by helicopter.","cn":"筋疲力尽的登山者由直升机营救出来。"},{"en":"You cannot grow crops on exhausted land.","cn":"贫瘠的土地上种不了庄稼。"}],"base":"exhaust"},"explicit":{"media":{"uk":"media/uk/explicit__gb_1.mp3","us":"media/us/explicit__us_1.mp3"},"oxford":{"phon":"ɪkˈsplɪsɪt","pos":"adjective","senses":[{"en":"clear and easy to understand, so that you have no doubt what is meant","cn":"清楚明白的；毫不含糊的","ex":{"en":"He gave me very explicit directions on how to get there.","cn":"他清楚地向我说明了去那儿的路线。"}},{"en":"saying something clearly, exactly and openly","cn":"（说话）清晰的，明确的；直言的；坦率的","ex":{"en":"She was quite explicit about why she had left.","cn":"她对自己离开的原因直言不讳。"}},{"en":"describing or showing something, especially sexual activity, with a lot of detail","cn":"（尤指色情描写或画面）赤裸裸的，露骨的","lab":"usually disapproving","ex":{"en":"a sexually explicit film","cn":"一部有露骨性爱场面的影片"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明确的;清晰的;毫不隐讳的","en":"Something that is explicit is expressed or shown clearly and openly, without any attempt to hide anything.","ex":{"en":"...sexually explicit scenes in films and books.","cn":"电影和书籍中露骨的性爱片段"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"直言的;坦率的;坦诚的","en":"If you are explicit about something, you speak about it very openly and clearly.","ex":{"en":"He was explicit about his intention to overhaul the party's internal voting system.","cn":"他直言自己的目的是改革党内的投票制度。"}}]},"examples":[{"en":"He didn't like the degree of sexual explicitness in the film.","cn":"他不喜欢那部电影里性爱露骨的程度。"},{"en":"He gave me very explicit directions on how to get there.","cn":"他清楚地向我说明了去那儿的路线。"}]},"expected":{"media":{"uk":"media/uk/expected__gb_1.mp3","us":"media/us/expected__us_1.mp3"},"oxford":{"phon":"ɪkˈspektɪd","pos":"adjective","senses":[{"en":"that you think will happen","cn":"预料的；预期的","ex":{"en":"Double the expected number of people came to the meeting.","cn":"出席会议的人数比预期的多一倍。"}}]},"examples":[{"en":"Double the expected number of people came to the meeting.","cn":"出席会议的人数比预期的多一倍。"},{"en":"this year's expected earnings","cn":"今年的预计收入"}],"base":"expect"},"extensive":{"media":{"uk":"media/uk/extensive__gb_1.mp3","us":"media/us/extensive__us_1.mp3"},"oxford":{"phon":"ɪkˈstensɪv","pos":"adjective","senses":[{"en":"covering a large area; great in amount","cn":"广阔的；广大的；大量的","ex":{"en":"The house has extensive grounds.","cn":"这栋房子有宽敞的庭院。"}},{"en":"including or dealing with a wide range of information","cn":"广泛的；广博的","ex":{"en":"Extensive research has been done into this disease.","cn":"对这种疾病已进行了广泛研究。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广大的;广阔的","en":"Something that is extensive covers or includes a large physical area.","ex":{"en":"...an extensive tour of Latin America","cn":"在拉丁美洲广泛游历"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广泛的;全面的;包罗万象的","en":"Something that is extensive covers a wide range of details, ideas, or items.","ex":{"en":"Developments in South Africa receive extensive coverage in The Sunday Telegraph","cn":"《星期日电讯报》全面报道了南非的发展。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的；大量的","en":"If something is extensive, it is very great.","ex":{"en":"The blast caused extensive damage, shattering the ground-floor windows","cn":"爆炸造成了巨大的破坏，震碎了一楼的窗户。"}}]},"examples":[{"en":"Extensive research has been done into this disease.","cn":"对这种疾病已进行了广泛研究。"},{"en":"Extensive repair work is being carried out.","cn":"大规模的修缮工作正在进行。"}]},"example":{"media":{"uk":"media/uk/example__gb_1.mp3","us":"media/us/example__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɑːmpl","pos":"noun","senses":[{"en":"something such as an object, a fact or a situation that shows, explains or supports what you say","cn":"实例；例证；例子","ex":{"en":"Let me give you an example.","cn":"我给你举个例子。"}},{"en":"a thing that is typical of or represents a particular group or set","cn":"典型；范例；样品","ex":{"en":"This is a good example of the artist's early work.","cn":"这是这位艺术家早期作品的范例。"}},{"en":"a person or their behaviour that is thought to be a good model for others to copy","cn":"榜样；楷模；模范","ex":{"en":"Her courage is an example to us all.","cn":"她的勇气是我们大家的榜样。"}},{"en":"a person’s behaviour, either good or bad, that other people copy","cn":"样板；榜样","ex":{"en":"It would be a mistake to follow his example.","cn":"仿效他的做法是错误的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"例子;例证;实例","en":"An example of something is a particular situation, object, or person which shows that what is being claimed is true.","ex":{"en":"The doctors gave numerous examples of patients being expelled from hospital","cn":"医生们列举了大量病人被逐出医院的实例。"}},{"pos":"N-COUNT 可数名词","cn":"范例;样本;代表","en":"An example of a particular class of objects or styles is something that has many of the typical features of such a class or style, and that you consider clearly represents it.","ex":{"en":"Symphonies 103 and 104 stand as perfect examples of early symphonic construction","cn":"第103和104号交响曲是早期交响乐结构的典型代表。"}},{"pos":"PHRASE 短语","cn":"例如;比如","en":"You use for example to introduce and emphasize something which shows that something is true.","ex":{"en":"...'educational toys' that are designed to promote the development of, for example, children's spatial ability","cn":"旨在促进儿童发展，诸如空间能力发展的“教学玩具”"}},{"pos":"N-COUNT 可数名词","cn":"榜样;模范","en":"If you refer to a person or their behaviour as an example to other people, you mean that he or she behaves in a good or correct way that other people should copy.","ex":{"en":"He is a model professional and an example to the younger lads","cn":"他是个模范的专业人士，是年轻人的榜样。"}},{"pos":"N-COUNT 可数名词","cn":"（词典中的）例证，例子","en":"In a dictionary entry, an example is a phrase or sentence which shows how a particular word is used.","ex":{"en":"The examples are unique to this dictionary.","cn":"这些例证是这部词典独有的。"}},{"pos":"PHRASE 短语","cn":"（尤指出于敬意而）学习…的榜样，以…为榜样","en":"If you follow someone's example, you behave in the same way as they did in the past, or in a similar way, especially because you admire them.","ex":{"en":"Following the example set by her father, she has fulfilled her role and done her duty","cn":"她以父亲为榜样，完成了任务，履行了职责。"}},{"pos":"PHRASE 短语","cn":"惩罚…以警戒他人;杀一儆百","en":"To make an example of someone who has done something wrong means to punish them severely as a warning to other people not to do the same thing.","ex":{"en":"Let us at least see our courts make an example of these despicable criminals.","cn":"至少让我们看到法庭惩罚这些十恶不赦的罪犯以儆效尤。"}},{"pos":"PHRASE 短语","cn":"树立榜样；以身作则","en":"If you set an example, you encourage or inspire people by your behaviour to behave or act in a similar way.","ex":{"en":"An officer's job was to set an example","cn":"军官的职责就是树立榜样。"}}]},"examples":[{"en":"Just to give you an example of his generosity — he gave me his old car and wouldn't take any money for it.","cn":"且给你举个例子来说明他的慷慨吧 — 他把他的旧汽车给了我，而且分文不取。"},{"en":"It is possible to combine Computer Science with other subjects, for example Physics.","cn":"将计算机科学与其他学科，如物理学，结合起来是可能的。"}]},"exerting":{"lemma":"exert"},"existence":{"media":{"uk":"media/uk/existence__gb_1.mp3","us":"media/us/existence__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɪstəns","pos":"noun","senses":[{"en":"the state or fact of being real or living or of being present","cn":"存在；实有","g":"[uncountable]","ex":{"en":"I was unaware of his existence until today.","cn":"直到今天我才知道有他这么个人。"}},{"en":"a way of living, especially when this is difficult or boring","cn":"（尤指艰难或无聊的）生活，生活方式","g":"[countable]","ex":{"en":"The family endured a miserable existence in a cramped apartment.","cn":"这家人在狭小的公寓里艰难度日。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"存在;实有","en":"The existence of something is the fact that it is present in the world as a real thing.","ex":{"en":"...the existence of other galaxies","cn":"其他星系的存在"}},{"pos":"N-COUNT 可数名词","cn":"（尤指逆境中的）生活，生活方式","en":"You can refer to someone's way of life as an existence, especially when they live under difficult conditions.","ex":{"en":"You may be stuck with a miserable existence for the rest of your life","cn":"你可能一辈子都要过着悲惨的生活。"}}]},"examples":[{"en":"Pakistan came into existence as an independent country in 1947.","cn":"巴基斯坦在 1947 年成为了独立国家。"},{"en":"We led a poor but happy enough existence as children.","cn":"我们儿时的生活虽然贫穷却过得很愉快。"}]},"experimental":{"oxford":{"phon":"ɪkˌsperɪˈmentl","pos":"adjective","senses":[{"en":"based on new ideas, forms or methods that are used to find out what effect they have","cn":"以实验（或试验）为基础的；实验性的；试验性的","ex":{"en":"The school's experimental teaching methods include letting the children decide what to study.","cn":"学校的实验教学方法包括让孩子们决定学习什么。"}},{"en":"connected with scientific experiments","cn":"科学实验的；科学试验的","ex":{"en":"experimental conditions/data/evidence","cn":"实验环境／数据／证据"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"试验性的","en":"Something that is experimental is new or uses new ideas or methods, and might be modified later if it is unsuccessful.","ex":{"en":"...an experimental air conditioning system","cn":"试验性的空调系统"}},{"pos":"ADJ 形容词","cn":"实验的;用于实验的;根据实验的","en":"Experimental means using, used in, or resulting from scientific experiments.","ex":{"en":"...the main techniques of experimental science.","cn":"实验科学的主要技术"}},{"pos":"ADJ 形容词","cn":"（行动）试验性的，试探性的","en":"An experimental action is done in order to see what it is like, or what effects it has.","ex":{"en":"The British Sports Minister is reported to be ready to argue for an experimental lifting of the ban.","cn":"据报道，英国体育大臣准备争取试行取消那条禁令。"}}]},"media":{"uk":"media/uk/experimental__gb_1.mp3","us":"media/us/experimental__us_1.mp3"},"examples":[{"en":"This theory can be confirmed experimentally.","cn":"这种理论可通过实验得到证实。"},{"en":"He moved his shoulder experimentally to see if it still hurt.","cn":"他试着动了动肩看看还疼不疼。"}]},"examine":{"media":{"uk":"media/uk/examine__gb_1.mp3","us":"media/us/examine__us_1.mp3","img":["media/ldoce/img/examine.jpg"]},"oxford":{"phon":"ɪɡˈzæmɪn","pos":"verb","senses":[{"en":"to consider or study an idea, a subject, etc. very carefully","cn":"审查；调查；考查；考察","ex":{"en":"This study sets out to examine in detail the possible effects of climate change.","cn":"这项研究旨在详细考察气候变化可能带来的影响。"}},{"en":"to look at somebody/something closely, to see if there is anything wrong or to find the cause of a problem","cn":"（仔细地）检查，检验","ex":{"en":"The doctor examined her carefully but could find nothing wrong.","cn":"医生给她认真做了检查，但没发现什么问题。"}},{"en":"to give somebody a test to see how much they know about a subject or what they can do","cn":"考，测验（某人）","g":"[usually passive]","lab":"formal","ex":{"en":"The students will be examined in all subjects at the end of term.","cn":"期末时学生须要参加所有学科的考试。"}},{"en":"to ask somebody questions formally, especially in court","cn":"（尤指在法庭上）审问，查问","lab":"law","ex":{"en":"The prosecution examined 20 witnesses.","cn":"检方询问了20名证人。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"仔细检查;细查","en":"If you examine something, you look at it carefully.","ex":{"en":"He examined her passport and stamped it","cn":"他仔细检查了她的护照，然后在上面盖了章。"}},{"pos":"VERB 动词","cn":"（医生）诊察，检查","en":"If a doctor examines you, he or she looks at your body, feels it, or does simple tests in order to check how healthy you are.","ex":{"en":"Another doctor examined her and could still find nothing wrong","cn":"另外一名医生对她进行了诊察，仍旧没有发现任何问题。"}},{"pos":"VERB 动词","cn":"仔细研究;审查;剖析","en":"If an idea, proposal, or plan is examined, it is considered very carefully.","ex":{"en":"I have given the matter much thought, examining all the possible alternatives","cn":"这个问题我已经考虑了很多，分析了各种可能的选择。"}},{"pos":"VERB 动词","cn":"测验;考核","en":"If you are examined, you are given a formal test in order to show your knowledge of a subject.","ex":{"en":"...learning to cope with the pressures of being judged and examined by our teachers.","cn":"学会应对老师评判和测验时的压力"}}]},"examples":[{"en":"These ideas will be examined in more detail in Chapter 10.","cn":"这些观点将在第 10 章作更为详细的探讨。"},{"en":"We will study the report carefully before making a decision.","cn":"我们将认真研究这份报告，然后再作决定。"}]},"exaggerate":{"oxford":{"phon":"ɪɡˈzædʒəreɪt","pos":"verb","senses":[{"en":"to make something seem larger, better, worse or more important than it really is","cn":"夸张；夸大；言过其实","ex":{"en":"The hotel was really filthy and I'm not exaggerating.","cn":"我不是夸张，这旅店真的很脏。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"夸大;夸张","en":"If you exaggerate, you indicate that something is, for example, worse or more important than it really is.","ex":{"en":"He thinks I'm exaggerating","cn":"他觉得我在夸大其词。"}},{"pos":"VERB 动词","cn":"突出;夸大","en":"If something exaggerates a situation, quality, or feature, it makes the situation, quality, or feature appear greater, more obvious, or more important than it really is.","ex":{"en":"These figures exaggerate the loss of competitiveness","cn":"这些数字夸大了竞争力的丧失。"}}]},"media":{"uk":"media/uk/exaggerate__gb_1.mp3","us":"media/us/exaggerate__us_1.mp3"},"examples":[{"en":"I'm sure he exaggerates his Irish accent (= tries to sound more Irish than he really is).","cn":"我肯定他故意把爱尔兰口音说得很重。"},{"en":"Demand for the product has been greatly exaggerated.","cn":"对这项产品的需求给过分夸大了。"}]},"exhibitions":{"lemma":"exhibition","media":{"uk":"media/uk/exhibition__gb_1.mp3","us":"media/us/exhibition__us_1.mp3"}},"exam":{"oxford":{"phon":"ɪɡˈzæm","pos":"noun","senses":[{"en":"a formal written, spoken or practical test, especially at school or college, to see how much you know about a subject, or what you can do","cn":"（笔头、口头或操作）考试","lab":"British English","ex":{"en":"to take an exam","cn":"参加考试"}},{"en":"a medical test of a particular part of the body","cn":"（对身体特定部位进行的）检查；体检","lab":"North American English","ex":{"en":"an eye exam","cn":"眼睛检查"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"考试","en":"An exam is a formal test that you take to show your knowledge or ability in a particular subject, or to obtain a qualification.","ex":{"en":"I don't want to take any more exams","cn":"我再也不想参加考试了。"}},{"pos":"N-COUNT 可数名词","cn":"体检；医学检查","en":"If you have a medical exam, a doctor looks at your body, feels it, or does simple tests in order to check how healthy you are."}]},"media":{"uk":"media/uk/exam__gb_1.mp3","us":"media/us/exam__us_1.mp3"},"examples":[{"en":"I got my exam results today.","cn":"我今天得到了考试成绩。"},{"en":"A lot of students suffer from exam nerves.","cn":"许多学生考试怯阵。"}]},"explanations":{"lemma":"explanation","media":{"uk":"media/uk/explanation__gb_1.mp3","us":"media/us/explanation__us_1.mp3"}},"excess":{"media":{"uk":"media/uk/excess__gb_1.mp3","us":"media/us/excess__us_1.mp3"},"oxford":{"phon":"ɪkˈses","pos":"noun","senses":[{"en":"more than is necessary, reasonable or acceptable","cn":"超过；过度；过分","g":"[singular, uncountable]","ex":{"en":"You can throw away any excess.","cn":"凡多余的你都可以扔掉。"}},{"en":"an amount by which something is larger than something else","cn":"过多的量；超过的量","g":"[countable, usually singular, uncountable]","ex":{"en":"We cover costs up to £600 and then you pay the excess.","cn":"我们最多支付 600 英镑的费用，超出的部分由你支付。"}},{"en":"the part of an insurance claim that a person has to pay while the insurance company pays the rest","cn":"免赔额；自负额","g":"[countable, usually singular]","lab":"British English","ex":{"en":"There is an excess of £100 on each claim under this policy.","cn":"本保险单每次索赔均有 100 英镑的免赔额。"}},{"en":"the fact of doing too much of something, especially eating or drinking","cn":"过量，过度（尤指吃喝）","g":"[uncountable]","lab":"disapproving","ex":{"en":"He gave in to bouts of alcoholic excess.","cn":"几次过量饮酒之后他就扛不住了。"}},{"en":"extreme behaviour that is unacceptable, illegal or morally wrong","cn":"放肆行为；越轨行为","g":"[plural]","lab":"disapproving","ex":{"en":"We need a free press to curb government excesses.","cn":"我们需要新闻自由来遏制政府滥用权力。"}},{"en":"in addition to an amount that is necessary, usual or legal","cn":"超额的；额外的；附加的；过度的","ex":{"en":"Excess food is stored as fat.","cn":"多余的食物作为脂肪贮存起来。"},"pos":"adjective"},{"en":"required as extra payment","cn":"额外的","lab":"British English","ex":{"en":"The full excess fare had to be paid.","cn":"必须支付全部超额车费。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"过多;过量","en":"An excess of something is a larger amount than is needed, allowed, or usual.","ex":{"en":"An excess of house plants in a small flat can be oppressive","cn":"在小公寓中摆放过多室内植物会让人觉得很压抑。"}},{"pos":"ADJ 形容词","cn":"过量的;过多的","en":"Excess is used to describe amounts that are greater than what is needed, allowed, or usual.","ex":{"en":"After cooking the fish, pour off any excess fat","cn":"烹完鱼后，倒掉多余的油。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无节制;无度","en":"Excess is behaviour that is unacceptable because it is considered too extreme or immoral.","ex":{"en":"She said she was sick of her life of excess.","cn":"她说她厌倦了自己无节制的生活。"}},{"pos":"ADJ 形容词","cn":"额外的;多余的","en":"Excess is used to refer to additional amounts of money that need to be paid for services and activities that were not originally planned or taken into account.","ex":{"en":"...a letter demanding an excess fare of £20","cn":"要求额外付20英镑邮资的信"}},{"pos":"N-COUNT 可数名词","cn":"（保险中的）免赔额，承保人本人需承担的款额","en":"The excess on an insurance policy is a sum of money which the insured person has to pay towards the cost of a claim. The insurance company pays the rest.","ex":{"en":"The company wanted £1,800 for a policy with a £500 excess for under-21s.","cn":"那家公司想要办理单价1,800英镑的保单，并且要求21岁以下人员承担价值500英镑的免赔额。"}},{"pos":"PREP-PHRASE 短语介词","cn":"超过","en":"In excess of means more than a particular amount.","ex":{"en":"Avoid deposits in excess of £20,000 in any one account","cn":"单一账户存款勿超过两万英镑。"}},{"pos":"PHRASE 短语","cn":"过分地;过度地","en":"If you do something to excess, you do it too much.","ex":{"en":"I was reasonably fit, played a lot of tennis, and didn't smoke or drink to excess","cn":"我相当健康，经常打网球，不怎么吸烟，也不酗酒。"}}]},"examples":[{"en":"We cover costs up to £600 and then you pay the excess.","cn":"我们最多支付 600 英镑的费用，超过的部分由你支付。"},{"en":"There is an excess of £100 on each claim under this policy.","cn":"本保险单每次索赔均有 100 英镑的免赔额。"}]},"explosive":{"oxford":{"phon":"ɪkˈspləʊsɪv","pos":"adjective","senses":[{"en":"easily able or likely to explode","cn":"易爆炸的；可能引起爆炸的","ex":{"en":"an explosive device (= a bomb)","cn":"爆炸装置（炸弹）"}},{"en":"likely to cause violence or strong feelings of anger or hate","cn":"易爆发的；可能引起冲动的；爆炸性的","ex":{"en":"one of the most explosive issues of our time","cn":"我们这个时代最具爆炸性的问题之一"}},{"en":"often having sudden violent or angry feelings","cn":"暴躁的","ex":{"en":"an explosive temper","cn":"暴躁的脾气"}},{"en":"increasing suddenly and rapidly","cn":"突增的；猛增的；激增的","ex":{"en":"the explosive growth of the export market","cn":"出口市场的急剧扩大"}},{"en":"sudden and loud","cn":"爆发的","ex":{"en":"There was an explosive crash and then everything fell silent.","cn":"一声爆炸性的撞击声响起，然后一切都归于沉寂。"}},{"en":"a substance that is able or likely to cause an explosion","cn":"炸药；爆炸物","ex":{"en":"plastic explosives","cn":"塑性炸药"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"炸药;爆炸物","en":"An explosive is a substance or device that can cause an explosion.","ex":{"en":"...one-hundred-and-fifty pounds of Semtex explosive","cn":"150磅塞姆汀塑胶炸药"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"会爆炸的;能引起爆炸的","en":"Something that is explosive is capable of causing an explosion.","ex":{"en":"The explosive device was timed to go off at the rush hour","cn":"爆炸装置被设定在高峰时间引爆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（增长）爆炸性的，迅猛的","en":"An explosive growth is a sudden, rapid increase in the size or quantity of something.","ex":{"en":"The explosive growth in casinos is one of the most conspicuous signs of Westernisation.","cn":"西化最显著的标志之一就是赌场的骤增。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（局面等）一触即发的，千钧一发的","en":"An explosive situation is likely to have difficult, serious, or dangerous effects.","ex":{"en":"He appeared to be treating the potentially explosive situation with some sensitivity","cn":"他似乎正小心地应对可能一触即发的局势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易怒的;暴躁的","en":"If you describe someone as explosive, you mean that they tend to express sudden violent anger.","ex":{"en":"She was unpredictable, explosive, impulsive and easily distracted","cn":"她难以捉摸，脾气暴躁，冲动鲁莽，容易分心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声响突然）爆发的","en":"A sudden loud noise can be described as explosive.","ex":{"en":"He made a loud, explosive noise of disgust.","cn":"他反感地爆发出一阵叫嚷。"}}]},"media":{"uk":"media/uk/explosive__gb_1.mp3","us":"media/us/explosive__us_1.mp3"},"examples":[{"en":"The bomb was packed with several pounds of high explosive.","cn":"这枚炸弹装有几磅烈性炸药。"},{"en":"the explosive growth of the export market","cn":"出口市场的急剧扩大"}]},"exerts":{"lemma":"exert"},"excuses":{"lemma":"excuse","media":{"uk":"media/uk/excuse__gb_1.mp3","us":"media/us/excuse__us_1.mp3"}},"experience":{"media":{"uk":"media/uk/experience__gb_1.mp3","us":"media/us/experience__us_1.mp3"},"oxford":{"phon":"ɪkˈspɪəriəns","pos":"noun","senses":[{"en":"the knowledge and skill that you have gained through doing something for a period of time; the process of gaining this","cn":"（由实践得来的）经验；实践","g":"[uncountable]","ex":{"en":"My lack of practical experience was a disadvantage.","cn":"我缺少实际经验是个不利条件。"}},{"en":"the things that have happened to you that influence the way you think and behave","cn":"经历；阅历","g":"[uncountable]","ex":{"en":"Experience has taught me that life can be very unfair.","cn":"经历使我懂得人生有时是很不公平的。"}},{"en":"an event or activity that affects you in some way","cn":"（一次）经历，体验","g":"[countable]","ex":{"en":"a unique/positive/wonderful experience","cn":"独特的／积极的／美妙的经历"}},{"en":"what it is like for somebody to use a service, do an activity, attend an event, etc.","cn":"（对服务、活动等的）体验，感受","g":"[singular]","ex":{"en":"We are continually looking for ways to improve the customer experience.","cn":"我们一直在寻找改善客户体验的方法。"}},{"en":"events or knowledge shared by all the members of a particular group in society, that influences the way they think and behave","cn":"传统","g":"[singular]","ex":{"en":"musical forms like jazz that emerged out of the Black American experience","cn":"诸如爵士乐这类起源于美国黑人传统的音乐形式"}},{"en":"to have a particular situation affect you or happen to you","cn":"经历；经受；遭受","ex":{"en":"Many people have never experienced these difficulties first-hand.","cn":"许多人从未亲身经历过这些困难。"},"pos":"verb"},{"en":"to have and be aware of a particular emotion or physical feeling","cn":"感受；体会；体验","ex":{"en":"I have never experienced such pain before.","cn":"我从来没有经历过这样的痛苦。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"经验；实践","en":"Experience is knowledge or skill in a particular job or activity, which you have gained because you have done that job or activity for a long time.","ex":{"en":"He has also had managerial experience on every level","cn":"他还有各个层级的管理经验。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（组成个人生活或形成个性的）经历，阅历","en":"Experience is used to refer to the past events, knowledge, and feelings that make up someone's life or character.","ex":{"en":"I should not be in any danger here, but experience has taught me caution","cn":"我在这里应该不会有任何危险，但是经验告诉我要小心。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指重要的）经历，往事","en":"An experience is something that you do or that happens to you, especially something important that affects you.","ex":{"en":"Moving had become a common experience for me","cn":"搬家对我而言已经成了常事。"}},{"pos":"VERB 动词","cn":"经历","en":"If you experience a particular situation, you are in that situation or it happens to you.","ex":{"en":"We had never experienced this kind of holiday before and had no idea what to expect","cn":"我们以前从未有过这样的假期，不知道会怎么样。"}},{"pos":"VERB 动词","cn":"感受;体验","en":"If you experience a feeling, you feel it or are affected by it.","ex":{"en":"Widows seem to experience more distress than do widowers.","cn":"寡妇似乎比鳏夫更痛苦。"}}]},"examples":[{"en":"Living in Africa was very different from home and quite an experience (= unusual for us).","cn":"生活在非洲完全不同于在家里，那真是一次不同寻常的经历。"},{"en":"musical forms like jazz that emerged out of the Black American experience","cn":"诸如爵士乐这类起源于美国黑人传统的音乐形式"}]},"exchanged":{"lemma":"exchange"},"excavation":{"media":{"uk":"media/uk/excavation__gb_1.mp3","us":"media/us/excavation__us_1.mp3"},"oxford":{"phon":"ˌekskəˈveɪʃn","pos":"noun","senses":[{"en":"the activity of digging in the ground to look for old buildings or objects that have been buried for a long time","cn":"（对古建筑或古物的）发掘，挖掘","g":"[countable, uncountable]","ex":{"en":"Further archaeological excavations are now being carried out.","cn":"更进一步的考古发掘正在进行。"}},{"en":"a place where people are digging to look for old buildings or objects","cn":"发掘现场","g":"[countable, usually plural]","ex":{"en":"The excavations are open to the public.","cn":"发掘现场对公众开放。"}},{"en":"the act of digging, especially with a machine","cn":"挖掘；开凿；挖土","g":"[uncountable]"}]},"examples":[{"en":"The excavations are open to the public.","cn":"发掘现场对公众开放。"},{"en":"Schliemann excavated the ancient city of Troy.","cn":""}]},"exercises":{"lemma":"exercise","media":{"img":["media/pic/keepingfit_comp.jpg","media/thumb/treadmill.jpg"],"uk":"media/uk/exercise__gb_1.mp3","us":"media/us/exercise__us_1.mp3"}},"expensive":{"media":{"uk":"media/uk/expensive__gb_1.mp3","us":"media/us/expensive__us_1.mp3"},"oxford":{"phon":"ɪkˈspensɪv","pos":"adjective","senses":[{"en":"costing a lot of money","cn":"昂贵的；花钱多的；价格高的","lab":"British English","ex":{"en":"an expensive car/restaurant/holiday","cn":"昂贵的汽车；高档的餐馆；花费大的假日"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昂贵的;高价的","en":"If something is expensive, it costs a lot of money.","ex":{"en":"Wine's so expensive in this country","cn":"葡萄酒在这个国家非常昂贵。"}}]},"examples":[{"en":"Houses in the village are now too pricey for local people to afford.","cn":"如今该村庄的房价太高，当地人根本买不起。"},{"en":"You want to avoid costly legal proceedings if you can.","cn":"如果能够的话你希望避免昂贵的法律诉讼。"}]},"expectant":{"oxford":{"phon":"ɪkˈspektənt","pos":"adjective","senses":[{"en":"hoping for something, especially something good and exciting","cn":"期待的；期望的","ex":{"en":"children with expectant faces waiting for the fireworks to begin","cn":"带着期盼的神情等待烟火表演开始的孩子们"}},{"en":"used to describe somebody who is going to have a baby soon or become a father","cn":"准（母亲、父亲、父母）","ex":{"en":"Smoking by expectant mothers may increase the chances of brain damage in their babies.","cn":"准妈妈吸烟可能会增加婴儿脑损伤的风险。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"期待的;期望的","en":"If someone is expectant, they are excited because they think something interesting is about to happen.","ex":{"en":"An expectant crowd gathered","cn":"满怀期待的人群聚在一起。"}},{"pos":"ADJ 形容词","cn":"即将当（妈妈或爸爸）的","en":"An expectant mother or father is someone whose baby is going to be born soon."}]},"media":{"uk":"media/uk/expectant__gb_1.mp3","us":"media/us/expectant__us_1.mp3"},"examples":[{"en":"children with expectant faces waiting for the fireworks to begin","cn":"带着期盼的神情等待烟火表演的孩子们"},{"en":"A sudden roar came from the expectant crowd.","cn":"期待的人群中突然发出一声咆哮。"}]},"existing":{"media":{"uk":"media/uk/existing__gb_1.mp3","us":"media/us/existing__us_1.mp3"},"oxford":{"phon":"ɪɡˈzɪstɪŋ","pos":"adjective","senses":[{"en":"found or used now","cn":"现存的；现行的","ex":{"en":"New laws will soon replace existing legislation.","cn":"新法即将取代现行法规。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指与未来相对的）现存的，现行的，目前的","en":"Existing is used to describe something which is now present, available, or in operation, especially when you are contrasting it with something which is planned for the future.","ex":{"en":"...the need to improve existing products and develop new lines","cn":"改进现有产品、开发新生产线的需要"}}]},"examples":[{"en":"New laws will soon replace existing legislation.","cn":"新法律即将取代现行法规。"},{"en":"The service is available to all existing customers.","cn":"这项服务现有的客户均可享受。"}],"base":"exist"},"extreme":{"media":{"uk":"media/uk/extreme__gb_1.mp3","us":"media/us/extreme__us_1.mp3"},"oxford":{"phon":"ɪkˈstriːm","pos":"adjective","senses":[{"en":"very great in degree","cn":"极度的；极大的","g":"[usually before noun]","ex":{"en":"We are working under extreme pressure at the moment.","cn":"目前我们正在极大的压力下工作。"}},{"en":"not ordinary or usual; serious or severe","cn":"异乎寻常的；严重的；严厉的","ex":{"en":"extreme weather events such as floods and heatwaves","cn":"洪水和热浪等极端天气情况"}},{"en":"far from what most people consider to be normal, reasonable or acceptable","cn":"极端的；偏激的；过分的","ex":{"en":"extreme left-wing/right-wing views","cn":"极左／极右观点"}},{"en":"as far as possible from the centre, the beginning or in the direction mentioned","cn":"远离中心的；末端的；尽头的","g":"[only before noun]","ex":{"en":"Kerry is in the extreme west of Ireland.","cn":"凯里位于爱尔兰的最西端。"}},{"en":"a feeling, situation, way of behaving, etc. that is as different as possible from another or is opposite to it","cn":"极端不同的感情（或境况、行为方式等）；完全相反的事物","ex":{"en":"extremes of love and hate","cn":"爱和恨两种截然不同的感情"},"pos":"noun"},{"en":"the greatest or highest degree of something","cn":"极端；极度；极限","ex":{"en":"The climate is mild with no extremes of temperature.","cn":"气候温和，没有极端温度。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极其的;极度的","en":"Extreme means very great in degree or intensity.","ex":{"en":"The girls were afraid of snakes and picked their way along with extreme caution.","cn":"女孩子们害怕蛇，走路时格外小心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极端的","en":"You use extreme to describe situations and behaviour which are much more severe or unusual than you would expect, especially when you disapprove of them because of this.","ex":{"en":"The extreme case was Poland, where 29 parties won seats","cn":"极端的例子是波兰，共有29个政党拥有议席。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偏激的;过激的","en":"You use extreme to describe opinions, beliefs, or political movements which you disapprove of because they are very different from those that most people would accept as reasonable or normal.","ex":{"en":"This extreme view hasn't captured popular opinion.","cn":"这种偏激的观点未被大众接受。"}},{"pos":"N-COUNT 可数名词","cn":"极端；完全相反的事物","en":"You can use extremes to refer to situations or types of behaviour that have opposite qualities to each other, especially when each situation or type of behaviour has such a quality to the greatest degree possible.","ex":{"en":"...a 'middle way' between the extremes of success and failure","cn":"成功和失败这两个极端之间的“中间地带”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尽头的;末端的","en":"The extreme end or edge of something is its furthest end or edge.","ex":{"en":"...the room at the extreme end of the corridor.","cn":"在走廊尽头的那个房间"}},{"pos":"PHRASE 短语","cn":"走极端;使…至极端","en":"If a person goes to extremes or takes something to extremes, they do or say something in a way that people consider to be unacceptable, unreasonable, or foolish.","ex":{"en":"The police went to the extremes of installing the most advanced safety devices in the man's house","cn":"警方采取极端措施，在那个男子家里安装了最先进的安全装置。"}},{"pos":"PHRASE 短语","cn":"（用于形容词后，尤用于强调不好或令人惊讶的事）极其，极度","en":"You use in the extreme after an adjective in order to emphasize what you are saying, especially when you want to indicate that it is something which is undesirable or very surprising.","ex":{"en":"It is proving controversial in the extreme","cn":"事实证明它极具争议。"}}]},"examples":[{"en":"It's embarrassing the extremes he'll go to in order to impress his boss.","cn":"他为了给上司留下深刻印象，不惜走极端，真令人难堪。"},{"en":"Don't go doing anything extreme like leaving the country.","cn":"千万不要做出诸如离开国家之类的极端行为。"}]},"exceptions":{"lemma":"exception"},"extremes":{"lemma":"extreme"},"extends":{"lemma":"extend"},"exports":{"lemma":"export"},"experiments":{"lemma":"experiment"},"exporters":{"lemma":"exporter"},"experts":{"lemma":"expert"},"existed":{"lemma":"exist"},"experiencing":{"lemma":"experience"},"exists":{"lemma":"exist"},"expectations":{"lemma":"expectation"},"extracting":{"lemma":"extract"},"explaining":{"lemma":"explain"},"expressions":{"lemma":"expression"},"experiences":{"lemma":"experience"},"expanded":{"lemma":"expand"},"examining":{"lemma":"examine"},"excavators":{"oxford":{"phon":"ˈekskəveɪtə(r)","pos":"noun","senses":[{"en":"a large machine that is used for digging and moving earth","cn":"挖掘机；挖土机"},{"en":"a person who digs in the ground to look for old buildings and objects","cn":"发掘者"}]}},"extending":{"lemma":"extend"},"expressed":{"lemma":"express"},"expressing":{"lemma":"express"},"exploring":{"lemma":"explore"},"examples":{"lemma":"example"},"extinguished":{"oxford":{"phon":"ɪkˈstɪŋɡwɪʃ","pos":"verb","senses":[{"en":"to make a fire stop burning or a light stop shining","cn":"熄灭；扑灭"},{"en":"to destroy sth","cn":"毁灭；消灭；使破灭"}]}},"expenses":{"lemma":"expense"},"exiled":{"lemma":"exile"},"examined":{"lemma":"examine"},"extracurricular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"课外的","en":"Extracurricular activities are activities for students that are not part of their course.","ex":{"en":"Each child had participated in extracurricular activities at school.","cn":"每个孩子都参加了学校的课外活动。"}},{"pos":"ADJ 形容词","cn":"工作之余的","en":"Extracurricular activities are activities that someone does that are not part of their normal work.","ex":{"en":"The money he made from these extracurricular activities enabled him to pursue other ventures.","cn":"他从这些额外工作中赚取的钱使他可以从事其他事业。"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/extracurricula0205.mp3","us":"media/ldoce/hwd/ame/7/extracurricular.mp3"},"oxford":{"phon":"ˌekstrəkəˈrɪkjələ(r)","pos":"adjective","senses":[{"en":"not part of the usual course of work or studies at a school or college","cn":"课外的；课程以外的","ex":{"en":"She's involved in many extracurricular activities.","cn":"她参加了许多课外活动。"}}]}},"expands":{"lemma":"expand"},"explained":{"lemma":"explain"},"expiring":{"lemma":"expire"},"expects":{"lemma":"expect"},"expresses":{"lemma":"express"},"explains":{"lemma":"explain"},"exploited":{"lemma":"exploit"},"expeditions":{"lemma":"expedition"},"exceed":{"collins":{"senses":[{"pos":"VERB 动词","cn":"超过，超出（某数量、数字等）","en":"If something exceeds a particular amount or number, it is greater or larger than that amount or number.","ex":{"en":"Its research budget exceeds $700 million a year","cn":"其研究预算每年超过7亿美元。"}},{"pos":"VERB 动词","cn":"超出，超越（限制、规定等）","en":"If you exceed a limit or rule, you go beyond it, even though you are not supposed to or it is against the law.","ex":{"en":"He accepts he was exceeding the speed limit","cn":"他承认自己超速了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be more than a number or amount, especially a fixed number or limit - used especially in official reports or documents","cn":""},{"en":"if one type of person or thing outnumbers another, there are more of the first type than of the second","cn":""},{"en":"if profits, sales, income etc are up they are larger than at a time in the past","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To exceed is to go beyond expectations, or to go too far. If you exceed the speed limit, you might get a speeding ticket."}]},"collocations":{"phrases":["ADV. considerably, far, greatly, significantly, substantially | comfortably, easily The House voted by 327 votes to 93, comfortably exceedin","VERB + EXCEED be expected to, be likely to Income is expected to exceed expenditure. | be unlikely to"]},"media":{"uk":"media/ldoce/hwd/bre/0/exceed0205.mp3","us":"media/ldoce/hwd/ame/c/exceed.mp3"},"examples":[{"en":"The price will not exceed £100.","cn":"价格不会超过 100 英镑。"},{"en":"The officers had exceeded their authority.","cn":"这些官员超越了他们的权限。"}],"oxford":{"phon":"ɪkˈsiːd","pos":"verb","senses":[{"en":"to be greater than a particular number or amount","cn":"超过（数目或数量）","ex":{"en":"The price will not exceed £100.","cn":"价格不会超过 100 英镑。"}},{"en":"to do more than the law or an order, etc. allows you to do","cn":"超越（法律、命令等）的限制","ex":{"en":"She was exceeding the speed limit (= driving faster than is allowed).","cn":"当时她超速驾驶。"}},{"en":"to be better than expected","cn":"优于预期；出乎意料","ex":{"en":"His achievements have exceeded expectations.","cn":"他的成就出乎预料。"}}]}},"extinct":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"灭绝的;绝种的","en":"A species of animal or plant that is extinct no longer has any living members, either in the world or in a particular place.","ex":{"en":"It is 250 years since the wolf became extinct in Britain.","cn":"狼在英国已经灭绝250年了。"}},{"pos":"ADJ 形容词","cn":"（某类劳动者、生活方式或活动）不复存在的，废除了的","en":"If a particular kind of worker, way of life, or type of activity is extinct, it no longer exists, because of changes in society.","ex":{"en":"If the current trend continues, black farmers in the United States may be extinct by the end of this decade","cn":"如果当前趋势继续发展下去，美国的黑人农民将在这个十年末不复存在。"}},{"pos":"ADJ 形容词","cn":"（火山）死的","en":"An extinct volcano is one that does not erupt or is not expected to erupt any more.","ex":{"en":"Its tallest volcano, long extinct, is Olympus Mons.","cn":"它最高的火山是早已熄灭的奥林波斯山。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something disappears , it stops existing, and cannot be seen any more","cn":""},{"en":"to stop existing, especially because of a sudden or quick process","cn":""},{"en":"if a type of animal or plant becomes extinct , all the animals or plants of that type die, so that the type does not exist any more","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that no longer exists and has no living representative is extinct. Dinosaurs are extinct. Polar bears may become extinct. Sadly, history teachers who force their students to memorize long lists of dates are in no danger of becoming extinct."}]},"collocations":{"phrases":["VERBS be | become, go | presume sth, think sth The species was presumed extinct.","ADV. completely, totally | all but, almost, nearly, practically, virtually The numbers of these animals have been falling steadily and they "]},"media":{"uk":"media/ldoce/hwd/bre/3/extinct0205.mp3","us":"media/ldoce/hwd/ame/a/extinct.mp3"},"examples":[{"en":"Servants are now almost extinct in modern society.","cn":"在现代社会里奴仆已近乎不复存在。"},{"en":"an extinct species","cn":"已灭绝的物种"}],"oxford":{"phon":"ɪkˈstɪŋkt","pos":"adjective","senses":[{"en":"no longer in existence","cn":"不再存在的；已灭绝的；绝种的","ex":{"en":"an extinct species","cn":"已灭绝的物种"}},{"en":"no longer in existence in society","cn":"绝迹的；消亡了的；废除了的","ex":{"en":"Servants are now almost extinct in modern society.","cn":"在现代社会里奴仆已近乎不复存在。"}},{"en":"no longer active","cn":"不再活跃的；死的"}]}},"extremist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"极端分子;极端主义者","en":"If you describe someone as an extremist, you disapprove of them because they try to bring about political change by using violent or extreme methods.","ex":{"en":"The country needs a strong intelligence service to counter espionage and foreign extremists","cn":"该国需要强大的情报机构来打击间谍活动和外国极端分子。"}},{"pos":"ADJ 形容词","cn":"极端主义的；过激的","en":"If you say that someone has extremist views, you disapprove of them because they believe in bringing about change by using violent or extreme methods."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"extreme opinions or beliefs about politics, religion etc are too strong and most people regard them as unreasonable","cn":""},{"en":"extremist ideas or political organizations involve actions or aims that are very strong and most people think are unreasonable","cn":""},{"en":"relating to the most extreme left wing or right wing of a political organization or among followers of a set of political beliefs","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Nowadays, we tend to associate the word extremist with \"terrorist,\" and use the two words almost interchangeably to define someone who holds radical political or religious views."}]},"collocations":{"phrases":["ADJ. left-wing, right-wing an attack by right-wing extremists | political, religious | Muslim, Republican, etc.","EXTREMIST + NOUN group, party"]},"media":{"uk":"media/ldoce/hwd/bre/0/extremist0205.mp3","us":"media/ldoce/hwd/ame/b/laadextremist.mp3"},"examples":[{"en":"extremist attacks/groups/policies","cn":"过激分子的攻击；极端分子组织；极端主义政策"},{"en":"left-wing/right-wing/political/religious extremists","cn":"左翼/右翼/政治/宗教极端主义者"}],"oxford":{"phon":"ɪkˈstriːmɪst","pos":"noun","senses":[{"en":"a person whose opinions, especially about religion or politics, are extreme, and who may do things that are violent or illegal for what they believe","cn":"极端主义者；极端分子；过激分子","ex":{"en":"left-wing/right-wing/political/religious extremists","cn":"左翼／右翼／政治／宗教极端主义者"}},{"en":"connected with or belonging to people whose opinions, especially about religion or politics, are extreme, and who may do things that are violent or illegal for what they believe","cn":"极端主义者；极端分子；过激分子","ex":{"en":"extremist groups","cn":"极端组织"},"pos":"adjective"}]}},"expulsion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"开除；除名","en":"Expulsion is when someone is forced to leave a school, university, or organization.","ex":{"en":"Her hatred of authority led to her expulsion from high school.","cn":"她对权威的仇恨导致她被中学开除。"}},{"pos":"N-VAR 可变名词","cn":"驱逐；逐出","en":"Expulsion is when someone is forced to leave a place.","ex":{"en":"...the expulsion of Yemeni workers.","cn":"对也门工人的驱逐"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（自人体内的）排出","en":"Expulsion is when something is forced out from your body.","ex":{"en":"...the expulsion of waste products.","cn":"废弃物的排出"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of forcing someone to leave a place","cn":"驱逐﹐赶走"},{"en":"the act of stopping someone from going to the school where they were studying or from being part of the organization where they worked","cn":"开除﹐除名"},{"en":"the act of forcing air, water, gas etc out of something 〔","cn":"空气﹑水﹑气体等的〕排出"}]},"vocab":{"pos":"n","senses":[{"en":"Don't ever make a joke about a bomb on an airplane, if you don't want to risk expulsion . Expulsion is being kicked out of something, like a club, a school, or an airplane."}]},"collocations":{"phrases":["ADJ. automatic | immediate | mass | forced","VERB + EXPULSION lead to, result in Copying from another candidate results in automatic expulsion. | call for, demand | order The government","PREP. ~ from her expulsion from the society","PHRASES ground(s) for expulsion His disruptive behaviour was felt to be sufficient grounds for his expulsion."]},"media":{"uk":"media/ldoce/hwd/bre/1/expulsion0205.mp3","us":"media/ldoce/hwd/ame/4/expulsion.mp3"},"examples":[{"en":"These events led to the expulsion of senior diplomats from the country.","cn":"这些事件导致一些高级外交官被驱逐出境。"},{"en":"The headteacher threatened the three girls with expulsion.","cn":"校长以开除来威胁这三名女学生。"}],"oxford":{"phon":"ɪkˈspʌlʃn","pos":"noun","senses":[{"en":"the act of forcing somebody to leave a place; the act of expelling somebody","cn":"驱逐；逐出","g":"[uncountable, countable]","ex":{"en":"These events led to the expulsion of senior diplomats from the country.","cn":"这些事件导致一些高级外交官被驱逐出境。"}},{"en":"the act of sending somebody away from a school or an organization, so that they can no longer belong to it; the act of expelling somebody","cn":"开除；除名","g":"[uncountable, countable]","ex":{"en":"The headteacher threatened the three girls with expulsion.","cn":"校长以开除来威胁这三名女学生。"}},{"en":"the act of sending or driving a substance out of your body or a container","cn":"排出","g":"[uncountable]","lab":"formal","ex":{"en":"the expulsion of air from the lungs","cn":"从肺中排出空气。"}}]}},"expectation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"期待;期望；预期","en":"Your expectations are your strong hopes or beliefs that something will happen or that you will get something that you want.","ex":{"en":"Students' expectations were as varied as their expertise","cn":"学生们的期望根据他们的专业各有不同。"}},{"pos":"N-COUNT 可数名词","cn":"期望;希望","en":"A person's expectations are strong beliefs which they have about the proper way someone should behave or something should happen.","ex":{"en":"Stephen Chase had determined to live up to the expectations of the Company.","cn":"斯蒂芬·蔡斯决心不辜负公司的期望。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to expect something to happen, so that you make plans or take actions that depend on it happening","cn":""},{"en":"to expect something so much that your plans depend on it happening or you are completely prepared for it when it happens","cn":""},{"en":"if you make plans or take actions in expectation or anticipation of something happening, you do this because you expect it to happen and you want to be prepared","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An expectation is a belief about what might happen in the future, like your expectation to stay close with your best friends your whole life."}]},"collocations":{"phrases":["ADJ. great, high | low Many children start with low expectations. | growing, rising | heightened, increased Heightened expectations for educ","VERB + EXPECTATION have, hold You have unrealistic expectations. differences in the expectations held by different social groups | form the ","EXPECTATION + VERB rise, soar Once the government's promise was made, popular expectations soared.","PREP. against ~ Against all expectations, she was enjoying herself. | contrary to ~ The building work was completed on time, contrary to exp","PHRASES have every expectation I have every expectation of cheering the team on to victory in the final. | in line with expectations The var"]},"media":{"uk":"media/ldoce/hwd/bre/a/expectation0205.mp3","us":"media/ldoce/hwd/ame/b/expectation.mp3"},"examples":[{"en":"We are confident in our expectation of a full recovery.","cn":"我们满怀信心地期待着完全康复。"},{"en":"I applied for the post more in hope than expectation.","cn":"我申请这个职位是希望多于期待。"}],"oxford":{"phon":"ˌekspekˈteɪʃn","pos":"noun","senses":[{"en":"a belief that something will happen because it is likely","cn":"预料；预期；期待","g":"[uncountable, countable]","ex":{"en":"We are confident in our expectation of a full recovery.","cn":"我们满怀信心地期待着完全恢复。"}},{"en":"a hope that something good will happen","cn":"希望；盼望","g":"[countable, usually plural, uncountable]","ex":{"en":"She went to college with great expectations.","cn":"她满怀希望地进入大学。"}},{"en":"a strong belief about the way something should happen or how somebody should behave","cn":"期望；指望","g":"[countable, usually plural]","ex":{"en":"Unfortunately the new software has failed to meet expectations.","cn":"遗憾的是新软件并不理想。"}}]}},"exporter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出口国;出口者;出口厂商","en":"An exporter is a country, firm, or person that sells and sends goods to another country.","ex":{"en":"France is the world's second-biggest exporter of agricultural products.","cn":"法国是世界第二大农产品出口国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person, company, or country that sells goods to another country","cn":"出口商﹔出口公司﹔出口国"},{"en":"OPP importer exporter of With the expanded production of North Sea oil and gas, the UK has become a net exporter of fuel (= it exports more fuel than it imports ) .","cn":"随着北海石油和天然气产量的扩大﹐英国已成为燃料的净出口国。 major/leading exporter Japan is a leading exporter of textiles. 日本是纺织品的一大出口国。"}]},"vocab":{"pos":"n","senses":[{"en":"An exporter is someone who sends goods out of a country to be sold. If you are in the import/export business, you bring goods from abroad into the country as well."}]},"collocations":{"phrases":["ADJ. big, large | leading, major | food, oil the biggest oil exporter in the world | net The country is a net exporter of food."]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeexporter.mp3","us":"media/ldoce/hwd/ame/8/exporter.mp3"},"examples":[{"en":"the world's largest/major/leading exporter of cars","cn":"世界上最大的/重要的/主要的汽车输出国"},{"en":"The country is now a net exporter of fuel (= it exports more than it imports).","cn":"目前这个国家是燃料净输出国。"}],"oxford":{"phon":"ekˈspɔːtə(r)","pos":"noun","senses":[{"en":"a person, company or country that sells goods to another country","cn":"出口商；出口公司；出口国","ex":{"en":"the world’s largest/major/leading exporter of cars","cn":"世界上最大的／重要的／主要的汽车输出国"}}]}},"execute":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…处死;将…正法","en":"To execute someone means to kill them as a punishment for a serious crime.","ex":{"en":"He was executed by lethal injection earlier today","cn":"他于今天早些时候被注射处死。"}},{"pos":"VERB 动词","cn":"执行;实施;贯彻","en":"If you execute a plan, you carry it out.","ex":{"en":"We are going to execute our campaign plan to the letter.","cn":"我们将严格施行我们的竞选计划。"}},{"pos":"VERB 动词","cn":"完成，表演(高难度动作)","en":"If you execute a difficult action or movement, you successfully perform it.","ex":{"en":"I executed the hairpin turn high on the sheer western face of the mountains","cn":"我在山脉西侧陡峭的高处成功地急转弯。"}},{"pos":"VERB 动词","cn":"制作，创作（艺术品）","en":"When someone executes a work of art, they make or produce it, using an idea as a basis.","ex":{"en":"Morris executed a suite of twelve drawings in 1978","cn":"莫里斯在1978年创作了由12幅画组成的一组作品。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone die","cn":""},{"en":"to deliberately kill someone – used when talking about this as a crime","cn":""},{"en":"to kill someone without intending to – used when talking about this as a crime","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To execute means to carry out in full or perform. If you execute all the difficult steps of the dance perfectly, you will make your instructor proud."}]},"collocations":{"phrases":["ADV. summarily | extrajudicially, illegally | publicly | wrongly innocent people who are wrongly executed","PREP. for He was executed for treason. 2 perform/carry out sth","ADV. beautifully, boldly, brilliantly, cleanly, meticulously, neatly, skilfully, successfully, well The movement was beautifully executed. |"]},"media":{"uk":"media/ldoce/hwd/bre/5/execute0205.mp3","us":"media/ldoce/hwd/ame/2/execute.mp3"},"examples":[{"en":"Picasso also executed several landscapes at Horta de San Juan.","cn":"毕加索还在奥尔塔 — 德圣胡安画了几幅风景画。"},{"en":"They drew up and executed a plan to reduce fuel consumption.","cn":"他们制订并实施了一项降低燃料消耗的计划。"}],"oxford":{"phon":"ˈeksɪkjuːt","pos":"verb","senses":[{"en":"to kill somebody, especially as a legal punishment","cn":"（尤指依法）处决，处死","g":"[usually passive]","ex":{"en":"He was executed for treason.","cn":"他因叛国罪被处死。"}},{"en":"to do a piece of work, perform a duty, put a plan into action, etc.","cn":"实行；执行；实施","lab":"formal","ex":{"en":"They drew up and executed a plan to reduce fuel consumption.","cn":"他们制订并实施了一项降低燃料消耗的计划。"}},{"en":"to successfully perform an action or movement that requires skill","cn":"成功地完成（需要技巧的动作或活动）","lab":"formal","ex":{"en":"The pilot executed a perfect landing.","cn":"飞行员完成了一次完美着陆。"}},{"en":"to make or produce a work of art","cn":"制作，做成（艺术品）","lab":"formal","ex":{"en":"Picasso also executed several landscapes at Horta de San Juan.","cn":"毕加索还在奥尔塔–德圣胡安画了几幅风景画。"}},{"en":"to follow the instructions in a legal document; to make a document legally acceptable","cn":"执行（法令）；使（法律文件）生效","lab":"law","ex":{"en":"His will was executed by his lawyers in 2008.","cn":"2008年，他的律师签署了他的遗嘱。"}}]}},"expel":{"collins":{"senses":[{"pos":"VERB 动词","cn":"开除;将…除名","en":"If someone is expelled from a school or organization, they are officially told to leave because they have behaved badly.","ex":{"en":"More than five-thousand secondary school students have been expelled for cheating.","cn":"5,000多名中学生因为作弊被开除。"}},{"pos":"VERB 动词","cn":"逐出;驱逐","en":"If people are expelled from a place, they are made to leave it, often by force.","ex":{"en":"An American academic was expelled from the country yesterday","cn":"昨天一位美国学者被逐出该国。"}},{"pos":"VERB 动词","cn":"排出;喷出","en":"To expel something means to force it out from a container or from your body.","ex":{"en":"Daily brushing of the skin helps the skin expel toxins","cn":"每天擦洗皮肤有助于皮肤排毒。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone leave school or college permanently because they have behaved badly","cn":""},{"en":"to make someone leave school, college, or university permanently because of bad behaviour or for failing examinations","cn":""},{"en":"to officially say that a student can no longer attend his or her school, either for a short time or permanently, as a punishment for bad behaviour","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Getting expelled from a school is a step beyond suspension. It means that you are asked to leave and never come back. In other words, you have been kicked out."}]},"collocations":{"phrases":["ADV. forcibly They were forcibly expelled from their farm by the occupying authorities.","PREP. for, from He was expelled from school for disruptive behaviour."]},"media":{"uk":"media/ldoce/hwd/bre/a/expel0205.mp3","us":"media/ldoce/hwd/ame/8/expel.mp3"},"examples":[{"en":"She was expelled from school at 15.","cn":"她 15 岁时被学校开除了。"},{"en":"Foreign journalists are being expelled.","cn":"外国记者被驱逐出境。"}],"oxford":{"phon":"ɪkˈspel","pos":"verb","senses":[{"en":"to officially make somebody leave a school or an organization","cn":"把…开除（或除名）","lab":"British English","ex":{"en":"She was expelled from school at 15.","cn":"她 15 岁时被学校开除了。"}},{"en":"to force somebody to leave a country","cn":"驱逐出境","ex":{"en":"Foreign journalists are being expelled.","cn":"外国记者被驱逐出境。"}},{"en":"to force air or water out of a part of the body or from a container","cn":"排出；喷出","lab":"specialist","ex":{"en":"Expel all the air from your chest.","cn":"呼出胸腔中所有的空气。"}}]}},"exhaustive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"详尽无遗的;彻底全面的","en":"If you describe a study, search, or list as exhaustive, you mean that it is very thorough and complete.","ex":{"en":"This is by no means an exhaustive list but it gives an indication of the many projects taking place","cn":"这绝称不上是详尽无遗的清单，但是列出了很多正在进行的项目。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a thorough search, examination, check etc includes everything that can be included","cn":""},{"en":"including all the necessary facts, or a lot of details","cn":""},{"en":"very thorough, especially because it is important that nothing is left out and that every possible problem is dealt with","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Exhaustive means performed comprehensively and completely. When you recruit a new employee (or spouse), you undertake an exhaustive search for the best talent."}]},"collocations":{"phrases":["VERBS be","ADV. by no means, not necessarily This list is by no means exhaustive. | fairly After a fairly exhaustive investigation, they were able to p"]},"media":{"uk":"media/ldoce/hwd/bre/5/exhaustive0205.mp3","us":"media/ldoce/hwd/ame/6/exhaustive.mp3"},"examples":[{"en":"Every product is exhaustively tested before being sold.","cn":"每件产品销售前都经过全面检验。"},{"en":"This list is not intended to be exhaustive.","cn":"这份清单不求详尽无遗。"}],"oxford":{"phon":"ɪɡˈzɔːstɪv","pos":"adjective","senses":[{"en":"including everything possible; very careful or complete","cn":"详尽的；彻底的；全面的","ex":{"en":"exhaustive research/tests","cn":"彻底的研究；全面的测试"}}]}},"excitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易激动的;易兴奋的","en":"If you describe someone as excitable, you mean that they behave in a rather nervous way and become excited very easily.","ex":{"en":"Mary sat beside Elaine, who today seemed excitable","cn":"玛丽坐在伊莱恩身边，伊莱恩今天似乎有些激动。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone, especially a child, who is overexcited has become too excited to behave calmly","cn":""},{"en":"unable to stop shouting, crying etc because you are extremely excited","cn":""},{"en":"in a state of great and uncontrollable excitement","cn":""}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. highly, very | quite, rather, somewhat | easily The horses have easily excitable nervous systems."]},"media":{"uk":"media/ldoce/hwd/bre/2/excitable0205.mp3","us":"media/ldoce/hwd/ame/b/excitable.mp3"},"examples":[{"en":"a class of excitable ten-year-olds","cn":"一群易兴奋的十岁儿童"},{"en":"A puppy is naturally affectionate and excitable.","cn":"小狗生性热情好激动。"}],"oxford":{"phon":"ɪkˈsaɪtəbl","pos":"adjective","senses":[{"en":"likely to become easily excited","cn":"易激动的；易兴奋的","ex":{"en":"She had trouble controlling the class of excitable ten-year-olds.","cn":"她很难管束班里这些易兴奋的十岁儿童。"}}]}},"exterior":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外观;外部","en":"The exterior of something is its outside surface.","ex":{"en":"In one ad the viewer scarcely sees the car's exterior","cn":"在一则广告中，观众几乎看不到汽车的外观。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指与实际性格相差甚远的）外表，外貌，外在","en":"You can refer to someone's usual appearance or behaviour as their exterior, especially when it is very different from their real character.","ex":{"en":"According to Mandy, Pat's tough exterior hides a shy and sensitive soul.","cn":"据曼迪说，帕特彪悍的外表下隐藏着一颗害羞且敏感的心。"}},{"pos":"ADJ 形容词","cn":"外面的;外部的","en":"You use exterior to refer to the outside parts of something or things that are outside something.","ex":{"en":"The exterior walls were made of pre-formed concrete.","cn":"外墙用的是预制混凝土。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the outside part or surface of a building, vehicle etc - used especially in technical contexts","cn":""},{"en":"the outside of something, especially a building 〔","cn":"尤指建筑物的〕外部﹐外观"},{"en":"behaviour that seems calm, unfriendly etc but which often hides a different feeling or attitude","cn":"表面上镇定/冷漠等"}]},"vocab":{"pos":"adj n","senses":[{"en":"Something that's exterior is on the outside of some structure or object. An exterior door on a house opens to the outdoors, rather than connecting one room to another."}]},"collocations":{"phrases":["ADJ. elegant | plain","PREP. behind an/the ~ Hidden behind a plain exterior is a wonderful hotel. | on the ~ There is an abundance of fine sculpture, both on the e","ADJ. bland, bluff, calm, charming, confident, cool, glacial Her calm exterior hides very passionate feelings.","EXTERIOR + VERB belie, conceal, hide His bluff exterior belied a connoisseur of antiques.","PREP. behind sb's ~ Behind his cool exterior lurks a reckless and frustrated person. | beneath/underneath sb's ~ Beneath her charming exteri"]},"media":{"uk":"media/ldoce/hwd/bre/2/exterior_n0205.mp3","us":"media/ldoce/hwd/ame/6/exterior1.mp3"},"examples":[{"en":"Beneath his confident exterior, he was desperately nervous.","cn":"他表面上自信，内心极度紧张。"},{"en":"The filming of the exterior scenes was done on the moors.","cn":"外景是在高沼地拍摄的。"}],"oxford":{"phon":"ɪkˈstɪəriə(r)","pos":"noun","senses":[{"en":"the outside of something, especially a building","cn":"（尤指建筑物的）外部，外观，表面，外貌","g":"[countable]","ex":{"en":"The exterior of the house needs painting.","cn":"房子外墙需要油漆。"}},{"en":"the way that somebody appears or behaves, especially when this is very different from their real feelings or character","cn":"（人的）外貌，外表","g":"[singular]","ex":{"en":"Beneath his confident exterior, he was desperately nervous.","cn":"他表面上自信，内心极度紧张。"}},{"en":"on the outside of something; done or happening outdoors","cn":"外面的；外部的；外表的；户外的","ex":{"en":"exterior walls/surfaces","cn":"外墙；外层表面"},"pos":"adjective"}]}},"explicable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可解释的;可说明的","en":"If something is explicable, it can be explained and understood because it is logical or sensible.","ex":{"en":"The older I grow, the stranger and less explicable the world appears to me.","cn":"年龄越大，世界对我而言就变得越陌生、越难理解。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to be easily understood or explained","cn":"易于理解的﹔容易解释的"}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. easily, readily The sudden increase in sales is easily explicable. | entirely, perfectly, wholly His behaviour is entirely explicable. ","PREP. by The delay is partly explicable by the roadworks. | in terms of The differences in the children's achievements were not wholly expli"]},"media":{"uk":"media/ldoce/hwd/bre/a/explicable0205.mp3","us":"media/ldoce/hwd/ame/e/explicable.mp3"},"examples":[{"en":"His behaviour is only explicable in terms of (= because of) his recent illness.","cn":"他的行为只能用他最近患病来解释。"},{"en":"The success of the Revolution is explicable in terms of the weakness of the king’s government.","cn":"革命的成功可归因于国王政府的软弱。"}],"oxford":{"phon":"ɪkˈsplɪkəbl","pos":"adjective","senses":[{"en":"that can be explained or understood","cn":"可解释；可说明；可理解","ex":{"en":"His behaviour is only explicable in terms of (= because of) his recent illness.","cn":"他的行为只能用他最近患病来解释。"}}]}},"exclaim":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（由于激动、震惊、愤怒等）突然呼喊，惊叫，大声喊","en":"Writers sometimes use exclaim to show that someone is speaking suddenly, loudly, or emphatically, often because they are excited, shocked, or angry.","ex":{"en":"'He went back to the lab', Iris exclaimed impatiently","cn":"“他回实验室去了，”艾里斯不耐烦地大声说。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The verb exclaim is from the Latin word exclamare , which means \"to cry out.\" The English meaning is similar, to cry out, but with the added element of a strong emotion such as fear, joy, surprise."}]},"collocations":{"phrases":["ADV. loudly, softly | angrily, indignantly | helplessly, weakly | triumphantly | suddenly","PREP. at, in They exclaimed in horror at the price. | over standing in front of shop windows exclaiming over the beautiful clothes | with Sh"]},"media":{"uk":"media/ldoce/hwd/bre/2/exclaim0205.mp3","us":"media/ldoce/hwd/ame/9/exclaim.mp3"},"examples":[{"en":"She opened her eyes and exclaimed in delight at the scene.","cn":"看到这情景，她瞪着眼睛，高兴得大叫起来。"},{"en":"‘It isn't fair!’, he exclaimed angrily. “","cn":"这不公平！”他气愤地喊道。"}],"oxford":{"phon":"ɪkˈskleɪm","pos":"verb","senses":[{"en":"to say something suddenly and loudly, especially because of strong emotion or pain","cn":"（尤因强烈的情感或痛苦而）惊叫，呼喊","ex":{"en":"She opened her eyes and exclaimed in delight at the scene.","cn":"看到这情景，她瞪着眼睛，高兴得大叫起来。"}}]}},"exit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出口；通道","en":"The exit is the door through which you can leave a public building.","ex":{"en":"He picked up the case and walked towards the exit","cn":"他提起箱子，向出口走去。"}},{"pos":"N-COUNT 可数名词","cn":"（高速路、公路等的）出口，换道口","en":"An exit on a motorway or highway is a place where traffic can leave it.","ex":{"en":"Take the A422 exit at Old Stratford.","cn":"从旧斯特拉福特的A422号出口出来。"}},{"pos":"N-COUNT 可数名词","cn":"离开;离去","en":"If you refer to someone's exit, you are referring to the way that they left a room or building, or the fact that they left it.","ex":{"en":"I made a hasty exit and managed to open the gate.","cn":"我匆忙离开并设法打开了大门。"}},{"pos":"N-COUNT 可数名词","cn":"离开;退出;退场","en":"If you refer to someone's exit, you are referring to the way that they left a situation or activity, or the fact that they left it.","ex":{"en":"...after England's exit from the European Championship","cn":"英格兰退出欧锦赛后"}},{"pos":"VERB 动词","cn":"出去;离去;退出","en":"If you exit from a room or building, you leave it.","ex":{"en":"She exits into the tropical storm","cn":"她走了出去，消失在热带风暴中。"}},{"pos":"VERB 动词","cn":"退出，停止运行（计算机程序、系统等）","en":"If you exit a computer program or system, you stop running it.","ex":{"en":"I can open other applications without having to exit WordPerfect.","cn":"我不必退出WordPerfect程序就可以打开其他应用程序。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a door or space through which you can leave a public room, building etc","cn":"出口﹔通道"},{"en":"when you leave a room or building","cn":"离开〔房间或建筑物〕"},{"en":"a place where vehicles can leave a road such as a motorway , and join another road 〔","cn":"公路的〕出口"}]},"collocations":{"phrases":["ADJ. front, rear, side | emergency, fire | the nearest She headed for the nearest exit.","VERB + EXIT head for, make for | bar, block Do not leave bags lying around which could block the emergency exits.","EXIT + NOUN door, gate, route","PREP. to/towards the ~ They moved to the exits. 2 act of leaving","ADJ. fast, hurried, quick, swift | dignified | early her early exit from the tournament, in only the second round | mass","VERB + EXIT make She turned on her heel and made what she hoped was a dignified exit.","EXIT + NOUN visa","PREP. ~ from a mass exit of members from the party 3 for traffic"]},"media":{"uk":"media/ldoce/hwd/bre/1/exit_n0205.mp3","us":"media/ldoce/hwd/ame/f/exit1.mp3"},"examples":[{"en":"There is a fire exit on each floor of the building.","cn":"这栋建筑每层楼都有个消防通道。"},{"en":"As the actors exited the stage the lights went on.","cn":"演员们退场时灯光便亮了起来。"}],"oxford":{"phon":"ˈeksɪt","pos":"noun","senses":[{"en":"a way out of a public building or vehicle","cn":"出口；通道；太平门","ex":{"en":"Where's the exit?","cn":"出口在哪儿？"}},{"en":"a place where vehicles can leave a road to join another road","cn":"（车辆可以从一道路驶出进入另一道路的）出口，出路","ex":{"en":"Leave the roundabout at the second exit.","cn":"在第二个出口处驶离环岛。"}},{"en":"an act of leaving, especially of an actor from the stage","cn":"退出；离去；（尤指演员）退场","ex":{"en":"The heroine made her exit to great applause.","cn":"女主角在热烈的掌声中退场。"}},{"en":"the fact of leaving a particular situation or activity","cn":"退出；离开","ex":{"en":"They were disappointed by the team's early exit from the World Cup.","cn":"他们对该队早早离开世界杯感到失望。"}},{"en":"to go out; to leave a building, stage, vehicle, etc.","cn":"出去；离去；退场","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"The bullet entered her back and exited through her chest.","cn":"子弹从她背部射入，穿胸而出。"},"pos":"verb"},{"en":"to finish using a computer program","cn":"退出（计算机程序）","g":"[intransitive, transitive]","ex":{"en":"To exit from this page, press the return key.","cn":"退出本页面按返回键。"},"pos":"verb"},{"en":"used in the instructions printed in a play to say that an actor must leave the stage","cn":"（剧本里的指示）退场，退下","g":"[intransitive]","ex":{"en":"Exit Macbeth.","cn":"麦克佩斯退场。"},"pos":"verb"}]}},"exhaust":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使精疲力竭;使疲惫不堪","en":"If something exhausts you, it makes you so tired, either physically or mentally, that you have no energy left.","ex":{"en":"Don't exhaust him","cn":"不要把他累坏了。"}},{"pos":"VERB 动词","cn":"耗尽;用光","en":"If you exhaust something such as money or food, you use or finish it all.","ex":{"en":"We have exhausted all our material resources","cn":"我们已经耗尽了所有的物资。"}},{"pos":"VERB 动词","cn":"详尽地讨论;详尽无遗地论述","en":"If you have exhausted a subject or topic, you have talked about it so much that there is nothing more to say about it.","ex":{"en":"She and Chantal must have exhausted the subject of babies and clothes.","cn":"她和尚塔尔肯定已经充分讨论过宝宝和衣服的问题。"}},{"pos":"N-COUNT 可数名词","cn":"排气管","en":"The exhaust or the exhaust pipe is the pipe which carries the gas out of the engine of a vehicle."},{"pos":"N-UNCOUNT 不可数名词","cn":"尾气;废气","en":"Exhaust is the gas or steam that is produced when the engine of a vehicle is running.","ex":{"en":"...the exhaust from a car engine","cn":"汽车发动机排放的尾气"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to eat or drink all of something, so that there is none left","cn":""},{"en":"if you run out of something that you need, there is none left","cn":""},{"en":"to use all of something, especially when it is difficult to get more of it","cn":""}]},"vocab":{"pos":"1 v 2 v 3 n v","senses":[{"en":"The noun exhaust refers to what comes out of your car's tailpipe. It consists of the burned gases and particulate matter that are created by the engine. As a verb, the word exhaust means to use something up, such as a food supply or your energy."}]},"collocations":{"phrases":["ADV. absolutely, completely, totally, utterly The swimming had completely exhausted him. | emotionally, mentally, physically The experience ","ADV. completely, totally | almost, nearly The funds are nearly exhausted. | quickly, rapidly Their limited resources were quickly exhausted."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdeexhaust.mp3","us":"media/ldoce/hwd/ame/c/exhaust1.mp3"},"examples":[{"en":"There's no need to exhaust yourself clearing up — we'll do it.","cn":"你不必筋疲力尽地收拾，我们会做的。"},{"en":"Within three days they had exhausted their supply of food.","cn":"他们在三天之内就把所有粮食吃光了。"}],"oxford":{"phon":"ɪɡˈzɔːst","pos":"noun","senses":[{"en":"waste gases that come out of a vehicle, an engine or a machine","cn":"（车辆、发动机或机器排出的）废气","g":"[uncountable]","ex":{"en":"car exhaust fumes/emissions","cn":"汽车排出的废气；汽车排放物"}},{"en":"the system in a vehicle through which exhaust gases come out","cn":"（汽车的）排气管，排气系统","g":"[countable]","ex":{"en":"My car needs a new exhaust.","cn":"我的汽车需要一根新排气管。"}},{"en":"to make somebody feel very tired","cn":"使筋疲力尽；使疲惫不堪","ex":{"en":"Even a short walk exhausted her.","cn":"走不了几步她就会疲惫不堪。"},"pos":"verb"},{"en":"to use all of something so that there is none left","cn":"用完；花光；耗尽","ex":{"en":"Within three days they had exhausted their supply of food.","cn":"他们在三天之内就把所有粮食吃光了。"},"pos":"verb"},{"en":"to talk about or study a subject until there is nothing else to say about it","cn":"详尽讨论（或研究）","ex":{"en":"I think we've exhausted that particular topic.","cn":"我认为我们已把那个题目讨论透彻了。"},"pos":"verb"}]}},"exorbitant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过度的;过分的；过高的","en":"If you describe something such as a price or fee as exorbitant, you are emphasizing that it is much greater than it should be.","ex":{"en":"Exorbitant housing prices have created an acute shortage of affordable housing for the poor.","cn":"过高的房价已经造成了穷人能够买得起的住房严重短缺。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"costing a lot of money","cn":""},{"en":"costing a lot of money. You use high about rents/fees/prices/costs. Don’t use expensive with these words","cn":""},{"en":"expensive compared to the usual price","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective exorbitant when you want to describe something that is really just too much! You'll often hear people griping about exorbitant bank fees or exorbitant interest rates."}]},"collocations":{"phrases":["VERBS be, seem","ADV. grossly | quite The hotel charges quite exorbitant prices. | pretty"]},"media":{"uk":"media/ldoce/hwd/bre/1/exorbitant0205.mp3","us":"media/ldoce/hwd/ame/b/exorbitant.mp3"},"examples":[{"en":"Prices are exorbitantly high in this shop.","cn":"这家商店的价格高得离谱。"},{"en":"exorbitant costs/fares/fees/prices/rents","cn":"过高的花费/交通费/收费/价格/租金"}],"oxford":{"phon":"ɪɡˈzɔːbɪtənt","pos":"adjective","senses":[{"en":"much too high","cn":"过于昂贵的；过高的","ex":{"en":"exorbitant costs/fares/fees/prices/rents","cn":"过高的花费／交通费／收费／价格／租金"}}]}},"exemplify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"作为…的例证;是…的典范","en":"If a person or thing exemplifies something such as a situation, quality, or class of things, they are a typical example of it.","ex":{"en":"The room's style exemplifies Conran's ideal of 'beauty and practicality'.","cn":"那个房间的风格是体现康兰“美观和实用”观念的典范。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"something that you mention because it is typical of the kind of thing that you are talking about","cn":""},{"en":"an example of something that happens, especially something bad","cn":""},{"en":"an example of a particular kind of situation or event","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you exemplify something, you're the perfect example of it. Say you wear frilly shirts, knee-high boots, and black eye-make-up — you exemplify the fashion world's obsession with pirates."}]},"collocations":{"phrases":["ADV. clearly, well"]},"media":{"uk":"media/ldoce/hwd/bre/c/exemplify0205.mp3","us":"media/ldoce/hwd/ame/0/exemplify.mp3"},"examples":[{"en":"Her early work is exemplified in her book, ‘A Study of Children's Minds’.","cn":"她的《儿童思维研究》一书是她早期的代表作。"},{"en":"She exemplified each of the points she was making with an amusing anecdote.","cn":"她的每一个论点都用一个佚闻趣事来说明。"}],"oxford":{"phon":"ɪɡˈzemplɪfaɪ","pos":"verb","senses":[{"en":"to be a typical example of something","cn":"是…的典型（或典范、榜样）","ex":{"en":"Her early work is exemplified in her book, ‘A Study of Children's Minds’.","cn":"她的《儿童思维研究》一书是她早期的代表作。"}},{"en":"to give an example in order to make something clearer","cn":"举例说明","ex":{"en":"She exemplified each of the points she was making with an amusing anecdote.","cn":"她的每一个论点都用一个逸闻趣事来说明。"}}]}},"exception":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"例外;除外","en":"An exception is a particular thing, person, or situation that is not included in a general statement, judgment, or rule.","ex":{"en":"Few guitarists can sing as well as they can play; Eddie, however, is an exception","cn":"很少有吉他手唱歌像弹吉他那么好，然而埃迪是个例外。"}},{"pos":"PHRASE 短语","cn":"不例外；无例外","en":"If you make a general statement, and then say that something or someone is no exception, you are emphasizing that they are included in that statement.","ex":{"en":"Marketing is applied to everything these days, and books are no exception","cn":"现在市场营销已无处不在，图书也不例外。"}},{"pos":"PHRASE 短语","cn":"证明普遍性的例外；规则必有例外","en":"If you are making a general statement and you say that something is the exception that proves the rule, you mean that although it seems to contradict your statement, in most other cases your statement will be true.","ex":{"en":"Wine-making and accountants don't usually go together, but Thierry Hasard is an exception that proves the rule.","cn":"酿酒和会计通常不搭边，而蒂埃里·阿萨尔却是普遍中的例外。"}},{"pos":"PHRASE 短语","cn":"反感;厌恶","en":"If you take exception to something, you feel offended or annoyed by it, usually with the result that you complain about it.","ex":{"en":"He also took exception to having been spied on","cn":"他也讨厌被暗中监视。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除…之外；不包括…在内","en":"You use with the exception of to introduce a thing or person that is not included in a general statement that you are making.","ex":{"en":"Yesterday was a day off for everybody, with the exception of Lawrence","cn":"昨天所有人都放一天假，劳伦斯除外。"}},{"pos":"PHRASE 短语","cn":"毫无例外；无一例外","en":"You use without exception to emphasize that the statement you are making is true in all cases.","ex":{"en":"The vehicles are without exception old, rusty and dented","cn":"那些车辆一律都很破旧，锈迹斑斑，布满凹痕。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is not included in a general statement, or does not do what most others in the same situation do","cn":""},{"en":"all the things or people in a group","cn":""},{"en":"all the things in a group, or all the things that someone says or does","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An exception is something that is left out or not done on purpose. An exception to a rule does not follow that rule."}]},"collocations":{"phrases":["ADJ. conspicuous, important, major, notable, obvious, significant, striking Most industries have suffered badly in the recession, but there ","VERB + EXCEPTION make No parking is allowed, but an exception is made for disabled drivers.","PREP. with the ~ of The whole of the island was flooded with the exception of a small area in the north. | without ~ Without exception, all ","PHRASES be no exception The weather had been rainy for days, and the day of the race was no exception. | be the exception rather than the ru"]},"media":{"uk":"media/ldoce/hwd/bre/d/exception0205.mp3","us":"media/ldoce/hwd/ame/0/exception.mp3"},"examples":[{"en":"Most electronics companies have not done well this year, but ours is the exception that proves the rule.","cn":"今年多数电子公司都不景气，而我们公司却是普遍中的例外。"},{"en":"I take great exception to the fact that you told my wife before you told me.","cn":"你还没告诉我就先对我妻子讲了，为此我非常生气。"}],"oxford":{"phon":"ɪkˈsepʃn","pos":"noun","senses":[{"en":"a person or thing that is not included in a general statement","cn":"一般情况以外的人（或事物）；例外","ex":{"en":"Most of the buildings in the town are modern, but the church is an exception.","cn":"城里大多是现代建筑，不过教堂是个例外。"}},{"en":"a thing that does not follow a rule","cn":"规则的例外；例外的事物","ex":{"en":"Good writing is unfortunately the exception rather than the rule (= it is unusual).","cn":"可惜优秀的文字作品真是可遇不可求。"}}]}},"exponent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阐述者;拥护者;倡导者","en":"An exponent of an idea, theory, or plan is a person who supports and explains it, and who tries to persuade other people that it is a good idea.","ex":{"en":"...a leading exponent of test-tube baby techniques.","cn":"试管婴儿技术的主要倡导者"}},{"pos":"N-COUNT 可数名词","cn":"擅长者;大师;行家","en":"An exponent of a particular skill or activity is a person who is good at it.","ex":{"en":"...the great exponent of expressionist dance, Kurt Jooss.","cn":"表现主义舞蹈的杰出代表人物，库尔特·约斯"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an exponent of an idea, belief etc tries to explain it and persuade others that it is good or useful 〔","cn":"想法﹑信仰等的〕倡导者﹐鼓吹者"},{"en":"an exponent of a particular skill, idea, or activity is someone who is good at it","cn":"能手﹐大师"},{"en":"a sign written above and to the right of a number or letter to show how many times that quantity is to be multiplied by itself","cn":"指数﹐幂"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An exponent is a person who is a big promoter of something. Are you an exponent of the four-day school and work week?"}]},"collocations":{"phrases":["ADJ. chief, foremost, leading, main, principal | great, outstanding | famous, well-known | early He was an early exponent of multimedia in t","PREP. ~ of a leading exponent of the Japanese flute"]},"media":{"uk":"media/ldoce/hwd/bre/7/exponent0205.mp3","us":"media/ldoce/hwd/ame/c/exponent.mp3"},"examples":[{"en":"She was a leading exponent of free trade during her political career","cn":"她从政期间是自由贸易的主要倡导者。"},{"en":"the most famous exponent of the art of mime","cn":"最著名的哑剧表演艺术大师"}],"oxford":{"phon":"ɪkˈspəʊnənt","pos":"noun","senses":[{"en":"a person who supports an idea, theory, etc. and persuades others that it is good","cn":"（观点、理论等的）拥护者，鼓吹者，倡导者","ex":{"en":"She was a leading exponent of free trade during her political career.","cn":"她从政期间是自由贸易的主要倡导者。"}},{"en":"a person who is able to perform a particular activity with skill","cn":"（某种活动的）能手，大师","ex":{"en":"the most famous exponent of the art of mime","cn":"最著名的哑剧表演艺术大师"}},{"en":"a raised figure or symbol that shows how many times a quantity must be multiplied by itself, for example the figure 4 in a4","cn":"指数","lab":"mathematics"}]}},"extortion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敲诈罪;勒索罪","en":"Extortion is the crime of obtaining something from someone, especially money, by using force or threats.","ex":{"en":"He has been charged with extortion and abusing his powers.","cn":"他被控犯有敲诈勒索罪和滥用职权罪。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone give you something such as money or information by persuading them, tricking them, or threatening them","cn":""},{"en":"to illegally force someone to give you money by frightening or threatening them","cn":""},{"en":"to force someone to give you money or do what you want, by threatening to tell people about something that they want to keep secret","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Extortion means forcing someone into giving you something through threats. A bully who tells kids he'll beat them up if they don't give him their lunch money is guilty of extortion ."}]},"collocations":{"phrases":["ADJ. attempted | alleged","EXTORTION + NOUN racket He was known for running a brutal extortion racket. • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/d/extort0205.mp3","us":"media/ldoce/hwd/ame/e/extort.mp3"},"examples":[{"en":"He was arrested and charged with extortion.","cn":"他因敲诈勒索罪被拘捕和控告。"},{"en":"Rebels extorted money from local villagers.","cn":""}],"oxford":{"phon":"ɪkˈstɔːʃn","pos":"noun","senses":[{"en":"the crime of making somebody give you something by threatening them","cn":"敲诈；勒索；强夺","ex":{"en":"He was arrested and charged with extortion.","cn":"他被逮捕并被指控犯了敲诈勒索罪。"}}]}},"excursion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"短途旅行;远足","en":"You can refer to a short journey as an excursion, especially if it is made for pleasure or enjoyment. →see usage note at:","ex":{"en":"In Bermuda, Sam's father took him on an excursion to a coral barrier.","cn":"在百慕大，萨姆的父亲带他到附近的珊瑚礁去游玩。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指旅行社组织的）短途旅游","en":"An excursion is a trip or visit to an interesting place, especially one that is arranged or recommended by a holiday company or tourist organization.","ex":{"en":"We also recommend a full day optional excursion to the Upper Douro","cn":"我们还推荐去杜罗河上游的短途自选一日游。"}},{"pos":"N-COUNT 可数名词","cn":"尝试;涉猎","en":"If you describe an activity as an excursion into something, you mean that it is an attempt to develop or understand something new that you have not experienced before.","ex":{"en":"...Radio 3's latest excursion into ethnic music, dance and literature","cn":"第三广播台最近开始涉及有关少数民族音乐、舞蹈和文学的节目"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when you travel from one place to another – used especially about travelling a long distance, or travelling somewhere regularly","cn":""},{"en":"a journey to visit a place","cn":""},{"en":"a journey for pleasure, during which you visit several different towns, areas etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An excursion is taken more for pleasure than for practical reasons. Your business trip, when you spent most of the week waiting in airports and adjusting to different time zones, does not count as an excursion ."}]},"collocations":{"phrases":["ADJ. brief, short | day, evening, full-day, half-day, weekend | annual | organized | boat, coach, train | holiday, shopping, sightseeing","VERB + EXCURSION go on, make We decided to make an all-day excursion to the island. | arrange, organize | take sb on","PREP. ~ to He took us on an excursion to the ruined city."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeexcursion.mp3","us":"media/ldoce/hwd/ame/b/excursion.mp3"},"examples":[{"en":"After a brief excursion into drama, he concentrated on his main interest, which was poetry.","cn":"他短暂涉猎过戏剧之后便把全部精力投入到他的主要兴趣 — 诗歌中去了。"},{"en":"They've gone on an excursion to York.","cn":"他们到约克旅游去了。"}],"oxford":{"phon":"ɪkˈskɜːʃn","pos":"noun","senses":[{"en":"a short journey made for pleasure, especially one that has been organized for a group of people","cn":"（尤指集体）远足，短途旅行","lab":"British English","ex":{"en":"They've gone on an excursion to York.","cn":"他们到约克旅游去了。"}},{"en":"a short period of trying a new or different activity","cn":"（短期的）涉足，涉猎","lab":"formal","ex":{"en":"After a brief excursion into drama, he concentrated on his main interest, which was poetry.","cn":"他短暂涉猎戏剧之后便把全部精力投入到他的主要兴趣——诗歌中去了。"}}]}},"expedient":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"权宜之计;应急措施","en":"An expedient is an action that achieves a particular purpose, but may not be morally right.","ex":{"en":"Surgical waiting lists were reduced by the simple expedient of striking off all patients awaiting varicose vein operations","cn":"采取了将所有等待进行静脉曲张手术的病人从名单上删除的简单做法，这一权宜之计使得外科手术等待名单得以缩减。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的;方便的;权宜之计的","en":"If it is expedient to do something, it is useful or convenient to do it, even though it may not be morally right.","ex":{"en":"Governments frequently ignore human rights abuses in other countries if it is politically expedient to do so.","cn":"如果在政治上对自己有利，各国政府经常忽视其他国家侵犯人权的行为。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"helping you to deal with a problem quickly and effectively although sometimes in a way that is not morally right","cn":"便捷有效(但不道德)的﹔权宜的"},{"en":"a quick and effective way of dealing with a problem","cn":"应急对策﹔权宜之计"}]},"vocab":{"pos":"adj n","senses":[{"en":"The adjective expedient describes something that provides an easy way to achieve a goal or result, but it's not necessarily a moral solution."}]},"collocations":{"phrases":["VERBS be, prove | become | consider sth, deem sth, think sth | find sth The government found it expedient to relax censorship a little.","ADV. politically"]},"media":{"uk":"media/ldoce/hwd/bre/6/expedient_n0205.mp3","us":"media/ldoce/hwd/ame/6/expedient1.mp3"},"examples":[{"en":"The disease was controlled by the simple expedient of not allowing anyone to leave the city.","cn":"采取了禁止所有人出城的简单应急办法使疾病得到了控制。"},{"en":"The government has clearly decided that a cut in interest rates would be politically expedient.","cn":"政府显然认为削减利率是政治上的权宜之计。"}],"oxford":{"phon":"ɪkˈspiːdiənt","pos":"noun","senses":[{"en":"an action that is useful or necessary for a particular purpose, but not always fair or right","cn":"权宜之计；应急办法","ex":{"en":"The disease was controlled by the simple expedient of not allowing anyone to leave the city.","cn":"采取了禁止所有人出城的简单应急办法，使疾病得到了控制。"}},{"en":"useful or necessary for a particular purpose, but not always fair or right","cn":"得当；可取；合宜；权宜之计","ex":{"en":"The government has clearly decided that a cut in interest rates would be politically expedient.","cn":"政府显然认为削减利率是政治上的权宜之计。"},"pos":"adjective"}]}},"exclude":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…排除在外;不包括","en":"If you exclude someone from a place or activity, you prevent them from entering it or taking part in it.","ex":{"en":"The Academy excluded women from its classes","cn":"该学院不招收女学生。"}},{"pos":"VERB 动词","cn":"拒绝;阻止","en":"If you exclude something that has some connection with what you are doing, you deliberately do not use it or consider it.","ex":{"en":"They eat only plant foods, and take care to exclude animal products from other areas of their lives","cn":"他们只吃素食，在生活的其他方面也注意拒绝使用动物产品。"}},{"pos":"VERB 动词","cn":"排除…的可能性;对…不予考虑","en":"To exclude a possibility means to decide or prove that it is wrong and not worth considering.","ex":{"en":"I cannot entirely exclude the possibility that some form of pressure was applied to the neck.","cn":"我不能完全排除颈部受到某种压迫的可能性。"}},{"pos":"VERB 动词","cn":"阻挡;拒绝；阻止…进入","en":"To exclude something such as the sun's rays or harmful germs means to prevent them physically from reaching or entering a particular place.","ex":{"en":"This was intended to exclude the direct rays of the sun","cn":"其目的是阻挡直射的太阳光。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately not include someone or something, especially in a way that seems wrong or unfair","cn":""},{"en":"to not include something, especially a piece of information, either deliberately or because you forget","cn":""},{"en":"to not include someone or something, either deliberately or accidentally. Leave out is more common in everyday English than exclude or omit","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Exclude means to leave out — like when the cool kids won't let you in on their game of four-square or the pizza guy leaves your neighborhood out from his delivery zone."}]},"collocations":{"phrases":["ADV. rigorously | altogether, completely, entirely, totally | not absolutely, not wholly The possibility of error cannot be absolutely exclu","VERB + EXCLUDE attempt to, be designed to, purport to, seek to a clause that seeks to exclude liability for death or serious injury | tend t","PREP. from Women were excluded from the council.","PHRASES feel excluded Many local people felt excluded from decisions that affected their own community."]},"media":{"uk":"media/ldoce/hwd/bre/5/exclude0205.mp3","us":"media/ldoce/hwd/ame/6/exclude.mp3"},"examples":[{"en":"( BrE ) Concern is growing over the number of children excluded from school (= not allowed to attend because of bad behaviour).","cn":"对遭学校开除的儿童人数之众，人们越来越表关注。"},{"en":"The police have excluded theft as a motive for the murder.","cn":"警方已排除这起谋杀案中有偷窃的动机。"}],"oxford":{"phon":"ɪkˈskluːd","pos":"verb","senses":[{"en":"to deliberately not include something in what you are doing or considering","cn":"不包括；不放在考虑之列","ex":{"en":"The cost of borrowing has been excluded from the inflation figures.","cn":"通胀数字未包括借贷费用。"}},{"en":"to prevent somebody/something from entering a place or taking part in something","cn":"防止…进入；阻止…参加；把…排斥在外","lab":"British English","ex":{"en":"Women are still excluded from some London clubs.","cn":"伦敦有些俱乐部仍然拒绝妇女参加。"}},{"en":"to decide that something is not possible","cn":"排除（…的可能性）；认为…不可能","ex":{"en":"We should not exclude the possibility of negotiation.","cn":"我们不应该排除谈判的可能性。"}}]}},"exile":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流放;放逐;流亡","en":"If someone is living in exile, they are living in a foreign country because they cannot live in their own country, usually for political reasons.","ex":{"en":"He is now living in exile in Egypt","cn":"他目前流亡埃及。"}},{"pos":"VERB 动词","cn":"放逐;流放;使流亡","en":"If someone is exiled, they are living in a foreign country because they cannot live in their own country, usually for political reasons.","ex":{"en":"His second wife, Hilary, had been widowed, then exiled from South Africa","cn":"他的第二任妻子希拉丽已经成了寡妇，后来又被驱逐出南非。"}},{"pos":"N-COUNT 可数名词","cn":"被流放者;流亡者","en":"An exile is someone who has been exiled."},{"pos":"VERB 动词","cn":"开除;排除;使离开","en":"If you say that someone has been exiled from a particular place or situation, you mean that they have been sent away from it or removed from it against their will.","ex":{"en":"He has been exiled from the first team and forced to play in third team matches","cn":"他被开除出甲级球队，被迫参加丙级球队的比赛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make a foreigner leave a country because they have broken the law, or for political reasons","cn":""},{"en":"if the authorities in a country deport a foreign person or a member of a particular race who is living in that country, they force them to leave","cn":""},{"en":"to officially send someone back to another country where they are believed to have committed a crime, in order to be tried in a court of law","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you are exiled from a place, you must leave and return. Such punishment is called exile . For example, after he was removed from power, Napoleon lived in exile on the island of Elba."}]},"collocations":{"phrases":["ADJ. long | permanent | enforced | self-imposed, voluntary | internal Many spent decades in labour camps or in internal exile.","VERB + EXILE be driven/forced/sent into | flee into, go into The king went into exile after the overthrow of his government. | live in They ","PREP. in ~ She had spent 40 years in exile. | ~ from Dante died in exile from Florence.","PHRASES a place of exile 2 person forced to live in another country","ADJ. political | tax (= a rich person who moves to another country where taxes are lower)","EXILE + VERB return A general amnesty was granted, allowing political exiles to return freely.","PHRASES the recall of exiles, the return of exiles"]},"media":{"uk":"media/ldoce/hwd/bre/2/exile_n0205.mp3","us":"media/ldoce/hwd/ame/e/exile1.mp3"},"examples":[{"en":"He returned after 40 years of exile.","cn":"他流放 40 年后归来。"},{"en":"a tax exile (= a rich person who moves to another country where taxes are lower)","cn":"迁居低税国家的富人"}],"oxford":{"phon":"ˈeksaɪl","pos":"noun","senses":[{"en":"the state of being sent to live in another country that is not your own, especially for political reasons or as a punishment","cn":"流放；流亡；放逐","g":"[uncountable, singular]","ex":{"en":"a place of exile","cn":"流放地"}},{"en":"a person who chooses, or is forced, to live away from his or her own country","cn":"流亡国外者；被流放者；离乡背井者","g":"[countable]","ex":{"en":"political exiles","cn":"政治流亡者"}},{"en":"to force somebody to leave their country, especially for political reasons or as a punishment; to send somebody into exile","cn":"流放；放逐","ex":{"en":"He was exiled to Siberia.","cn":"他被流放到西伯利亚。"},"pos":"verb"}]}},"extinction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（物种的）灭绝","en":"The extinction of a species of animal or plant is the death of all its remaining living members.","ex":{"en":"An operation is beginning to try to save a species of crocodile from extinction","cn":"一项努力拯救一个鳄鱼物种、使其免于灭绝的行动已经开始。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"消亡;消灭;不复存在","en":"If someone refers to the extinction of a way of life or type of activity, they mean that the way of life or activity stops existing.","ex":{"en":"The loggers say their jobs are faced with extinction because of declining timber sales.","cn":"伐木工人说由于木材销量下降，他们的工作恐不复存在。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if something disappears , it stops existing, and cannot be seen any more","cn":""},{"en":"to stop existing, especially because of a sudden or quick process","cn":""},{"en":"if a type of animal or plant becomes extinct , all the animals or plants of that type die, so that the type does not exist any more","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Extinction is when all members of a particular group die. Most often, we use it to discuss animal species. Many fear that the tiger is headed for extinction because of development and hunting."}]},"collocations":{"phrases":["ADJ. mass, total, widespread the mass extinction of the dinosaurs | near, virtual | imminent, impending","VERB + EXTINCTION cause, lead to Modern farming methods have led to the total extinction of many species of wild flowers. | be doomed to, be"]},"media":{"uk":"media/ldoce/hwd/bre/b/extinction0205.mp3","us":"media/ldoce/hwd/ame/c/extinction.mp3"},"examples":[{"en":"We know of several mass extinctions in the earth's history.","cn":"我们知道地球历史上出现过几次大规模的灭绝。"},{"en":"a tribe threatened with extinction/in danger of extinction","cn":"面临消亡威胁/有消亡危险的部落"}],"oxford":{"phon":"ɪkˈstɪŋkʃn","pos":"noun","senses":[{"en":"a situation in which a plant, an animal, a way of life, etc. stops existing","cn":"（植物、动物、生活方式等的）灭绝，绝种，消亡","ex":{"en":"a tribe threatened with extinction/in danger of extinction","cn":"面临消亡威胁／有消亡危险的部落"}}]}},"expose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使暴露;使显露","en":"To expose something that is usually hidden means to uncover it so that it can be seen.","ex":{"en":"Lowered sea levels exposed the shallow continental shelf beneath the Bering Sea","cn":"海平面下降使白令海底部的浅层大陆架暴露出来。"}},{"pos":"VERB 动词","cn":"揭发;揭露","en":"To expose a person or situation means to reveal that they are bad or immoral in some way.","ex":{"en":"The Budget does expose the lies ministers were telling a year ago","cn":"预算案无疑揭穿了部长们一年前所说的谎话。"}},{"pos":"VERB 动词","cn":"使暴露于（险境）;使遭受（危险或不快）","en":"If someone is exposed to something dangerous or unpleasant, they are put in a situation in which it might affect them.","ex":{"en":"They had not been exposed to most diseases common to urban populations","cn":"城市人口中多数常见的疾病他们都没有接触到。"}},{"pos":"VERB 动词","cn":"使受…的影响(或熏陶);使接触","en":"If someone is exposed to an idea or feeling, usually a new one, they are given experience of it, or introduced to it.","ex":{"en":"...local people who've not been exposed to glimpses of Western life before","cn":"过去丝毫未曾见识过西方生活的当地人"}},{"pos":"VERB 动词","cn":"（常因精神或感情失控）暴露性器官，当众露阴","en":"A man who exposes himself shows people his genitals in a public place, usually because he is mentally or emotionally disturbed.","ex":{"en":"Smith admitted indecently exposing himself on Wimbledon Common.","cn":"史密斯承认自己在温布尔登公地当众露阴，有伤风化。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to let someone see something, especially by holding it out in front of them","cn":""},{"en":"to show something to someone very quickly","cn":""},{"en":"to show something to someone, especially so that they can examine it, repair it etc","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v n 4 v","senses":[{"en":"To expose means to uncover or allow to be in the open air. If you take off your coat and expose your bare arms to the terrible cold, your tattoos might freeze off. (Note: We don’t actually know if this is physically possible.)"}]},"collocations":{"phrases":["ADV. completely, fully | briefly | suddenly | deliberately She lifted her chin in a gesture that deliberately exposed the line of her throat","PREP. to These drawings must not be exposed to the air. 2 show the truth","ADV. fully | clearly a report which clearly exposes the weakness of the government's economic policy | publicly He was publicly exposed as a","VERB + EXPOSE threaten to | seek to, try to 3 to sth harmful","ADV. directly | constantly The general public is constantly exposed to radiation. | regularly","PREP. to"]},"media":{"uk":"media/ldoce/hwd/bre/c/expose0205.mp3","us":"media/ldoce/hwd/ame/f/expose1.mp3"},"examples":[{"en":"He threatened to expose the racism that existed within the police force.","cn":"他扬言要把警队内部存在的种族歧视公之于众。"},{"en":"We want to expose the kids to as much art and culture as possible.","cn":"我们想让孩子们尽量受到艺术和文化薰陶。"}],"oxford":{"phon":"ɪkˈspəʊz","pos":"verb","senses":[{"en":"to show something that is usually hidden","cn":"暴露；显露；露出","sc":"show something hidden","ex":{"en":"He smiled suddenly, exposing a set of amazingly white teeth.","cn":"他突然一笑，露出一口雪白的牙齿。"}},{"en":"to tell the true facts about a person or a situation, and show them/it to be dishonest, illegal, etc.","cn":"揭露；揭穿","sc":"show truth","ex":{"en":"He threatened to expose the racism that existed within the police force.","cn":"他扬言要把警队内部存在的种族歧视公之于众。"}},{"en":"to put somebody/something in a place or situation where they are not protected from something harmful or unpleasant","cn":"使面临，使遭受（危险或不快）","sc":"to something harmful","ex":{"en":"This tactic allowed the rebels to attack without the risk of exposing themselves.","cn":"这一战术使叛军能够在不暴露自己的情况下发动攻击。"}},{"en":"to let somebody find out about something by giving them experience of it or showing them what it is like","cn":"使接触；使体验","sc":"give experience","ex":{"en":"We want to expose the kids to as much art and culture as possible.","cn":"我们想让孩子们尽量受到艺术和文化熏陶。"}},{"en":"to allow light into a camera when taking a photograph","cn":"曝光","sc":"photograph"},{"en":"a person who exposes himself or herself, shows their sexual organs in public in a way that is offensive to other people","cn":"当众暴露阴部","sc":"yourself"},{"en":"an account of the facts of a situation, especially when these shock people or have deliberately been kept secret","cn":"（尤指对丑闻或隐秘之事的）揭露，曝光","ex":{"en":"a damning exposé of police corruption","cn":"警察腐败的令人震惊的揭露"},"pos":"noun"}]}},"excise":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"国内货物税;消费税","en":"Excise is a tax that the government of a country puts on particular goods, such as cigarettes and alcoholic drinks, which are produced for sale in its own country.","ex":{"en":"...this year's rise in excise duties","cn":"今年消费税的提高"}},{"pos":"VERB 动词","cn":"切除;删除;消除","en":"If someone excises something, they remove it deliberately and completely.","ex":{"en":"...a personal crusade to excise racist and sexist references in newspapers.","cn":"消除报纸中涉及种族和性别歧视内容的个人努力"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the government tax that is put on the goods that are produced and used inside a country","cn":"国内货物税﹔消费税"},{"en":"excise officer (= someone who collects excise ) excise duty/tax (= the money paid as excise ) excise duty on tobacco","cn":"烟草消费税"},{"en":"to remove or get rid of something, especially by cutting it out","cn":"切除﹔去除"}]},"vocab":{"pos":"1 v 2 n v","senses":[{"en":"An excise tax is a special tax levied on specific products sold within a country. To excise something can also mean to get rid of it. Say, wouldn't it be nice if they would excise the excise taxes?"}]},"collocations":{"phrases":["VERB + EXCISE impose, levy the excise levied on beer and tobacco | pay | increase, raise | cut, reduce","EXCISE + NOUN duty, revenue, tax | licence applications for vehicle excise licences | officer","PREP. ~ on to increase the excise on whisky"]},"media":{"uk":"media/ldoce/hwd/bre/7/excise_n0205.mp3","us":"media/ldoce/hwd/ame/6/l3excise.mp3"},"examples":[{"en":"new excise duties on low-alcohol drinks","cn":"低酒精饮料新的消费税"},{"en":"Certain passages were excised from the book.","cn":"书中某些段落已删去。"}],"oxford":{"phon":"ˈeksaɪz","pos":"noun","senses":[{"en":"a government tax on some goods made, sold or used within a country","cn":"国内货物税；消费税","ex":{"en":"new excise duties on low-alcohol drinks","cn":"低酒精饮料新的消费税"}},{"en":"to remove something completely","cn":"切除；删除","ex":{"en":"Certain passages were excised from the book.","cn":"书中某些段落已删去。"},"pos":"verb"}]}},"expire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"到期;期满;失效","en":"When something such as a contract, deadline, or visa expires, it comes to an end or is no longer valid.","ex":{"en":"He had lived illegally in the United States for five years after his visitor's visa expired.","cn":"在访问签证到期后，他又在美国非法居住了5年。"}},{"pos":"VERB 动词","cn":"气绝;死亡;故去","en":"When someone expires, they die.","ex":{"en":"He endured excruciating agonies before he finally expired.","cn":"在最终离世前他经受了极大的痛苦。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a event, activity, or story ends, it stops happening","cn":""},{"en":"to end – use this about an organized event such as a meeting, party, or lesson, especially when saying what time it ends","cn":""},{"en":"if an event, activity, or period of time is over, it has ended","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"If something — like milk or a free shipping coupon — expires , it is no longer usable or valid. When you expire , you will be dead."}]},"collocations":{"phrases":["VERB + EXPIRE be due to His contract is due to expire at the end of this year."]},"media":{"uk":"media/ldoce/hwd/bre/1/expire0205.mp3","us":"media/ldoce/hwd/ame/1/expire.mp3"},"examples":[{"en":"When does your driving licence expire?","cn":"你的驾照什么时候到期？"},{"en":"His term of office expires at the end of June.","cn":"他的任期六月底届满。"}],"oxford":{"phon":"ɪkˈspaɪə(r)","pos":"verb","senses":[{"en":"to be no longer legally acceptable because the period of time for which it could be used has ended","cn":"（因到期而）失效，终止；到期","g":"[intransitive]","ex":{"en":"When does your driving licence expire?","cn":"你的驾照什么时候到期？"}},{"en":"to end","cn":"届满","g":"[intransitive]","ex":{"en":"His term of office expires at the end of June.","cn":"他的任期六月底届满。"}},{"en":"to die","cn":"逝世；去世；故去","g":"[intransitive]","lab":"literary","ex":{"en":"She had expired while bearing her son.","cn":"她在生下儿子时就断气了。"}}]}},"expanse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"广袤;辽阔;浩瀚","en":"An expanse of something, usually sea, sky, or land, is a very large amount of it.","ex":{"en":"...a vast expanse of grassland.","cn":"广阔的草原"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large continuous area of land, water, or sky","cn":""},{"en":"an area of land or water, especially one that is long and narrow","cn":""},{"en":"a very large area of land of a particular type, for example, an area of forest or farming country","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An expanse is a huge area you can look at all at once. If you climb to the top of a mountains, suggest that your fellow climbers take time to admire the expanse of trees below."}]},"collocations":{"phrases":["ADJ. broad, endless, great, huge, large, vast, wide a vast expanse of sand | barren, bleak, empty a bleak expanse of concrete | flat looking","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/7/expanse0205.mp3","us":"media/ldoce/hwd/ame/e/expanse.mp3"},"examples":[{"en":"a wide/vast expanse of blue sky","cn":"广阔/无垠的蓝天"},{"en":"flat expanses of open farmland","cn":"平坦而辽阔的农田"}],"oxford":{"phon":"ɪkˈspæns","pos":"noun","senses":[{"en":"a wide and open area of something, especially land or water","cn":"一大片，广阔，宽广，浩瀚（尤指陆地或海洋）","ex":{"en":"a wide/vast expanse of blue sky","cn":"广阔的蓝天"}}]}}});
